package com.clanhub;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * What the four boss cards (a drop line's boss, a kill count, a personal best and the Chat Commands answers) take from
 * the bundled boss table: the facts under the title and the wiki page. Pure, no state: the {@link CardTables.BossInfo} in,
 * the pairs and the page out; a boss the table lacks gives no facts and the page built from its name, so its card is the
 * one the line alone gives. The picture is not the table's: the card asks the wiki for its own ({@link WikiPictures}).
 *
 * <p>Choice: a fact is a row only when there is something to say: a boss with no quest has no "Quest" pair, and a raid
 * whose page has no stats has the quest, if any, alone.
 */
final class BossCards
{
	private BossCards()
	{
	}

	/**
	 * The pairs Combat, Hitpoints, Max hit and Quest, in that order, each only when the boss's value for it is not empty;
	 * an empty list for no boss (null).
	 */
	static List<HoverCard.Pair> facts(CardTables.BossInfo info)
	{
		if (info == null)
		{
			return Collections.emptyList();
		}
		final List<HoverCard.Pair> facts = new ArrayList<>(4);
		add(facts, "Combat", info.combat);
		add(facts, "Hitpoints", info.hitpoints);
		add(facts, "Max hit", info.maxHit);
		add(facts, "Quest", info.quest);
		return facts;
	}

	/** The wiki page of the boss's card: the table's page for a boss it knows, else the page built from {@code name}. */
	static String page(CardTables.BossInfo info, String name)
	{
		return info == null || info.wiki.isEmpty() ? InfoCard.pageFor(name) : info.wiki;
	}

	/** The pair of a label and a value with no note, added when the value is not empty. */
	private static void add(List<HoverCard.Pair> facts, String label, String value)
	{
		if (!value.isEmpty())
		{
			facts.add(new HoverCard.Pair(label, value, ""));
		}
	}
}

package com.clanhub;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Optional;
import java.util.function.BooleanSupplier;
import net.runelite.api.ChatMessageType;

/**
 * The reader of the broadcast lines of the clan, guest clan, group ironman and friends chat channels: a drop, a stacked
 * drop, a clue item or a new collection log item. {@link BroadcastLine} finds the item's name in the line and
 * {@link ItemCards} makes the card, so a line gives the item's card, or none when it is not a broadcast or names no item
 * the item manager knows. A drop line that says where the drop came from ("from Duke Sucellus") gives a second card, the
 * boss's, while the "Boss cards" setting is on: a quiet card with the wiki's own picture of the boss (the combat icon
 * until it comes), its combat level, hitpoints, max hit and quest from the {@link CardTables}, and the wiki's first
 * paragraph.
 *
 * <p>Choice: the boss card is given even when the item gives none (an unknown name), because the line still says where
 * the drop came from; the list is the item card, then the boss card, the order their words stand in the line.
 *
 * <p>Choice: a boss the table lacks, or a table that has not loaded, gives the card as before: no facts, and the wiki's
 * picture, which every name is asked for, the combat icon behind it.
 */
final class BroadcastItemReader implements LineReader
{
	private final ItemCards itemCards;
	private final BooleanSupplier bossCards;
	private final CardTables tables;

	/**
	 * @param itemCards makes the item card
	 * @param bossCards whether the "Boss cards" setting is on, asked for each line
	 * @param tables the bosses' facts, which may not have loaded yet
	 */
	BroadcastItemReader(ItemCards itemCards, BooleanSupplier bossCards, CardTables tables)
	{
		this.itemCards = itemCards;
		this.bossCards = bossCards;
		this.tables = tables;
	}

	@Override
	public List<HoverCard> read(ChatMessageType type, String message)
	{
		final Optional<BroadcastLine.ItemMention> found = BroadcastLine.parse(type, message);
		if (!found.isPresent())
		{
			return Collections.emptyList();
		}
		final BroadcastLine.ItemMention mention = found.get();
		final List<HoverCard> cards = new ArrayList<>(2);
		final HoverCard card = itemCards.forName(mention.name, mention.quantity, mention.text, mention.start,
			mention.end);
		if (card != null)
		{
			cards.add(card);
		}
		if (mention.source != null && bossCards.getAsBoolean())
		{
			cards.add(bossCard(mention.source, mention.text, mention.sourceStart, mention.sourceEnd, tables));
		}
		return cards;
	}

	/**
	 * The quiet card for the boss, monster, raid or chest a drop line names: its name for the title, the boss's facts for
	 * its row ({@link BossCards#facts}, none for a boss {@code tables} lacks), no notes, its wiki page, the wiki's own
	 * picture of that page and the combat icon behind it until the picture comes. Quiet, so its words keep the line's own
	 * colour and show themselves only under the mouse; the item stays the line's one blue word. The {@link OwnLineReader} makes the player's own drop
	 * lines' boss card the same way.
	 *
	 * @param tables the bosses' table, which may not have loaded yet
	 */
	static HoverCard bossCard(String source, String line, int start, int end, CardTables tables)
	{
		final CardTables.BossInfo info = tables.boss(source);
		return new InfoCard(source, BossCards.facts(info), Collections.<String>emptyList(), BossCards.page(info, source),
			line, start, end, SkillSprites.spriteOf("Combat"), -1, false, true);
	}
}

package com.clanhub;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.ChatMessageType;
import net.runelite.api.gameval.ItemID;

/**
 * The reader of the broadcast lines of the clan, guest clan, group ironman and friends chat channels that are about
 * something other than an item the {@link BroadcastItemReader} knows: a raid's special loot (an item card, through
 * {@link ItemCards}), a quest, a combat achievement task, a pet, a level, an XP milestone, a diary tier and a personal
 * best; and, from the player's own game lines, a boss kill count. The sentences are the research's
 * ({@code docs/data/broadcasts.md}, section 3) and are matched as they stand once the tags and a combat achievement
 * line's {@code CA_ID:<n>|} are taken off ({@link ChatText#plain}), the text the offsets index; the first kind that
 * matches wins. What the wiki says of a quest, task, pet or diary comes from the {@link CardTables}; for a name the table
 * does not know, or before it has loaded, the card is the plain one the line alone gives. On a level or XP line the
 * phrase is the card ("Smithing level 99", "200,000,000 XP in Cooking"): one card, over the phrase, and a quiet one,
 * whose words the chat does not colour; a level line of a skill the table knows gives the card of what is new at that
 * level, else the plain level card. A combat level line and a total level line carry nothing of their own and give no
 * card. A pet's picture is its item, whose id the table gives, else {@link ItemCards#idOf} finds by the name. A
 * personal best and a kill count name a boss: when the table knows it the card shows the boss's combat level,
 * hitpoints, max hit and quest after its first fact (the time, the count), and the picture is the wiki's own of the
 * boss's page, with the clue watch (a personal best) or the combat icon (a kill count) behind it until it comes. The
 * chat text is never rewritten.
 */
final class BroadcastKindReader implements LineReader
{
	/** "Player received special loot from a raid: Twisted bow." */
	private static final Pattern RAID = Pattern.compile(
		"^(?<player>.+?) received special loot from a raid: (?<item>.+?)\\.?$");
	/** "Klar has completed a quest: Dragon Slayer II" */
	private static final Pattern QUEST = Pattern.compile("^(?<player>.+?) has completed a quest: (?<quest>.+)$");
	/** "CA_ID:279|Klar has completed a Master combat task: Perfect Zulrah (5 points)." */
	private static final Pattern CA_TASK = Pattern.compile(
		"^(?<player>.+?) has completed an? (?<tier>Easy|Medium|Hard|Elite|Master|Grandmaster) combat task: (?<task>.+?)"
			+ "(?: \\((?<points>\\d+) points?\\))?\\.?$", Pattern.CASE_INSENSITIVE);
	/** "Clipper has a funny feeling like he's being followed: Pet snakeling at 2,678 killcount." */
	private static final Pattern PET_FOLLOWED = Pattern.compile(
		"^(?<player>.+?) has a funny feeling like (?:he|she|they)(?:'s|'re| would have) (?:being|been) followed: "
			+ "(?<pet>.+?)(?: at (?<count>[\\d,]+) (?<unit>.+?))?\\.?$");
	/** "Dash Inc feels something weird sneaking into his backpack: Heron at 8,426,283 XP." */
	private static final Pattern PET_BACKPACK = Pattern.compile(
		"^(?<player>.+?) feels something weird sneaking into (?:his|her|their) backpack: "
			+ "(?<pet>.+?)(?: at (?<count>[\\d,]+) (?<unit>.+?))?\\.?$");
	/** "ClanMate feels like she's acquired something special: Abyssal orphan" */
	private static final Pattern PET_SPECIAL = Pattern.compile(
		"^(?<player>.+?) feels like (?:he|she|they)(?:'s|'ve| has| have) acquired something special: (?<pet>.+?)\\.?$");
	/**
	 * "Th3TRiPPyOn3 has reached Defence level 70."; a combat level line matches too, and so does a total level line that
	 * says "the highest possible", and both give no card.
	 */
	private static final Pattern LEVEL = Pattern.compile(
		"^(?<player>.+?) has reached (?:the highest possible )?(?<skill>[A-Za-z]+) level(?: of)? (?<level>\\d+)[.!]?$");
	/** "Marsel has reached 200,000,000 XP in Cooking." */
	private static final Pattern XP = Pattern.compile(
		"^(?<player>.+?) has reached (?<xp>[\\d,]+) XP in (?<skill>[A-Za-z]+)[.!]?$");
	/** "Player has completed the Elite Ardougne diary." */
	private static final Pattern DIARY = Pattern.compile(
		"^(?<player>.+?) has completed the (?<tier>Easy|Medium|Hard|Elite) (?<area>.+?) diary\\.?$");
	/** "Player has achieved a new Vorkath personal best: 2:28" */
	private static final Pattern PB = Pattern.compile(
		"^(?<player>.+?) has achieved a new (?<activity>.+?) personal best: "
			+ "(?<time>\\d+(?::\\d+)+(?:\\.\\d+)?)\\.?$");
	/** The player's own "Your King Black Dragon kill count is: 420." */
	private static final Pattern OWN_KC = Pattern.compile(
		"^Your (?<boss>.+?) (?<kind>kill|chest|completion|harvest|success|opened|lap|Total Ticket) ?count is: ?"
			+ "(?<count>[\\d,]+)\\.?$", Pattern.CASE_INSENSITIVE);

	/** An {@code @colour@} macro the game puts in a name. */
	private static final Pattern MACRO = Pattern.compile("@[^@\\s]+@");

	/** The combat achievement tiers in order; a tier's index is added to the first sword's sprite. */
	private static final List<String> TIERS = Arrays.asList("Easy", "Medium", "Hard", "Elite", "Master", "Grandmaster");

	private final CardTables tables;
	private final ItemCards itemCards;

	BroadcastKindReader(CardTables tables, ItemCards itemCards)
	{
		this.tables = tables;
		this.itemCards = itemCards;
	}

	/**
	 * The card for the thing a line names, or none. The four broadcast channels' lines are tried against the kinds in
	 * the order raid loot, quest, combat task, the three pet shapes, level, XP, diary, personal best, the first match
	 * giving the one card; a {@code GAMEMESSAGE} line is tried against the kill count only; any other type, a line that
	 * is none of these, and a combat level or total level line (which the level pattern matches and which gets no card),
	 * gives an empty list.
	 */
	@Override
	public List<HoverCard> read(ChatMessageType type, String message)
	{
		if (message == null)
		{
			return Collections.emptyList();
		}
		if (type == ChatMessageType.GAMEMESSAGE)
		{
			final String plain = ChatText.plain(message);
			final Matcher kills = OWN_KC.matcher(plain);
			return kills.matches() ? one(killCount(kills, plain)) : Collections.<HoverCard>emptyList();
		}
		if (!isBroadcast(type))
		{
			return Collections.emptyList();
		}
		final String plain = ChatText.plain(message);
		Matcher found = RAID.matcher(plain);
		if (found.matches())
		{
			return one(itemCards.forName(found.group("item"), 1, plain, found.start("item"), found.end("item")));
		}
		found = QUEST.matcher(plain);
		if (found.matches())
		{
			return one(quest(found, plain));
		}
		found = CA_TASK.matcher(plain);
		if (found.matches())
		{
			return one(task(found, plain));
		}
		found = PET_FOLLOWED.matcher(plain);
		if (found.matches())
		{
			return one(pet(found, plain, true));
		}
		found = PET_BACKPACK.matcher(plain);
		if (found.matches())
		{
			return one(pet(found, plain, true));
		}
		found = PET_SPECIAL.matcher(plain);
		if (found.matches())
		{
			return one(pet(found, plain, false));
		}
		found = LEVEL.matcher(plain);
		if (found.matches())
		{
			return one(level(found, plain));
		}
		found = XP.matcher(plain);
		if (found.matches())
		{
			return one(experience(found, plain));
		}
		found = DIARY.matcher(plain);
		if (found.matches())
		{
			return one(diary(found, plain));
		}
		found = PB.matcher(plain);
		if (found.matches())
		{
			return one(personalBest(found, plain));
		}
		return Collections.emptyList();
	}

	/** The quest card: difficulty, length and points from the table, or "Quest completed" alone for a quest it lacks. */
	private HoverCard quest(Matcher found, String plain)
	{
		final String name = clean(found.group("quest"));
		final CardTables.QuestInfo info = tables.quest(name);
		final List<HoverCard.Pair> row = info == null
			? Collections.singletonList(pair("Quest completed", ""))
			: Arrays.asList(pair("Difficulty", info.difficulty), pair("Length", info.length),
				pair("Points", String.valueOf(info.points)));
		return new InfoCard(name, row, Collections.<String>emptyList(), page(info == null ? null : info.wiki, name),
			plain, found.start("quest"), found.end("quest"), SkillSprites.QUEST);
	}

	/**
	 * The combat achievement task card: tier, points and boss from the table with the description under them, whole (the
	 * painter wraps it to the card), or only the tier for a task it lacks; the picture is the tier's sword.
	 */
	private HoverCard task(Matcher found, String plain)
	{
		final String name = clean(found.group("task"));
		final String tier = canonicalTier(found.group("tier"));
		final CardTables.TaskInfo info = tables.achievement(name);
		final List<HoverCard.Pair> row;
		final List<String> notes;
		if (info == null)
		{
			row = Collections.singletonList(pair("Tier", tier));
			notes = Collections.emptyList();
		}
		else
		{
			row = new ArrayList<>(Arrays.asList(pair("Tier", info.tier), pair("Points", String.valueOf(info.points))));
			if (!info.monster.isEmpty())
			{
				row.add(pair("Boss", info.monster));
			}
			final String description = info.description.trim();
			notes = description.isEmpty() ? Collections.<String>emptyList() : Collections.singletonList(description);
		}
		return new InfoCard(name, row, notes, page(info == null ? null : info.wiki, name), plain, found.start("task"),
			found.end("task"), SkillSprites.CA_TIER_SWORDS + TIERS.indexOf(tier));
	}

	/**
	 * The pet card: the pet's name as the table spells it, where it comes from, its "Rate" when the drop table holds one
	 * ({@link ItemCards#rateOf}), and (when {@code counted} and the line has one) "Dropped at", the member's own count
	 * when the pet dropped, as the line gives it with its unit word; for a pet the table lacks, the name from the line and
	 * "Pet" alone. The picture is the pet's own item: the id the table gives when it has one, else the id {@link
	 * ItemCards#idOf} gives for the name as the table spells it, else the line's; -1 (no picture) when no item has that
	 * name.
	 *
	 * <p>Choice: the table is asked first, so the picture shows from the first second after login, before the names
	 * index {@code idOf} reads has been built.
	 */
	private HoverCard pet(Matcher found, String plain, boolean counted)
	{
		final String name = clean(found.group("pet"));
		final CardTables.PetInfo info = tables.pet(name);
		final List<HoverCard.Pair> row = new ArrayList<>();
		if (info == null)
		{
			row.add(pair("Pet", ""));
		}
		else
		{
			row.add(pair("Pet from", info.source));
			final String rate = itemCards.rateOf(info.name);
			if (rate != null && !rate.isEmpty())
			{
				row.add(pair("Rate", rate));
			}
			if (counted && found.group("count") != null)
			{
				row.add(pair("Dropped at", found.group("count") + " " + found.group("unit")));
			}
		}
		final String spelled = info == null ? name : info.name;
		final int itemId = info != null && info.itemId > 0 ? info.itemId : itemCards.idOf(spelled);
		return new InfoCard(spelled, row, Collections.<String>emptyList(), page(info == null ? null : info.wiki, name),
			plain, found.start("pet"), found.end("pet"), -1, itemId);
	}

	/**
	 * The level card, over the phrase "Defence level 70": for a skill the table knows, {@link #unlocks} ("Defence 70",
	 * what is new at that level); for any other skill, or before the table has loaded, the plain card "Defence level 70"
	 * with the skill's row and page. The combat level, which the pattern also reads, gets no card (null), nor does a
	 * total level line that says "the highest possible", which the pattern reads as a skill called "Total". The card is
	 * quiet.
	 */
	private HoverCard level(Matcher found, String plain)
	{
		final String skill = capitalised(found.group("skill"));
		if ("Combat".equals(skill) || "Total".equals(skill))
		{
			return null;
		}
		final List<String> unlocks = tables.unlocks(skill, levelOf(found.group("level")));
		if (unlocks != null)
		{
			return unlocks(skill, found, plain, unlocks);
		}
		return new InfoCard(skill + " level " + found.group("level"), Collections.singletonList(pair("Skill", skill)),
			Collections.<String>emptyList(), InfoCard.pageFor(skill), plain, found.start("skill"), found.end("level"),
			SkillSprites.spriteOf(skill), -1, false);
	}

	/**
	 * The card of what is new at a level, "Defence 70": one row, "New unlocks" with "4", "1" or "None", its
	 * unlocks under it as a list, and the skill's {@code Level_up_table} page. Its words are the phrase "Defence level
	 * 70", and it is quiet.
	 *
	 * <p>Choice: every unlock is kept whole and trimmed, in the table's order, one note each, and no full stop is added;
	 * the painter sets the notes as a numbered list under the card header, one to an item with a long one wrapping under
	 * its own text, and cuts the list with "..." where it runs on.
	 */
	private HoverCard unlocks(String skill, Matcher found, String plain, List<String> unlocks)
	{
		final int count = unlocks.size();
		final List<String> notes = new ArrayList<>();
		for (final String unlock : unlocks)
		{
			final String text = unlock.trim();
			if (!text.isEmpty())
			{
				notes.add(text);
			}
		}
		final String summary = count == 0 ? "None" : String.valueOf(count);
		return new InfoCard(skill + " " + found.group("level"),
			Collections.singletonList(pair("New unlocks", summary)), notes, skill + "/Level_up_table", plain,
			found.start("skill"), found.end("level"), SkillSprites.spriteOf(skill), -1, false);
	}

	/** The level a group of digits spells, or 0 when it is too large to be one (the table then has nothing for it). */
	private static int levelOf(String digits)
	{
		try
		{
			return Integer.parseInt(digits);
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	/** The XP milestone card, "200,000,000 XP in Cooking". Its words are that whole phrase, and it is quiet. */
	private HoverCard experience(Matcher found, String plain)
	{
		final String skill = capitalised(found.group("skill"));
		return new InfoCard(found.group("xp") + " XP in " + skill, Collections.singletonList(pair("Skill", skill)),
			Collections.<String>emptyList(), InfoCard.pageFor(skill), plain, found.start("xp"), found.end("skill"),
			SkillSprites.spriteOf(skill), -1, false);
	}

	/** The diary card, "Ardougne diary, Elite", with the area as the table spells it when it knows it. */
	private HoverCard diary(Matcher found, String plain)
	{
		final String area = clean(found.group("area"));
		final CardTables.DiaryInfo info = tables.diary(area);
		final String tier = found.group("tier");
		return new InfoCard((info == null ? area : info.name) + " diary, " + tier,
			Collections.singletonList(pair("Tier", tier)), Collections.<String>emptyList(),
			page(info == null ? null : info.wiki, area + " Diary"), plain, found.start("area"), found.end("area"),
			SkillSprites.DIARY);
	}

	/**
	 * The personal best card, "Vorkath personal best" with the time first, then the boss's facts from the table when it
	 * knows the activity ({@link BossCards#facts}); the picture is the wiki's own of the activity's page, the clue watch's
	 * item behind it until it comes.
	 */
	private HoverCard personalBest(Matcher found, String plain)
	{
		final String activity = clean(found.group("activity"));
		final CardTables.BossInfo info = tables.boss(activity);
		final List<HoverCard.Pair> row = new ArrayList<>();
		row.add(pair("Time", found.group("time")));
		row.addAll(BossCards.facts(info));
		return new InfoCard(activity + " personal best", row, Collections.<String>emptyList(),
			BossCards.page(info, activity), plain, found.start("activity"), found.end("activity"), -1, ItemID.TRAIL_WATCH,
			true, true);
	}

	/**
	 * The kill count card, "King Black Dragon kill count" with the count first, then the boss's facts from the table when
	 * it knows the boss ({@link BossCards#facts}); the picture is the wiki's own of the boss's page, the game's combat icon
	 * behind it until it comes.
	 *
	 * <p>Choice: the pair's label is "Kills" for a kill count and "Count" for the other kinds (chest, completion and the
	 * rest), and the title carries the kind's word in lower case.
	 */
	private HoverCard killCount(Matcher found, String plain)
	{
		final String boss = clean(found.group("boss"));
		final String kind = found.group("kind").toLowerCase(Locale.ROOT);
		final CardTables.BossInfo info = tables.boss(boss);
		final List<HoverCard.Pair> row = new ArrayList<>();
		row.add(pair("kill".equals(kind) ? "Kills" : "Count", found.group("count")));
		row.addAll(BossCards.facts(info));
		return new InfoCard(boss + " " + kind + " count", row, Collections.<String>emptyList(),
			BossCards.page(info, boss), plain, found.start("boss"), found.end("boss"), SkillSprites.spriteOf("Combat"), -1,
			true, true);
	}

	/** A pair of a label and its value with no note. */
	private static HoverCard.Pair pair(String label, String value)
	{
		return new HoverCard.Pair(label, value, "");
	}

	/** The wiki page of a thing: the table's page when it has one, else the page built from the name. */
	private static String page(String tablePage, String name)
	{
		return tablePage == null || tablePage.isEmpty() ? InfoCard.pageFor(name) : tablePage;
	}

	/** The one card in a list, or an empty list for none. */
	private static List<HoverCard> one(HoverCard card)
	{
		return card == null ? Collections.<HoverCard>emptyList() : Collections.singletonList(card);
	}

	/**
	 * A name taken from a group, cleaned: a no-break space read as a space, {@code @...@} macros removed, the trailing
	 * dots and the spaces around it taken off.
	 */
	private static String clean(String name)
	{
		final String text = MACRO.matcher(name.replace((char) 160, ' ')).replaceAll("").trim();
		int end = text.length();
		while (end > 0 && (text.charAt(end - 1) == '.' || text.charAt(end - 1) == ' '))
		{
			end--;
		}
		return text.substring(0, end);
	}

	/** A skill's word with its first letter in capitals and the rest in lower case ("combat" is "Combat"). */
	private static String capitalised(String word)
	{
		return Character.toUpperCase(word.charAt(0)) + word.substring(1).toLowerCase(Locale.ROOT);
	}

	/** The tier's word as {@link #TIERS} spells it, whatever case the line wrote it in. */
	private static String canonicalTier(String word)
	{
		for (final String tier : TIERS)
		{
			if (tier.equalsIgnoreCase(word))
			{
				return tier;
			}
		}
		return word;
	}

	/** The four channels whose broadcast lines carry these cards. */
	private static boolean isBroadcast(ChatMessageType type)
	{
		return type == ChatMessageType.CLAN_MESSAGE
			|| type == ChatMessageType.CLAN_GUEST_MESSAGE
			|| type == ChatMessageType.CLAN_GIM_MESSAGE
			|| type == ChatMessageType.FRIENDSCHATNOTIFICATION;
	}
}

package com.clanhub;

import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.ChatMessageType;

/**
 * Reads the broadcast lines of the clan, guest clan, group ironman and friends chat channels for the one item each
 * names: a drop, a stacked drop, a clue item or a new collection log item. Pure: a type and a message in, a mention
 * out, no RuneLite state. The sentences are the game's own; the patterns follow the ones Chat Item Pricer has used
 * without trouble.
 */
final class BroadcastLine
{
	/** "received a drop: 10 x Black knife (460 coins)": the quantity, the name, the value. */
	private static final Pattern STACKED_DROP = Pattern.compile(
		"received a drop: (\\d+) x (.+?) \\((.+?) coins\\)", Pattern.CASE_INSENSITIVE);
	/** "received a drop: Dragon claws (121,453,000 coins)": the name, the value. */
	private static final Pattern DROP = Pattern.compile(
		"received a drop: (.+?) \\((.+?) coins\\)", Pattern.CASE_INSENSITIVE);
	/** "received a clue item: Ranger boots (25,296,193 coins)": the name, the value. */
	private static final Pattern CLUE = Pattern.compile(
		"received a clue item: (.+?) \\((.+?) coins\\)", Pattern.CASE_INSENSITIVE);
	/** "received a new collection log item: Abyssal whip (1/484)": the name. */
	private static final Pattern COLLECTION_LOG = Pattern.compile(
		"received a new collection log item: (.+?) \\(\\d+/\\d+\\)", Pattern.CASE_INSENSITIVE);
	/** ") from Duke Sucellus.": the boss, monster, raid or chest a drop line names after the value. */
	private static final Pattern SOURCE = Pattern.compile("\\) from (.+?)\\.?$", Pattern.CASE_INSENSITIVE);

	private BroadcastLine()
	{
	}

	/**
	 * One item named in a broadcast line: the item's name, how many of it, where the name starts and ends in the plain
	 * text (every tag already stripped), that plain text, and the boss, monster, raid or chest the line says the item came
	 * from, with where that name stands in the text. Plain data, read by the plugin when it builds the card.
	 */
	static final class ItemMention
	{
		/** The item's name as the line spells it. */
		final String name;
		/** How many of the item: 1 unless the line says "10 x". */
		final int quantity;
		/** Where the name starts in {@link #text}. */
		final int start;
		/** Just past the name's last character in {@link #text}. */
		final int end;
		/** The line without its tags. */
		final String text;
		/** The boss, monster, raid or chest the line names after the value ("from Duke Sucellus"), or null when it names none. */
		final String source;
		/** Where the source's name starts in {@link #text}, or -1 when the line names none. */
		final int sourceStart;
		/** Just past the source's name in {@link #text}, or -1 when the line names none. */
		final int sourceEnd;

		ItemMention(String name, int quantity, int start, int end, String text, String source, int sourceStart,
			int sourceEnd)
		{
			this.name = name;
			this.quantity = quantity;
			this.start = start;
			this.end = end;
			this.text = text;
			this.source = source;
			this.sourceStart = sourceStart;
			this.sourceEnd = sourceEnd;
		}
	}

	/**
	 * The item a broadcast line names, or nothing. Only the four channels' broadcast types are read; the tags (colours
	 * and rank icons) are stripped first ({@link ChatText#plain}), and the patterns are tried in the order stacked drop, drop, clue item,
	 * collection log item, so a stacked drop is never read as an item called "10 x Black knife".
	 *
	 * <p>Choice: a quantity too large for an int gives no mention, so no card.
	 *
	 * <p>Choice: the source ("from Duke Sucellus") is read only after a drop, a stacked drop or a clue item's value, from
	 * the closing bracket of the value to the line's end, without the full stop that ends the sentence; a collection log
	 * line names none, and a line with no "from" gives a mention with no source.
	 */
	static Optional<ItemMention> parse(ChatMessageType type, String message)
	{
		if (message == null || !isBroadcast(type))
		{
			return Optional.empty();
		}
		final String text = ChatText.plain(message);

		Matcher found = STACKED_DROP.matcher(text);
		if (found.find())
		{
			try
			{
				return Optional.of(mention(found, 2, Integer.parseInt(found.group(1)), text, true));
			}
			catch (NumberFormatException e)
			{
				return Optional.empty();
			}
		}
		found = DROP.matcher(text);
		if (found.find())
		{
			return Optional.of(mention(found, 1, 1, text, true));
		}
		found = CLUE.matcher(text);
		if (found.find())
		{
			return Optional.of(mention(found, 1, 1, text, true));
		}
		found = COLLECTION_LOG.matcher(text);
		if (found.find())
		{
			return Optional.of(mention(found, 1, 1, text, false));
		}
		return Optional.empty();
	}

	/**
	 * The mention for the match's name group; when {@code withSource} is true, the source the line names after the match's
	 * closing bracket is read too, trimmed.
	 */
	private static ItemMention mention(Matcher found, int nameGroup, int quantity, String text, boolean withSource)
	{
		String source = null;
		int sourceStart = -1;
		int sourceEnd = -1;
		if (withSource)
		{
			final Matcher from = SOURCE.matcher(text);
			from.region(found.end() - 1, text.length());
			if (from.find())
			{
				final String raw = from.group(1);
				final String trimmed = raw.trim();
				if (!trimmed.isEmpty())
				{
					source = trimmed;
					sourceStart = from.start(1) + raw.indexOf(trimmed);
					sourceEnd = sourceStart + trimmed.length();
				}
			}
		}
		return new ItemMention(found.group(nameGroup), quantity, found.start(nameGroup), found.end(nameGroup), text,
			source, sourceStart, sourceEnd);
	}

	/** The four channels whose broadcast lines carry a card. */
	private static boolean isBroadcast(ChatMessageType type)
	{
		return type == ChatMessageType.CLAN_MESSAGE
			|| type == ChatMessageType.CLAN_GUEST_MESSAGE
			|| type == ChatMessageType.CLAN_GIM_MESSAGE
			|| type == ChatMessageType.FRIENDSCHATNOTIFICATION;
	}
}

package com.clanhub;

import com.clanhub.ClanHubConfig.CardTrigger;

/**
 * Whether a card (and the underline under its words) shows yet: the show mode, the key and the delay settings against
 * how long the mouse has been on the words. Pure: the times come in as numbers, so no clock is read here.
 */
final class CardGate
{
	/** Nanoseconds in a millisecond. */
	private static final long NANOS_PER_MILLI = 1_000_000L;

	private CardGate()
	{
	}

	/**
	 * Whether the card shows. With {@link CardTrigger#CLICK} it shows exactly when the words were clicked ({@code clicked}),
	 * with no wait. Otherwise: not when the trigger is {@link CardTrigger#HOLD_KEY} and the key is not held; else once the
	 * mouse has been on the words for {@code delayMs} (the gap between {@code hoveredSinceNanos} and {@code nowNanos} is
	 * at least that), at once for a delay of 0. {@code clicked} means nothing to the other two modes.
	 */
	static boolean shows(CardTrigger trigger, boolean keyHeld, boolean clicked, long hoveredSinceNanos, long nowNanos,
		int delayMs)
	{
		if (trigger == CardTrigger.CLICK)
		{
			return clicked;
		}
		if (trigger == CardTrigger.HOLD_KEY && !keyHeld)
		{
			return false;
		}
		return nowNanos - hoveredSinceNanos >= delayMs * NANOS_PER_MILLI;
	}
}

package com.clanhub;

import com.clanhub.ClanHubConfig.CardTrigger;
import java.awt.event.KeyEvent;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.Supplier;
import net.runelite.client.config.Keybind;
import net.runelite.client.input.KeyListener;

/**
 * The listener of the card key. It tells the overlay when the key goes down and up, and lets every key through to the
 * game except in one case: the key is taken (the press, the character it would type and the release are consumed) only
 * while "Show a card" is "While holding a key", "Show hover cards" is on and the mouse is on a card's words. Everywhere
 * else the key types as usual, so a letter set as the card key can still be typed in the chat.
 *
 * <p>Choice: not RuneLite's {@code HotkeyListener}, which consumes every press and release of its key in every show
 * mode, whether the cards are on or off and whether or not the mouse is on a card, so a letter key set as the card key
 * could not be typed into the chat (the user hit it with 'g'). The take is decided at the press and kept to its
 * release and its typed character, so a key taken at its press is never half-taken: the character does not reach the
 * chat and the game does not see a release without a press. All of it runs on the AWT thread only, so the state needs
 * no lock.
 */
final class CardKeyListener implements KeyListener
{
	private final Supplier<Keybind> key;
	private final Supplier<CardTrigger> trigger;
	private final BooleanSupplier cardsOn;
	private final Supplier<HoverCard> hovered;
	private final Consumer<Boolean> held;

	/** The key code of the matching press not yet released, {@link KeyEvent#VK_UNDEFINED} for none. */
	private int pressedCode = KeyEvent.VK_UNDEFINED;
	/** Whether the press now down was taken from the game. */
	private boolean using;

	/**
	 * @param key the card key setting
	 * @param trigger the show mode setting
	 * @param cardsOn whether "Show hover cards" is on
	 * @param hovered the card under the mouse as of the last frame, or null
	 * @param held told true when the card key goes down and false when it comes up or the window loses focus
	 */
	CardKeyListener(Supplier<Keybind> key, Supplier<CardTrigger> trigger, BooleanSupplier cardsOn,
		Supplier<HoverCard> hovered, Consumer<Boolean> held)
	{
		this.key = key;
		this.trigger = trigger;
		this.cardsOn = cardsOn;
		this.hovered = hovered;
		this.held = held;
	}

	/** Consumes the character of a key that was taken at its press, so it never reaches the chat. */
	@Override
	public void keyTyped(KeyEvent e)
	{
		if (using)
		{
			e.consume();
		}
	}

	/**
	 * Tells the overlay the card key is down, and takes the press from the game when the key does something: the show mode
	 * is "While holding a key", the cards are on and the mouse is on a card. A key that is not the card key is left alone.
	 */
	@Override
	public void keyPressed(KeyEvent e)
	{
		if (!key.get().matches(e))
		{
			return;
		}
		held.accept(true);
		pressedCode = e.getKeyCode();
		if (cardsOn.getAsBoolean() && trigger.get() == CardTrigger.HOLD_KEY && hovered.get() != null)
		{
			e.consume();
			using = true;
		}
	}

	/** Tells the overlay the card key is up, and takes the release from the game if its press was taken. */
	@Override
	public void keyReleased(KeyEvent e)
	{
		if (pressedCode != KeyEvent.VK_UNDEFINED && e.getKeyCode() == pressedCode)
		{
			held.accept(false);
			pressedCode = KeyEvent.VK_UNDEFINED;
			if (using)
			{
				e.consume();
				using = false;
			}
		}
	}

	/** The window lost focus, so no release will come: the key is up and nothing is taken. */
	@Override
	public void focusLost()
	{
		held.accept(false);
		pressedCode = KeyEvent.VK_UNDEFINED;
		using = false;
	}
}

package com.clanhub;

import java.util.function.Consumer;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;

/**
 * The two entries a right-click on a chat line that holds a card adds to the game's menu: "Open wiki" and "Copy".
 * Both are the client's own kind of entry ({@code MenuAction.RUNELITE}): nothing is sent to the game. What they do is
 * handed in, so the entries can be checked without a browser or a clipboard.
 */
final class CardMenu
{
	private static final String OPEN_WIKI = "Open wiki";
	private static final String COPY = "Copy";
	/** The card's title in the menu's orange, the way the game shows a target. */
	private static final String TARGET_OPEN = "<col=ff9040>";
	private static final String TARGET_CLOSE = "</col>";

	private CardMenu()
	{
	}

	/**
	 * Adds "Open wiki" and "Copy" to the menu for {@code card}, or nothing when there is no card. The target of both is
	 * the card's title (an item's name, with its "x10" for a stack). "Open wiki" hands the card's wiki address to
	 * {@code browse} and "Copy" hands the line's plain text to {@code copy}. "Copy" is made first and "Open wiki" last,
	 * each with {@code createMenuEntry(-1)}: the client adds an entry at the end of its list and draws the end at the
	 * top, so the one made last is the one on top.
	 */
	static void addEntries(Menu menu, HoverCard card, Consumer<String> browse, Consumer<String> copy)
	{
		if (card == null)
		{
			return;
		}
		final String target = TARGET_OPEN + card.title() + TARGET_CLOSE;
		menu.createMenuEntry(-1)
			.setOption(COPY)
			.setTarget(target)
			.setType(MenuAction.RUNELITE)
			.onClick(e -> copy.accept(card.plainLine()));
		menu.createMenuEntry(-1)
			.setOption(OPEN_WIKI)
			.setTarget(target)
			.setType(MenuAction.RUNELITE)
			.onClick(e -> browse.accept(card.wikiUrl()));
	}
}

package com.clanhub;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.runelite.client.ui.FontManager;

/**
 * Draws a card and decides where it opens. Pure drawing: a {@link HoverCard}, a picture, a size and the description
 * text in, pixels and the card's size out. Two looks share one ground, a brown ground with a black edge and a lighter
 * line inside it. The split card is a header across the top, the picture (in a 36 x 32 box, or, for a card of a boss,
 * monster, raid or chest, the wiki's own picture in a 64 x 64 box), the bold title with the stack after it and the
 * facts of the first row at the right end of the same line (or, when they do not fit, under the title, wrapped onto as
 * many rows as they need); then, for an item, one grey line of drops, each source with its rate in white, flowing to the card's width; then
 * a rule and the description in white across the full width in at most the caller's number of lines; then a rule and the
 * hint in small grey type. It is as wide as its header, its description, its drops or its hint need, and never wider than
 * the caller's cap at the 16 px text size. The wide card is as wide as it is asked: the same header row, the drops (grey too) spread along
 * a row of their own, a rule, the description in white over the full width, and the hint. A drop with no rate ("and 2
 * more") is drawn as grey words alone in either card. The painter wraps the description itself, by pixel width in the
 * real font.
 */
final class CardPainter
{
	/** The card's ground, solid: nothing of the game shows through it. */
	static final Color GROUND = new Color(70, 61, 50);
	/** The line inside the black edge, and the rules across the text. */
	static final Color LINE = new Color(118, 104, 82);
	/** The labels, the notes after a value, and the drops. */
	static final Color LABEL = new Color(165, 165, 165);
	/** The hint's grey. */
	static final Color HINT = new Color(135, 135, 135);

	/** The gap from the card's edge to its content: the black edge and the line inside it, then the padding, in px. */
	static final int INSET = 2 + 7;

	/** The item sprite's box, in px. */
	private static final int SPRITE_WIDTH = 36;
	private static final int SPRITE_HEIGHT = 32;
	/**
	 * The wiki picture's square box, in px: the header row of a card with {@link HoverCard#wikiPicture} is at least this
	 * tall, and its picture is drawn centred in it, both ways.
	 */
	static final int PICTURE_BOX = 64;
	/** The gap between the sprite and the text, in px. */
	private static final int SPRITE_GAP = 8;
	/** The air above and below a rule, in px. */
	private static final int RULE_AIR = 2;
	/** A label and its value are set apart by this. */
	private static final String LABEL_GAP = " ";
	/** What a cut line ends in. */
	private static final String MORE = "...";
	/** The caption over the drops. */
	private static final String DROPS = "Drops";

	/** The size the widths below are given at, in px. */
	private static final float BASE_SIZE = 16f;
	/** The most lines the wide card's paragraph takes; the split card's is the caller's. */
	private static final int WIDE_LINES = 2;
	/** The most lines a numbered list takes, at any width; a paragraph keeps the Card width setting's count. */
	static final int LIST_LINES = 10;
	/** The least air between two facts, and between two drops of the wide card, at 16 px. */
	private static final int FACT_GAP = 16;
	private static final int DROP_GAP = 12;

	/** The card opens this far above the cursor; when it opens below instead, its top is this far under it. */
	private static final int OPEN_ABOVE = 6;
	private static final int OPEN_BELOW = 18;

	private CardPainter()
	{
	}

	/**
	 * Where a split card of {@code card} size opens for a cursor on a canvas of {@code canvas} size: centred on the
	 * cursor, its bottom edge 6 px above it. Its left edge is held between the canvas's left edge and the place where its
	 * right edge meets the canvas's right edge. If its top would pass the top of the canvas it opens below the cursor
	 * instead, its top 18 px under it, held so that its bottom does not pass the canvas's bottom.
	 */
	static Rectangle placeCentred(Point cursor, Dimension card, Dimension canvas)
	{
		final int x = Math.max(0, Math.min(cursor.x - card.width / 2, canvas.width - card.width));
		int y = cursor.y - OPEN_ABOVE - card.height;
		if (y < 0)
		{
			y = Math.min(cursor.y + OPEN_BELOW, canvas.height - card.height);
		}
		return new Rectangle(x, y, card.width, card.height);
	}

	/**
	 * Where a wide card of {@code card} size opens above the chatbox's frame {@code chat}: its left edge on the frame's,
	 * its bottom edge on the frame's top edge. A card taller than the room above the frame is held at the top of the
	 * canvas.
	 */
	static Rectangle placeAboveChat(Rectangle chat, Dimension card)
	{
		return new Rectangle(chat.x, Math.max(0, chat.y - card.height), card.width, card.height);
	}

	/**
	 * Paints the split card with its top-left corner at ({@code x}, {@code y}) and returns its size. From the top: the
	 * header (the picture, the bold title with the stack in grey after it, the facts of the first row at the right end of
	 * that line, or under the title in as many rows as they need when they do not fit), the drops as one grey line of words with each rate in
	 * white (a drop with no rate is its grey words alone), the {@code description}, one text ("" for none), in white
	 * across the full width in at most {@code paragraphLines} lines with "..." ending the last when it goes on, and,
	 * under a rule, the hint. The description is a paragraph, or a numbered list when it holds line breaks (see
	 * {@link #layout}), a list taking up to {@link #LIST_LINES} lines whatever {@code paragraphLines} is. The card's own
	 * notes are not drawn, the caller passes them as the description. The width is
	 * as much as the widest of the header, the whole description on one line (the widest item of a list), the whole drops
	 * line on one line and the
	 * hint ask for, never more than {@code capAt16} px at {@code fontSize} 16 and growing and shrinking with it; a short
	 * card is narrow. The title
	 * is in the client's bold game font, everything else in its plain game font, the hint in its small one, all derived
	 * to {@code fontSize}. The picture's box is 36 x 32, drawn from its top-left corner as it comes, or, for a card with
	 * {@link HoverCard#wikiPicture}, {@link #PICTURE_BOX} square with the picture centred in it (scaled down to fit
	 * when it is bigger), which makes the header row at least that tall and moves the text to its right. A null picture
	 * leaves the box empty. The text is antialiased.
	 *
	 * <p>Choice: the measuring pass decides the width and the drawing pass lays out again at that width, so the one
	 * layout serves both.
	 */
	static Dimension paintSplit(Graphics2D g, HoverCard card, BufferedImage picture, int fontSize, int x, int y,
		String description, int capAt16, int paragraphLines)
	{
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		final Faces faces = new Faces(g, fontSize);
		final Dimension content = splitContent(new Pen(g, false), faces, card, picture, fontSize, 0, 0, description, capAt16,
			paragraphLines);
		final int width = content.width + 2 * INSET;
		final int height = 2 * INSET + content.height + RULE_AIR + 1 + RULE_AIR + faces.hintHeight;

		frame(g, x, y, width, height);
		splitContent(new Pen(g, true), faces, card, picture, fontSize, x, y, description, capAt16, paragraphLines);
		g.setColor(LINE);
		int lineTop = y + INSET + content.height + RULE_AIR;
		g.fillRect(x + INSET, lineTop, width - 2 * INSET, 1);
		lineTop += 1 + RULE_AIR;
		g.setFont(faces.hint);
		g.setColor(HINT);
		g.drawString(card.hint(), x + INSET, lineTop + faces.hintMetrics.getAscent());
		return new Dimension(width, height);
	}

	/**
	 * Paints the wide card, {@code width} px wide, with its top-left corner at ({@code x}, {@code y}) and returns its
	 * size. First row: the picture, the bold title with the stack in grey after it, and at the row's right end the facts
	 * of the first row; when they do not fit beside the title they go under it, in as many rows as they need. The picture's
	 * box is the split card's: 36 x 32, or {@link #PICTURE_BOX} square with the picture centred for a card with
	 * {@link HoverCard#wikiPicture}. Second row, when the card has drop rows: the grey caption and the drops spread evenly
	 * over the rest of the width, each its rate then its source, all in the label grey (a drop with no rate is its source
	 * alone, counting no gap for the rate), wrapping to a new row when they do not fit. Then a rule, the
	 * {@code description} ("" for none), a paragraph, or a numbered list when the description holds line breaks (see
	 * {@link #layout}), wrapped to the full width in white, a paragraph in at most two lines and a list in at most
	 * {@link #LIST_LINES}, the last line ending in "..." when the text goes on, and the hint. Fonts and colours as the
	 * split card's. The {@code accent} no longer colours anything, the drops being grey now; the parameter stays only so
	 * that the caller's signature does.
	 */
	static Dimension paintWide(Graphics2D g, HoverCard card, BufferedImage picture, int fontSize, int width, int x, int y,
		String description, Color accent)
	{
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		final Faces faces = new Faces(g, fontSize);
		final int content = wideContent(new Pen(g, false), faces, card, picture, fontSize, width, 0, 0, description, accent);
		final int height = 2 * INSET + content + faces.hintHeight;

		frame(g, x, y, width, height);
		wideContent(new Pen(g, true), faces, card, picture, fontSize, width, x, y, description, accent);
		g.setFont(faces.hint);
		g.setColor(HINT);
		g.drawString(card.hint(), x + INSET, y + INSET + content + faces.hintMetrics.getAscent());
		return new Dimension(width, height);
	}

	/** A width given at 16 px, at {@code fontSize}. */
	private static int scaled(int atBase, int fontSize)
	{
		return Math.round(atBase * fontSize / BASE_SIZE);
	}

	/** The card's ground, its black edge, and the line inside the edge. */
	private static void frame(Graphics2D g, int x, int y, int width, int height)
	{
		g.setColor(GROUND);
		g.fillRect(x, y, width, height);
		g.setColor(Color.BLACK);
		g.drawRect(x, y, width - 1, height - 1);
		g.setColor(LINE);
		g.drawRect(x + 1, y + 1, width - 3, height - 3);
	}

	/**
	 * Lays out the split card's content from ({@code ox}, {@code oy}), the card's top-left corner, drawing it when
	 * {@code pen} draws; returns the width and the height of the content inside the card's inset, the height ending at
	 * the description's last line, which the hint's rule follows. In order: the header row, the drops line, and, when
	 * there is a description, a rule and the description in white.
	 *
	 * <p>Choice: the width is the widest need among the header, the whole description on one line, the whole drops line
	 * on one line and the hint, held to {@code capAt16} px at 16 px less the inset; so a short card is narrow, and a long
	 * text is cut or flows to the line below at the widest. A paragraph takes at most {@code paragraphLines} lines, a
	 * numbered list at most {@link #LIST_LINES}, and the list's width is the widest of its items on a line each.
	 */
	private static Dimension splitContent(Pen pen, Faces faces, HoverCard card, BufferedImage picture, int fontSize, int ox,
		int oy, String description, int capAt16, int paragraphLines)
	{
		final FontMetrics body = faces.bodyMetrics;
		final int innerMax = scaled(capAt16, fontSize) - 2 * INSET;
		final int left = ox + INSET;
		final int top = oy + INSET;
		final List<Word> dropWords = dropWords(card);

		// The width: the widest of what the four parts ask for, held to the most.
		final int paragraphNeed = Math.min(innerMax, descriptionNeed(description, body));
		final int dropsNeed = dropWords.isEmpty() ? 0
			: Math.min(innerMax, lineWidth(flow(dropWords, body, Integer.MAX_VALUE).get(0), body));
		final int hintNeed = faces.hintMetrics.stringWidth(card.hint());
		final int need = Math.max(Math.max(headerNeed(faces, card, fontSize, innerMax), paragraphNeed),
			Math.max(dropsNeed, hintNeed));
		final int inner = Math.min(innerMax, need);

		// The header, then the drops: "Drops:" and each source in grey, each rate in white, one comma after each drop but the last.
		int y = top + headerRow(pen, faces, card, picture, fontSize, left, top, inner);
		if (!dropWords.isEmpty())
		{
			for (final List<Word> line : flow(dropWords, body, inner))
			{
				int x = left;
				for (final Word word : line)
				{
					pen.string(word.text, faces.body, word.colour, x, y + body.getAscent());
					pen.string(word.tail, faces.body, LABEL, x + body.stringWidth(word.text), y + body.getAscent());
					x += word.width(body) + body.stringWidth(LABEL_GAP);
				}
				y += faces.bodyHeight;
			}
		}

		// The description, under a rule across the card; with none, no rule and no air.
		final List<TextLine> lines = layout(description, body, inner, paragraphLines);
		if (!lines.isEmpty())
		{
			y += RULE_AIR;
			pen.rule(left, y, inner, 1);
			y += 1 + RULE_AIR;
			for (final TextLine line : lines)
			{
				pen.string(line.text, faces.body, Color.WHITE, left + line.indent, y + body.getAscent());
				y += faces.bodyHeight;
			}
		}
		return new Dimension(inner, y - top);
	}

	/**
	 * Lays out the wide card from ({@code ox}, {@code oy}), the card's top-left corner, drawing it when {@code pen}
	 * draws; returns the height from the top of the content to the end of the description, which the hint follows. The
	 * description is laid out to the inner width: a paragraph in at most {@link #WIDE_LINES} lines, a numbered list in at
	 * most {@link #LIST_LINES}.
	 */
	private static int wideContent(Pen pen, Faces faces, HoverCard card, BufferedImage picture, int fontSize, int width,
		int ox, int oy, String description, Color accent)
	{
		final int left = ox + INSET;
		final int innerWidth = Math.max(1, width - 2 * INSET);
		final int right = left + innerWidth;
		final int top = oy + INSET;
		final int dropGap = scaled(DROP_GAP, fontSize);
		final FontMetrics body = faces.bodyMetrics;

		// Row 1: the picture, the title and the stack, the facts at the right end or in rows under the title.
		int y = top + headerRow(pen, faces, card, picture, fontSize, left, top, innerWidth);

		// Row 2: the caption and the drops, spread evenly over the rest of the width, wrapping when they do not fit.
		final List<HoverCard.Pair> drops = dropsOf(card);
		if (!drops.isEmpty())
		{
			pen.string(DROPS, faces.body, LABEL, left, y + body.getAscent());
			final int dropsLeft = left + body.stringWidth(DROPS) + dropGap;
			final int available = Math.max(1, right - dropsLeft);
			final int spaceWidth = body.stringWidth(LABEL_GAP);
			int next = 0;
			while (next < drops.size())
			{
				final List<HoverCard.Pair> rowDrops = new ArrayList<>();
				final List<Integer> widths = new ArrayList<>();
				int sum = 0;
				while (next < drops.size())
				{
					final HoverCard.Pair drop = drops.get(next);
					final int wanted = drop.value.isEmpty() ? body.stringWidth(drop.label)
						: body.stringWidth(drop.value) + spaceWidth + body.stringWidth(drop.label);
					final int w = Math.min(wanted, available);
					if (!rowDrops.isEmpty() && sum + w + rowDrops.size() * dropGap > available)
					{
						break;
					}
					rowDrops.add(drop);
					widths.add(w);
					sum += w;
					next++;
				}
				final float gap = rowDrops.size() > 1 ? (available - sum) / (float) (rowDrops.size() - 1) : 0f;
				int before = 0;
				for (int i = 0; i < rowDrops.size(); i++)
				{
					final HoverCard.Pair drop = rowDrops.get(i);
					final int w = widths.get(i);
					final int dropX = i == rowDrops.size() - 1 && i > 0 ? right - w
						: dropsLeft + before + Math.round(i * gap);
					if (drop.value.isEmpty())
					{
						pen.string(fit(drop.label, body, Math.max(1, w)), faces.body, LABEL, dropX, y + body.getAscent());
					}
					else
					{
						final int rateWidth = body.stringWidth(drop.value);
						pen.string(drop.value, faces.body, LABEL, dropX, y + body.getAscent());
						pen.string(fit(drop.label, body, Math.max(1, w - rateWidth - spaceWidth)), faces.body, LABEL,
							dropX + rateWidth + spaceWidth, y + body.getAscent());
					}
					before += w;
				}
				y += faces.bodyHeight;
			}
		}

		y += RULE_AIR;
		pen.rule(left, y, innerWidth, 1);
		y += 1 + RULE_AIR;
		for (final TextLine line : layout(description, body, innerWidth, WIDE_LINES))
		{
			pen.string(line.text, faces.body, Color.WHITE, left + line.indent, y + body.getAscent());
			y += faces.bodyHeight;
		}
		return y - top;
	}

	/**
	 * Lays out the first row both cards open with, from ({@code left}, {@code top}) across {@code innerWidth} px, drawing
	 * it when {@code pen} draws; returns the row's height. The picture at the left, then the bold title, cut with "..."
	 * where it would pass the right edge, with the stack in grey after it; the facts of the first row at the right end of
	 * the line, or, when they would not fit beside the title and the stack, under the title at the text's left, set in
	 * rows by {@link #factRows} (as many facts to a row as fit between the text's left and the right edge), which makes
	 * the row taller by a body line for each fact row.
	 */
	private static int headerRow(Pen pen, Faces faces, HoverCard card, BufferedImage picture, int fontSize, int left,
		int top, int innerWidth)
	{
		final FontMetrics body = faces.bodyMetrics;
		final int right = left + innerWidth;
		final int factGap = scaled(FACT_GAP, fontSize);
		final int boxWidth = card.wikiPicture() ? PICTURE_BOX : SPRITE_WIDTH;
		final int boxHeight = card.wikiPicture() ? PICTURE_BOX : SPRITE_HEIGHT;
		final int textLeft = left + boxWidth + SPRITE_GAP;
		final String stack = stackOf(card);
		final int stackWidth = stack == null ? 0 : body.stringWidth(LABEL_GAP + stack);
		final String name = fit(nameOf(card), faces.titleMetrics, Math.max(1, right - textLeft - stackWidth));
		final int nameWidth = faces.titleMetrics.stringWidth(name);
		final List<HoverCard.Pair> facts = factsOf(card);
		final int factsWidth = rowWidth(facts, body, factGap);
		final boolean under = !facts.isEmpty() && textLeft + nameWidth + stackWidth + factGap + factsWidth > right;
		final List<List<HoverCard.Pair>> underRows = under ? factRows(facts, body, right - textLeft, factGap)
			: new ArrayList<List<HoverCard.Pair>>();
		final int rowHeight = Math.max(boxHeight,
			under ? faces.titleHeight + underRows.size() * faces.bodyHeight : faces.titleHeight);
		if (card.wikiPicture())
		{
			pen.pictureInBox(picture, left, top, PICTURE_BOX);
		}
		else
		{
			pen.picture(picture, left, top);
		}
		final int titleTop = under ? top : top + (rowHeight - faces.titleHeight) / 2;
		pen.string(name, faces.title, Color.WHITE, textLeft, titleTop + faces.titleMetrics.getAscent());
		if (stack != null)
		{
			pen.string(LABEL_GAP + stack, faces.body, LABEL, textLeft + nameWidth, titleTop + faces.titleMetrics.getAscent());
		}
		if (under)
		{
			int baseline = top + faces.titleHeight + body.getAscent();
			for (final List<HoverCard.Pair> factRow : underRows)
			{
				drawRow(pen, faces, factRow, textLeft, baseline, factGap);
				baseline += faces.bodyHeight;
			}
		}
		else if (!facts.isEmpty())
		{
			drawRow(pen, faces, facts, right - factsWidth, top + (rowHeight - faces.bodyHeight) / 2 + body.getAscent(),
				factGap);
		}
		return rowHeight;
	}

	/**
	 * The width the header row asks for, in px: the picture, its gap, the whole title, the stack and, when there are
	 * facts, the gap and the facts, on one line. When that passes {@code innerMax} the facts go under the title, as
	 * {@link #headerRow} puts them, and the row asks for the picture, its gap and the wider of the title (cut to
	 * {@code innerMax}, with the stack) and the widest single fact.
	 *
	 * <p>Choice: the facts under the title wrap onto rows ({@link #factRows}), so the card need not be as wide as the
	 * whole row of them: it asks for the widest fact, and the rows fill the width the other parts of the card give it.
	 */
	private static int headerNeed(Faces faces, HoverCard card, int fontSize, int innerMax)
	{
		final FontMetrics body = faces.bodyMetrics;
		final int factGap = scaled(FACT_GAP, fontSize);
		final int textLeft = (card.wikiPicture() ? PICTURE_BOX : SPRITE_WIDTH) + SPRITE_GAP;
		final String stack = stackOf(card);
		final int stackWidth = stack == null ? 0 : body.stringWidth(LABEL_GAP + stack);
		final int titleWidth = faces.titleMetrics.stringWidth(nameOf(card));
		final List<HoverCard.Pair> facts = factsOf(card);
		final int factsWidth = rowWidth(facts, body, factGap);
		final int beside = textLeft + titleWidth + stackWidth + (facts.isEmpty() ? 0 : factGap + factsWidth);
		if (facts.isEmpty() || beside <= innerMax)
		{
			return beside;
		}
		final String fitted = fit(nameOf(card), faces.titleMetrics, Math.max(1, innerMax - textLeft - stackWidth));
		int widestFact = 0;
		for (final HoverCard.Pair fact : facts)
		{
			widestFact = Math.max(widestFact, rowWidth(Collections.singletonList(fact), body, factGap));
		}
		return textLeft + Math.max(faces.titleMetrics.stringWidth(fitted) + stackWidth, widestFact);
	}

	/**
	 * The facts set in rows, in order, each row as many facts as fit {@code width} px with {@code gap} px between them
	 * (greedily: a fact that does not fit after the ones before it starts the next row); a fact wider than the width
	 * stands alone on its row. No facts give no rows, and no row is empty.
	 */
	static List<List<HoverCard.Pair>> factRows(List<HoverCard.Pair> facts, FontMetrics metrics, int width, int gap)
	{
		final List<List<HoverCard.Pair>> rows = new ArrayList<>();
		List<HoverCard.Pair> row = new ArrayList<>();
		int used = 0;
		for (final HoverCard.Pair fact : facts)
		{
			final int wanted = rowWidth(Collections.singletonList(fact), metrics, gap);
			if (!row.isEmpty() && (long) used + gap + wanted > width)
			{
				rows.add(row);
				row = new ArrayList<>();
				used = 0;
			}
			used += row.isEmpty() ? wanted : gap + wanted;
			row.add(fact);
		}
		if (!row.isEmpty())
		{
			rows.add(row);
		}
		return rows;
	}

	/**
	 * The drops line as words, in order: "Drops:", then for each drop the words of its source in the label grey and its
	 * rate in white (none for a drop with no rate), a comma in the label grey after every drop but the last, attached to
	 * the word before it. No words when the card has no drops.
	 */
	private static List<Word> dropWords(HoverCard card)
	{
		final List<Word> words = new ArrayList<>();
		final List<HoverCard.Pair> drops = dropsOf(card);
		if (drops.isEmpty())
		{
			return words;
		}
		words.add(new Word(DROPS + ":", LABEL, ""));
		for (int i = 0; i < drops.size(); i++)
		{
			final HoverCard.Pair drop = drops.get(i);
			for (final String part : drop.label.trim().split("\\s+"))
			{
				if (!part.isEmpty())
				{
					words.add(new Word(part, LABEL, ""));
				}
			}
			if (!drop.value.isEmpty())
			{
				words.add(new Word(drop.value, Color.WHITE, ""));
			}
			if (i < drops.size() - 1)
			{
				final Word last = words.get(words.size() - 1);
				words.set(words.size() - 1, new Word(last.text, last.colour, ","));
			}
		}
		return words;
	}

	/**
	 * The words set in lines, a space apart, a word that would pass {@code width} px starting the next line; a word
	 * wider than the width stands on a line of its own. At least one line when there are words.
	 */
	private static List<List<Word>> flow(List<Word> words, FontMetrics metrics, int width)
	{
		final int space = metrics.stringWidth(LABEL_GAP);
		final List<List<Word>> lines = new ArrayList<>();
		List<Word> line = new ArrayList<>();
		int used = 0;
		for (final Word word : words)
		{
			final int wordWidth = word.width(metrics);
			if (!line.isEmpty() && (long) used + space + wordWidth > width)
			{
				lines.add(line);
				line = new ArrayList<>();
				used = 0;
			}
			used += line.isEmpty() ? wordWidth : space + wordWidth;
			line.add(word);
		}
		if (!line.isEmpty())
		{
			lines.add(line);
		}
		return lines;
	}

	/** One line of words as {@link #flow} sets it: the words and the spaces between, in px. */
	private static int lineWidth(List<Word> line, FontMetrics metrics)
	{
		int width = 0;
		for (final Word word : line)
		{
			width += word.width(metrics);
		}
		return width + Math.max(0, line.size() - 1) * metrics.stringWidth(LABEL_GAP);
	}

	/** The card's title without the stack ("Dragon platelegs x7" is "Dragon platelegs"). */
	private static String nameOf(HoverCard card)
	{
		final String title = card.title();
		final String stack = stackOf(card);
		return stack != null && title.endsWith(LABEL_GAP + stack)
			? title.substring(0, title.length() - stack.length() - 1) : title;
	}

	/** The stack as "x7", or null for a card that is not a stack. */
	private static String stackOf(HoverCard card)
	{
		return card.quantity() > 1 ? "x" + card.quantity() : null;
	}

	/** The pairs of the card's first row, the facts; none when it has no rows. */
	private static List<HoverCard.Pair> factsOf(HoverCard card)
	{
		final List<List<HoverCard.Pair>> rows = card.rows();
		return rows.isEmpty() ? new ArrayList<HoverCard.Pair>() : rows.get(0);
	}

	/** The drops: the first pair of each row after the first, the source as its label and the rate as its value. */
	private static List<HoverCard.Pair> dropsOf(HoverCard card)
	{
		final List<HoverCard.Pair> drops = new ArrayList<>();
		final List<List<HoverCard.Pair>> rows = card.rows();
		for (int i = 1; i < rows.size(); i++)
		{
			if (!rows.get(i).isEmpty())
			{
				drops.add(rows.get(i).get(0));
			}
		}
		return drops;
	}

	/**
	 * The description set in lines for a card {@code width} px wide: a paragraph, or, when it holds line breaks, a
	 * numbered list.
	 *
	 * <p>With no line break in it the description is a paragraph: {@link #wrapToWidth}'s lines, at most {@code maxLines},
	 * every indent 0. With one it is a list: the items are the text between the breaks, trimmed, a blank one dropped,
	 * and item k begins "k. ". Each item's first line is its marker then its words, wrapped to {@code width}; each
	 * continuation line is wrapped to {@code width} less the indent and carries that indent, the width of the widest
	 * marker ({@code items.size() + ". "}), so a long item wraps under its own text. No full stop is added. The list
	 * takes at most {@code Math.max(maxLines, LIST_LINES)} lines, and when lines run out the last one kept ends in "..."
	 * (the marker kept), as a paragraph's does. An item wider than the line is cut as {@link #wrapToWidth} cuts a
	 * word. No text, or no item, gives no lines.
	 *
	 * <p>Choice: a list is not cut at the card's paragraph line count, so a level's unlocks show whole at any width;
	 * the wide card's two lines are for a paragraph, and a list there takes the same ten.
	 */
	static List<TextLine> layout(String description, FontMetrics metrics, int width, int maxLines)
	{
		final List<TextLine> lines = new ArrayList<>();
		if (description.indexOf('\n') < 0)
		{
			for (final String text : wrapToWidth(description, metrics, width, maxLines))
			{
				lines.add(new TextLine(text, 0));
			}
			return lines;
		}
		final List<String> items = itemsOf(description);
		final int cap = Math.max(maxLines, LIST_LINES);
		final int indent = metrics.stringWidth(items.size() + ". ");
		boolean cut = false;
		for (int k = 0; k < items.size() && !cut; k++)
		{
			final int room = cap - lines.size();
			final String full = (k + 1) + ". " + items.get(k);
			final String first = wrapToWidth(full, metrics, width, 2).get(0);
			lines.add(new TextLine(first, 0));
			final String rest = full.substring(first.length()).trim();
			final List<String> under = rest.isEmpty() ? new ArrayList<String>()
				: wrapToWidth(rest, metrics, Math.max(1, width - indent), room);
			for (int i = 0; i < under.size() && i < room - 1; i++)
			{
				lines.add(new TextLine(under.get(i), indent));
			}
			cut = under.size() > room - 1 || (lines.size() >= cap && k < items.size() - 1);
		}
		if (cut)
		{
			final TextLine last = lines.remove(lines.size() - 1);
			lines.add(new TextLine(withMore(last.text, metrics, Math.max(1, width - last.indent)), last.indent));
		}
		return lines;
	}

	/** The list's items: the description split at its line breaks, each trimmed with its spaces made single, blanks dropped. */
	private static List<String> itemsOf(String description)
	{
		final List<String> items = new ArrayList<>();
		for (final String part : description.split("\n"))
		{
			final String item = part.trim().replaceAll("\\s+", LABEL_GAP);
			if (!item.isEmpty())
			{
				items.add(item);
			}
		}
		return items;
	}

	/**
	 * The width the description asks for on one line, in px: a paragraph's whole text, or, for a list, its widest item
	 * with its marker.
	 */
	private static int descriptionNeed(String description, FontMetrics metrics)
	{
		if (description.indexOf('\n') < 0)
		{
			return metrics.stringWidth(description.trim().replaceAll("\\s+", LABEL_GAP));
		}
		final List<String> items = itemsOf(description);
		int need = 0;
		for (int k = 0; k < items.size(); k++)
		{
			need = Math.max(need, metrics.stringWidth((k + 1) + ". " + items.get(k)));
		}
		return need;
	}

	/**
	 * The text broken into lines of whole words no wider than {@code width} px in {@code metrics}, at most
	 * {@code maxLines}; a word wider than the width is broken. When words are left over the last line ends in "..." and
	 * still fits: whole words are dropped from its end until it does. An empty text, or a count under one, gives no
	 * lines. The wrapping stops as soon as it has one line more than it keeps, so a long paragraph costs no more than
	 * the lines shown.
	 */
	static List<String> wrapToWidth(String text, FontMetrics metrics, int width, int maxLines)
	{
		final List<String> lines = new ArrayList<>();
		final String trimmed = text.trim();
		if (trimmed.isEmpty() || maxLines < 1)
		{
			return lines;
		}
		String current = "";
		for (String word : trimmed.split("\\s+"))
		{
			final String joined = current.isEmpty() ? word : current + " " + word;
			if (metrics.stringWidth(joined) <= width)
			{
				current = joined;
				continue;
			}
			if (!current.isEmpty())
			{
				lines.add(current);
				current = "";
			}
			while (lines.size() <= maxLines && metrics.stringWidth(word) > width && word.length() > 1)
			{
				int cut = word.length() - 1;
				while (cut > 1 && metrics.stringWidth(word.substring(0, cut)) > width)
				{
					cut--;
				}
				lines.add(word.substring(0, cut));
				word = word.substring(cut);
			}
			if (lines.size() > maxLines)
			{
				break;
			}
			current = word;
		}
		if (lines.size() <= maxLines && !current.isEmpty())
		{
			lines.add(current);
		}
		if (lines.size() <= maxLines)
		{
			return lines;
		}
		final List<String> kept = new ArrayList<>(lines.subList(0, maxLines));
		kept.set(maxLines - 1, withMore(kept.get(maxLines - 1), metrics, width));
		return kept;
	}

	/** The line with "..." after it: whole words are dropped from its end until it fits {@code width} px, else it is cut. */
	private static String withMore(String line, FontMetrics metrics, int width)
	{
		String kept = line;
		while (metrics.stringWidth(kept + MORE) > width && kept.indexOf(' ') >= 0)
		{
			kept = kept.substring(0, kept.lastIndexOf(' '));
		}
		return fit(kept + MORE, metrics, width);
	}

	/** The text as it is when it fits in {@code width} px, else cut from its end and ending in "...". */
	private static String fit(String text, FontMetrics metrics, int width)
	{
		if (metrics.stringWidth(text) <= width)
		{
			return text;
		}
		String cut = text;
		while (cut.length() > 1 && metrics.stringWidth(cut + MORE) > width)
		{
			cut = cut.substring(0, cut.length() - 1);
		}
		return cut.trim() + MORE;
	}

	/** A row's width: each pair's label, value and note, with {@code gap} px between pairs. */
	static int rowWidth(List<HoverCard.Pair> row, FontMetrics metrics, int gap)
	{
		int width = 0;
		for (int i = 0; i < row.size(); i++)
		{
			final HoverCard.Pair pair = row.get(i);
			width += metrics.stringWidth(pair.label + LABEL_GAP) + metrics.stringWidth(pair.value)
				+ metrics.stringWidth(pair.note);
			if (i < row.size() - 1)
			{
				width += gap;
			}
		}
		return width;
	}

	/** Draws a row on {@code baseline}: each label in grey, its value in white, its note in grey, {@code gap} px between pairs. */
	private static void drawRow(Pen pen, Faces faces, List<HoverCard.Pair> row, int left, int baseline, int gap)
	{
		int x = left;
		for (final HoverCard.Pair pair : row)
		{
			final String head = pair.label + LABEL_GAP;
			pen.string(head, faces.body, LABEL, x, baseline);
			x += faces.bodyMetrics.stringWidth(head);
			pen.string(pair.value, faces.body, Color.WHITE, x, baseline);
			x += faces.bodyMetrics.stringWidth(pair.value);
			pen.string(pair.note, faces.body, LABEL, x, baseline);
			x += faces.bodyMetrics.stringWidth(pair.note) + gap;
		}
	}

	/** One line of the description as {@link #layout} sets it: its text, and how far in from the left it starts, in px. */
	static final class TextLine
	{
		final String text;
		final int indent;

		TextLine(String text, int indent)
		{
			this.text = text;
			this.indent = indent;
		}
	}

	/**
	 * One word of the drops line: its text in one colour, and a tail in the label grey set against it with no space, the
	 * comma after a drop, so that a line never breaks between a rate and its comma.
	 */
	private static final class Word
	{
		final String text;
		final Color colour;
		final String tail;

		Word(String text, Color colour, String tail)
		{
			this.text = text;
			this.colour = colour;
			this.tail = tail;
		}

		int width(FontMetrics metrics)
		{
			return metrics.stringWidth(text) + metrics.stringWidth(tail);
		}
	}

	/** The three fonts at one size, with their metrics and their line heights: ascent and descent, and 2. */
	private static final class Faces
	{
		final Font title;
		final Font body;
		final Font hint;
		final FontMetrics titleMetrics;
		final FontMetrics bodyMetrics;
		final FontMetrics hintMetrics;
		final int titleHeight;
		final int bodyHeight;
		final int hintHeight;

		Faces(Graphics2D g, int fontSize)
		{
			title = FontManager.getRunescapeBoldFont().deriveFont((float) fontSize);
			body = FontManager.getRunescapeFont().deriveFont((float) fontSize);
			hint = FontManager.getRunescapeSmallFont().deriveFont((float) fontSize);
			titleMetrics = g.getFontMetrics(title);
			bodyMetrics = g.getFontMetrics(body);
			hintMetrics = g.getFontMetrics(hint);
			titleHeight = lineHeight(titleMetrics);
			bodyHeight = lineHeight(bodyMetrics);
			hintHeight = lineHeight(hintMetrics);
		}

		private static int lineHeight(FontMetrics metrics)
		{
			return metrics.getAscent() + metrics.getDescent() + 2;
		}
	}

	/**
	 * What a layout draws with: draws when it is on, and when it is off only lets the layout learn its height, so one
	 * layout serves both the measuring and the painting.
	 */
	private static final class Pen
	{
		private final Graphics2D g;
		private final boolean draw;

		Pen(Graphics2D g, boolean draw)
		{
			this.g = g;
			this.draw = draw;
		}

		void string(String text, Font font, Color colour, int x, int baseline)
		{
			if (draw)
			{
				g.setFont(font);
				g.setColor(colour);
				g.drawString(text, x, baseline);
			}
		}

		void rule(int x, int y, int width, int height)
		{
			if (draw)
			{
				g.setColor(LINE);
				g.fillRect(x, y, width, height);
			}
		}

		void picture(BufferedImage image, int x, int y)
		{
			if (draw && image != null)
			{
				g.drawImage(image, x, y, null);
			}
		}

		/**
		 * Draws the picture centred, both ways, in the square box of {@code box} px whose top-left corner is ({@code x},
		 * {@code y}); a picture wider or taller than the box is drawn scaled down to fit it, its ratio kept (a guard: the
		 * overlay hands pictures already fitted).
		 */
		void pictureInBox(BufferedImage image, int x, int y, int box)
		{
			if (!draw || image == null)
			{
				return;
			}
			final int width = image.getWidth();
			final int height = image.getHeight();
			if (width <= box && height <= box)
			{
				g.drawImage(image, x + (box - width) / 2, y + (box - height) / 2, null);
				return;
			}
			final double scale = Math.min(box / (double) width, box / (double) height);
			final int fittedWidth = Math.max(1, (int) Math.round(width * scale));
			final int fittedHeight = Math.max(1, (int) Math.round(height * scale));
			g.drawImage(image, x + (box - fittedWidth) / 2, y + (box - fittedHeight) / 2, fittedWidth, fittedHeight, null);
		}
	}
}

package com.clanhub;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * The plugin's cards by plain chat line, the last 200 lines. The plugin fills it as chat messages arrive and the
 * overlay asks it about the text of the line under the mouse; shut-down clears it from another thread, so every method
 * is synchronized on the store itself.
 */
final class CardStore
{
	/** How many chat lines keep their cards. */
	private static final int MAX_LINES = 200;

	/** The cards by plain line, the oldest line first. */
	private final Map<String, List<HoverCard>> lines = new LinkedHashMap<>();

	/**
	 * What {@link #find} found: the cards of a stored line, and where that line starts inside the text it was found
	 * in.
	 */
	static final class Match
	{
		/** The cards the stored line holds, in the order their words stand in it. */
		final List<HoverCard> cards;
		/** Where the stored line starts inside the widget's text. */
		final int offset;

		Match(List<HoverCard> cards, int offset)
		{
			this.cards = cards;
			this.offset = offset;
		}
	}

	/**
	 * Keeps the cards for a plain chat line, and lets go of the oldest line when more than 200 are held. An empty list
	 * stores nothing.
	 *
	 * <p>Choice: a null or empty line stores nothing either, since every text contains the empty line and it would match
	 * everything; a line stored again becomes the newest, so "the most recent" holds for a repeated line.
	 */
	synchronized void put(String plainLine, List<HoverCard> cards)
	{
		if (plainLine == null || plainLine.isEmpty() || cards == null || cards.isEmpty())
		{
			return;
		}
		lines.remove(plainLine);
		lines.put(plainLine, Collections.unmodifiableList(new ArrayList<>(cards)));
		if (lines.size() > MAX_LINES)
		{
			final String oldest = lines.keySet().iterator().next();
			lines.remove(oldest);
		}
	}

	/**
	 * The most recently stored line that {@code widgetText} contains, with its cards and the place it starts inside
	 * {@code widgetText}; null when no stored line is in it. The chatbox puts the channel's prefix, and a timestamp
	 * another plugin adds, in the same widget, so the match is by containing, not by equal text.
	 */
	synchronized Match find(String widgetText)
	{
		if (widgetText == null)
		{
			return null;
		}
		Match newest = null;
		for (final Map.Entry<String, List<HoverCard>> entry : lines.entrySet())
		{
			final int at = widgetText.indexOf(entry.getKey());
			if (at >= 0)
			{
				newest = new Match(entry.getValue(), at);
			}
		}
		return newest;
	}

	/** Forgets every line. */
	synchronized void clear()
	{
		lines.clear();
	}
}

package com.clanhub;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * The quests, combat achievement tasks, pets, achievement diaries and skill unlocks of the Old School RuneScape Wiki,
 * from the table the plugin bundles ({@code /com/clanhub/cards.json}, built from the wiki and credited in its own
 * header), and the bosses' combat level, hitpoints, max hit and quest from the second table it bundles
 * ({@code /com/clanhub/bosses.json}, credited the same way): for a name, what the wiki says about it, and for a skill's
 * level, what the wiki lists as new at it. The tables are read once, off the client thread, a second or two after
 * start-up; until then, and for ever if the file is missing or unreadable, every lookup answers null and the cards of
 * these broadcasts are the plain ones. Parsing is pure and is the only part that needs the tables' shape.
 *
 * <p>Choice: the load task runs once; a plugin restart runs it again.
 *
 * <p>Choice: the boss table is a file of its own, and the load treats it apart from the cards: a boss file that is
 * missing or unreadable leaves {@link #boss} answering null and the rest of the table loaded, and when the card table
 * did not load nothing of the bosses is read.
 */
final class CardTables
{
	private static final Logger log = LoggerFactory.getLogger(CardTables.class);

	/** Where the bundled table lives on the classpath. */
	private static final String RESOURCE = "/com/clanhub/cards.json";

	/** Where the bundled boss table lives on the classpath. */
	private static final String BOSSES = "/com/clanhub/bosses.json";

	/** What the wiki says of a quest. */
	static final class QuestInfo
	{
		/** The difficulty, such as "Grandmaster". */
		final String difficulty;
		/** The length, such as "Very Long". */
		final String length;
		/** The quest points it gives. */
		final int points;
		/** The wiki page, such as "Dragon_Slayer_II". */
		final String wiki;

		QuestInfo(String difficulty, String length, int points, String wiki)
		{
			this.difficulty = difficulty;
			this.length = length;
			this.points = points;
			this.wiki = wiki;
		}
	}

	/** What the wiki says of a combat achievement task. */
	static final class TaskInfo
	{
		/** The tier, such as "Master". */
		final String tier;
		/** The points it gives. */
		final int points;
		/** The monster it is about, such as "Zulrah". */
		final String monster;
		/** The kind of task, such as "Perfection". */
		final String type;
		/** The task's description, as the wiki writes it. */
		final String description;
		/** The wiki page, such as "Perfect_Zulrah". */
		final String wiki;

		TaskInfo(String tier, int points, String monster, String type, String description, String wiki)
		{
			this.tier = tier;
			this.points = points;
			this.monster = monster;
			this.type = type;
			this.description = description;
			this.wiki = wiki;
		}
	}

	/** What the wiki says of a pet. */
	static final class PetInfo
	{
		/** The pet's name as the wiki spells it, such as "Pet Snakeling". */
		final String name;
		/** What it comes from, such as "Zulrah". */
		final String source;
		/** The wiki page, such as "Pet_Snakeling". */
		final String wiki;
		/** The id of the pet's item, whose sprite is the card's picture; 0 when the table has none. */
		final int itemId;

		PetInfo(String name, String source, String wiki, int itemId)
		{
			this.name = name;
			this.source = source;
			this.wiki = wiki;
			this.itemId = itemId;
		}
	}

	/** What the wiki says of an achievement diary's area. */
	static final class DiaryInfo
	{
		/** The area as the wiki spells it, such as "Lumbridge & Draynor". */
		final String name;
		/** The wiki page, such as "Ardougne_Diary". */
		final String wiki;

		DiaryInfo(String name, String wiki)
		{
			this.name = name;
			this.wiki = wiki;
		}
	}

	/** What the wiki says of a boss, or of a raid, with the quest it goes with. */
	static final class BossInfo
	{
		/** The boss's name as the pets' table and the game spell it, such as "Duke Sucellus". */
		final String name;
		/** The wiki page, such as "Duke_Sucellus". */
		final String wiki;
		/** The combat level as the wiki writes it, such as "758"; empty when the wiki has none. */
		final String combat;
		/** The hitpoints as the wiki writes them, such as "485"; empty when the wiki has none. */
		final String hitpoints;
		/** The max hit as the wiki writes it, such as "56 (Melee)"; empty when the wiki has none. */
		final String maxHit;
		/** The quest the boss belongs to, such as "Desert Treasure II - The Fallen Empire"; empty when it has none. */
		final String quest;

		BossInfo(String name, String wiki, String combat, String hitpoints, String maxHit, String quest)
		{
			this.name = name;
			this.wiki = wiki;
			this.combat = combat;
			this.hitpoints = hitpoints;
			this.maxHit = maxHit;
			this.quest = quest;
		}
	}

	/** A table read whole: each kind by its name's key. */
	private static final class Table
	{
		private final Map<String, QuestInfo> quests = new HashMap<>();
		private final Map<String, TaskInfo> tasks = new HashMap<>();
		private final Map<String, PetInfo> pets = new HashMap<>();
		private final Map<String, DiaryInfo> diaries = new HashMap<>();
		private final Map<String, BossInfo> bosses = new HashMap<>();
		/** Each skill's key, then each level with unlocks, to what the wiki lists as new at it. */
		private final Map<String, Map<Integer, List<String>>> unlocks = new HashMap<>();
	}

	/** The table once loaded; null until the load has published it. */
	private volatile Table table;

	/** A table that has not loaded: every lookup answers null and {@link #loaded()} is false. */
	CardTables()
	{
	}

	private CardTables(Table table)
	{
		this.table = table;
	}

	/**
	 * Reads the table's shape: {@code {"quests": [...], "achievements": [...], "pets": [...], "diaries": [...],
	 * "unlocks": {...}}}, each entry of an array an object with a {@code name} and the members of its info class, and
	 * {@code unlocks} an object of the skills, each an object of its levels (a decimal text) to an array of texts, what
	 * the wiki lists as new at that level. A missing array or object gives none of that kind, and the table still counts
	 * as loaded.
	 *
	 * <p>Choice: an entry with no {@code name} is skipped, a missing text member reads as an empty text and a missing
	 * number as 0, and a name met twice keeps its first entry; in {@code unlocks} a skill that is not an object, a level
	 * that is not a whole number or whose value is not an array, and an element of that array that is not a text, are
	 * each skipped; nothing in the file's shape that is merely odd stops the rest of the table being read.
	 *
	 * @throws com.google.gson.JsonParseException when the text is not JSON
	 */
	static CardTables parse(Reader json, Gson gson)
	{
		final Table read = new Table();
		final JsonObject root = gson.fromJson(json, JsonObject.class);
		if (root != null)
		{
			for (final JsonObject entry : objectsOf(root, "quests"))
			{
				read.quests.putIfAbsent(key(text(entry, "name")), new QuestInfo(text(entry, "difficulty"),
					text(entry, "length"), number(entry, "points"), text(entry, "wiki")));
			}
			for (final JsonObject entry : objectsOf(root, "achievements"))
			{
				read.tasks.putIfAbsent(key(text(entry, "name")), new TaskInfo(text(entry, "tier"),
					number(entry, "points"), text(entry, "monster"), text(entry, "type"), text(entry, "description"),
					text(entry, "wiki")));
			}
			for (final JsonObject entry : objectsOf(root, "pets"))
			{
				read.pets.putIfAbsent(key(text(entry, "name")),
					new PetInfo(text(entry, "name"), text(entry, "source"), text(entry, "wiki"), number(entry, "item")));
			}
			for (final JsonObject entry : objectsOf(root, "diaries"))
			{
				read.diaries.putIfAbsent(key(text(entry, "name")),
					new DiaryInfo(text(entry, "name"), text(entry, "wiki")));
			}
			readUnlocks(root, read.unlocks);
		}
		return new CardTables(read);
	}

	/**
	 * Reads the boss table's shape, {@code {"bosses": [...]}}, each entry an object with a {@code name} and the members of
	 * {@link BossInfo}, into this table, and returns this table. A missing array gives no bosses.
	 *
	 * <p>Choice: an entry with no {@code name} is skipped, a missing text member reads as an empty text, a member the
	 * class has no field for (the bundled file still carries each boss's {@code petItem}) is ignored, and a name met twice
	 * keeps its first entry, as {@link #parse} reads the other kinds.
	 *
	 * @throws IllegalStateException when this table has not loaded: the bosses are added to a table {@link #parse} made
	 * @throws com.google.gson.JsonParseException when the text is not JSON
	 */
	CardTables readBosses(Reader json, Gson gson)
	{
		if (table == null)
		{
			throw new IllegalStateException("the boss table is read into a table that has loaded");
		}
		final JsonObject root = gson.fromJson(json, JsonObject.class);
		if (root != null)
		{
			for (final JsonObject entry : objectsOf(root, "bosses"))
			{
				table.bosses.putIfAbsent(key(text(entry, "name")), new BossInfo(text(entry, "name"), text(entry, "wiki"),
					text(entry, "combat"), text(entry, "hitpoints"), text(entry, "maxHit"), text(entry, "quest")));
			}
		}
		return this;
	}

	/**
	 * Reads the {@code unlocks} member of the root into {@code into}: the skill's key, then each level that has at least
	 * one text to its list of them, in the file's order. A skill met twice keeps its first entry.
	 */
	private static void readUnlocks(JsonObject root, Map<String, Map<Integer, List<String>>> into)
	{
		final JsonElement skills = root.get("unlocks");
		if (skills == null || !skills.isJsonObject())
		{
			return;
		}
		for (final Map.Entry<String, JsonElement> skill : skills.getAsJsonObject().entrySet())
		{
			if (!skill.getValue().isJsonObject() || key(skill.getKey()).isEmpty())
			{
				continue;
			}
			final Map<Integer, List<String>> levels = new HashMap<>();
			for (final Map.Entry<String, JsonElement> level : skill.getValue().getAsJsonObject().entrySet())
			{
				final Integer number = wholeNumber(level.getKey());
				if (number == null || !level.getValue().isJsonArray())
				{
					continue;
				}
				final List<String> unlocks = new ArrayList<>();
				for (final JsonElement unlock : level.getValue().getAsJsonArray())
				{
					if (unlock.isJsonPrimitive() && unlock.getAsJsonPrimitive().isString())
					{
						unlocks.add(unlock.getAsString());
					}
				}
				levels.putIfAbsent(number, Collections.unmodifiableList(unlocks));
			}
			into.putIfAbsent(key(skill.getKey()), levels);
		}
	}

	/** The whole number a text spells in decimal, or null when it spells none. */
	private static Integer wholeNumber(String text)
	{
		try
		{
			return Integer.valueOf(text.trim());
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/** The objects of a member's array that have a name, in the file's order; none when the member is not an array. */
	private static List<JsonObject> objectsOf(JsonObject root, String member)
	{
		final List<JsonObject> objects = new ArrayList<>();
		final JsonElement array = root.get(member);
		if (array == null || !array.isJsonArray())
		{
			return objects;
		}
		for (final JsonElement entry : array.getAsJsonArray())
		{
			if (entry.isJsonObject() && !text(entry.getAsJsonObject(), "name").isEmpty())
			{
				objects.add(entry.getAsJsonObject());
			}
		}
		return objects;
	}

	/** The text of a member, or an empty text when it is missing or is not a string. */
	private static String text(JsonObject object, String member)
	{
		final JsonElement value = object.get(member);
		return value != null && value.isJsonPrimitive() ? value.getAsString() : "";
	}

	/** The whole number of a member, or 0 when it is missing or is not a number. */
	private static int number(JsonObject object, String member)
	{
		final JsonElement value = object.get(member);
		return value != null && value.isJsonPrimitive() && value.getAsJsonPrimitive().isNumber() ? value.getAsInt() : 0;
	}

	/**
	 * The key a name is kept and looked up by: a no-break space read as a space, the surrounding spaces and the trailing
	 * dots taken off ("Another Slice of H.A.M." and "Another Slice of H.A.M" are one name), in lower case.
	 */
	private static String key(String name)
	{
		final String spaced = name.replace((char) 160, ' ').trim();
		int end = spaced.length();
		while (end > 0 && (spaced.charAt(end - 1) == '.' || spaced.charAt(end - 1) == ' '))
		{
			end--;
		}
		return spaced.substring(0, end).toLowerCase(Locale.ROOT);
	}

	/**
	 * The quest called {@code name}, ignoring case, trailing dots and surrounding spaces, or null when the table does
	 * not know it or has not loaded.
	 *
	 * <p>Choice: the lookups ask {@link #loaded()} first; the table is published once and never taken back, so what
	 * follows may read it.
	 */
	QuestInfo quest(String name)
	{
		return loaded() && name != null ? table.quests.get(key(name)) : null;
	}

	/** The combat achievement task called {@code name}, matched as {@link #quest} matches; null when unknown. */
	TaskInfo achievement(String name)
	{
		return loaded() && name != null ? table.tasks.get(key(name)) : null;
	}

	/** The pet called {@code name}, matched as {@link #quest} matches; null when unknown. */
	PetInfo pet(String name)
	{
		return loaded() && name != null ? table.pets.get(key(name)) : null;
	}

	/**
	 * The boss, monster or raid called {@code name}, matched as {@link #quest} matches; null when the boss table does not
	 * know it or has not loaded.
	 */
	BossInfo boss(String name)
	{
		return loaded() && name != null ? table.bosses.get(key(name)) : null;
	}

	/** The achievement diary of the area called {@code area}, matched as {@link #quest} matches; null when unknown. */
	DiaryInfo diary(String area)
	{
		return loaded() && area != null ? table.diaries.get(key(area)) : null;
	}

	/**
	 * What the wiki lists as new at {@code level} of the skill called {@code skill}, ignoring case, in the table's order
	 * and at most a handful: an empty list when the table has the skill but nothing at that level, and null when the
	 * table has not loaded or has no object for the skill (so the caller can tell "nothing new" from "do not know").
	 */
	List<String> unlocks(String skill, int level)
	{
		if (!loaded() || skill == null)
		{
			return null;
		}
		final Map<Integer, List<String>> levels = table.unlocks.get(key(skill));
		if (levels == null)
		{
			return null;
		}
		final List<String> found = levels.get(level);
		return found == null ? Collections.<String>emptyList() : found;
	}

	/** Whether the table has been read and published. */
	boolean loaded()
	{
		return table != null;
	}

	/**
	 * Reads the bundled table on the executor and publishes it. A missing resource or a table that does not parse leaves
	 * this empty and logs one warning naming the cause; nothing is thrown out of the task.
	 *
	 * <p>Choice: after a failed load {@link #loaded()} stays false, since nothing was published.
	 */
	void loadInBackground(ScheduledExecutorService executor, Gson gson)
	{
		executor.execute(() -> load(gson));
	}

	/** The load task: two classpath reads, two parses, one publish. */
	private void load(Gson gson)
	{
		try (InputStream in = CardTables.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				log.warn("The card table {} is not in the plugin; the cards show what the chat line says and no more", RESOURCE);
				return;
			}
			final CardTables read = parse(new InputStreamReader(in, StandardCharsets.UTF_8), gson);
			readBossTable(read, gson);
			table = read.table;
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("The card table {} could not be read ({}); the cards show what the chat line says and no more", RESOURCE,
				e.toString());
		}
	}

	/**
	 * Reads the bundled boss table into {@code into}, which has not been published. A missing resource or a table that
	 * does not parse logs one warning naming the cause and leaves the bosses empty; nothing is thrown out of it.
	 */
	private static void readBossTable(CardTables into, Gson gson)
	{
		try (InputStream in = CardTables.class.getResourceAsStream(BOSSES))
		{
			if (in == null)
			{
				log.warn("The boss table {} is not in the plugin; the boss cards show no facts", BOSSES);
				return;
			}
			into.readBosses(new InputStreamReader(in, StandardCharsets.UTF_8), gson);
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("The boss table {} could not be read ({}); the boss cards show no facts", BOSSES, e.toString());
		}
	}
}

package com.clanhub;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws the card while the mouse is on the card's words in a chat line, and, while the mouse is anywhere on a line that
 * holds cards, underlines the words of every quiet card on it in the hover colour (the hover-reveal; the quiet level, total
 * level and XP phrases, the kill count and personal best answers and the boss of a drop line show themselves this way; a
 * blue word is its own signal and carries no underline). With "Underline level-ups" on, those quiet phrases carry a line in
 * the underline colour on every visible chat line, mouse or no mouse. The "Card place" setting says where: the split card centred above the cursor, or the wide card as wide as
 * the chatbox and pinned above its frame. It finds the line by walking the chatbox's line widgets for the one under the mouse
 * whose plain text holds a line the plugin has cards for, and a card shows only while the mouse is on that card's own
 * words, not elsewhere on the row, with one exception, the hold: when the chat moves under a mouse that has not moved
 * (a new line arrives and the rows shift up) the card stays where it is until the mouse moves more than {@link #HOLD_JITTER}
 * px from where it rested, the mouse wheel turns, or the mouse leaves the chat's area. A line the game wrapped into rows is one widget, so it is read row by row
 * ({@link ChatRows}): a card's words are hit and underlined on the row they fall on, a card whose words break across
 * the rows gets a piece on each. Only while the mouse is inside the chat's scroll area: a line scrolled out of the
 * chat is not hidden, its rectangle sits over the game world, so outside the area the card and the hover-reveal are off
 * whatever the lines say, and the always-underline keeps to the lines whose underline row is inside the area. The card
 * waits on {@link CardGate}: for the show mode (on hover; while the plugin's key is held, which the plugin
 * tells through {@link #keyHeld}; or on a click, which it tells through {@link #clicked}: the card then opens on the
 * words that were clicked and stays while the mouse is on them) and for the delay since the mouse came onto the words.
 * A card with notes of its own shows them as its description; a card with none gets the first paragraph of its wiki page
 * while "Wiki descriptions" is on, and asks for it again if it has not come yet. A line RuneLite rewrites after it arrives
 * (the Chat Commands plugin's kill count and personal best answers, which no chat event ever carries) is read as drawn
 * when the mouse reaches it ({@link ChatCommandReader}), and from then on it is a stored line like any other, so the
 * always-underline reaches it only after that. The card of a boss, monster, raid or chest shows the wiki's own picture of
 * its page in its big picture box while "Wiki pictures" is on, asked for as the card is hovered if the line's arrival
 * has not asked yet, with the card's own item or sprite in the box until the picture comes. It never changes the chat text.
 * Everything here runs on the client thread, in the draw call.
 */
public class ChatCardOverlay extends Overlay
{
	/** A chat line is one text row at most this tall; a taller widget is rows, or a line the game broke where we did not. */
	private static final int ONE_ROW = 16;
	/** The mouse has to move more than this many px before the line widgets are walked again. */
	private static final int MOVE_THRESHOLD = 3;
	/** A place the mouse never is, so the first frame always walks. */
	private static final int NOWHERE = -1000;
	/** A held card lets the mouse drift this many px, on either axis, from where it rested, before the hold ends. */
	private static final int HOLD_JITTER = 2;

	private final Client client;
	private final ClanHubConfig config;
	private final ItemManager itemManager;
	private final SpriteManager spriteManager;
	/** A scrap of canvas the card is painted on to learn its size before it is placed. */
	private final BufferedImage scratch = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);

	/**
	 * The plugin's cards by plain line. The store matches the text that HOLDS a card's line, because the chatbox puts the
	 * channel's prefix, and a timestamp another plugin adds, in the same widget.
	 *
	 * <p>Choice: an empty store of its own until the plugin hands over its own, so the overlay never meets null.
	 */
	private CardStore store = new CardStore();
	/**
	 * The wiki's first paragraphs, handed over by the plugin at start-up; null means the cards show no paragraph.
	 *
	 * <p>Choice: volatile, because start-up writes it on a thread other than the client thread that reads it.
	 */
	private volatile WikiSummaries summaries;
	/**
	 * The wiki's pictures of the boss, monster, raid and chest pages, handed over by the plugin at start-up; null means the
	 * cards show their own icon.
	 *
	 * <p>Choice: volatile, like {@link #summaries}.
	 */
	private volatile WikiPictures pictures;
	/**
	 * The bosses' facts, handed over by the plugin at start-up, for the cards of the Chat Commands answers.
	 *
	 * <p>Choice: a table of its own that has not loaded until the plugin hands over its own, so an answer read before then
	 * gives its card without facts and the overlay never meets null; volatile, like {@link #summaries}.
	 */
	private volatile CardTables tables = new CardTables();
	/** The card under the mouse, for the menu; null when the mouse is off a card line. */
	private volatile HoverCard hovered;
	/** Where the line widgets were last walked from, and what the walk found. */
	private int walkedX = NOWHERE;
	private int walkedY = NOWHERE;
	private Widget hitLine;
	private CardStore.Match hitMatch;
	private HoverCard hitCard;
	/** The line the mouse is on that holds cards, whether or not the mouse is on a card's words; null when there is none. */
	private Widget rowLine;
	private CardStore.Match rowMatch;
	/** When the mouse came onto the hit card's words, in {@link System#nanoTime} terms. */
	private long hitSince;
	/** Whether the plugin's card key is held, set from the key listener's thread. */
	private volatile boolean keyHeld;
	/** Whether a click has landed since the last frame, set from the mouse listener's thread. */
	private volatile boolean clickPending;
	/** The card whose words were clicked last, kept while the mouse stays on them; null when nothing is clicked open. */
	private HoverCard clickedCard;
	/** Where the mouse was at the previous frame inside the chat's area, {@link #NOWHERE} when it was outside or off. */
	private int lastX = NOWHERE;
	private int lastY = NOWHERE;
	/** The card shown at the last frame that showed one, null when the mouse has been off every card since. */
	private HoverCard held;
	/** When the mouse came onto the held card's words, as {@link #hitSince} counts it. */
	private long heldSince;
	/** Where the mouse was when the held card was last hit on its words. */
	private int heldX;
	private int heldY;
	/** Whether the card the last frame showed was the held one, the chat having moved off its words under a still mouse. */
	private boolean holding;
	/**
	 * Whether the mouse wheel has turned since the last frame, set from the wheel listener's thread.
	 *
	 * <p>Choice: volatile, because the listener writes it on a thread other than the client thread that reads it.
	 */
	private volatile boolean wheelTurned;

	@Inject
	ChatCardOverlay(Client client, ClanHubConfig config, ItemManager itemManager, SpriteManager spriteManager)
	{
		this.client = client;
		this.config = config;
		this.itemManager = itemManager;
		this.spriteManager = spriteManager;
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_HIGH);
	}

	/** Hands the overlay the plugin's cards and forgets what it found before: called when the plugin starts. */
	void attach(CardStore store)
	{
		this.store = store;
		forget();
		walkedX = NOWHERE;
		walkedY = NOWHERE;
	}

	/**
	 * Hands the overlay the wiki's first paragraphs, which a card shows under its rows while "Wiki descriptions" is on;
	 * null for none: called when the plugin starts.
	 */
	void summaries(WikiSummaries summaries)
	{
		this.summaries = summaries;
	}

	/**
	 * Hands the overlay the wiki's pictures, which the cards of a boss, monster, raid or chest show in their big picture box
	 * while "Wiki pictures" is on; null for none: called when the plugin starts, beside {@link #summaries}.
	 */
	void pictures(WikiPictures pictures)
	{
		this.pictures = pictures;
	}

	/**
	 * Hands the overlay the bosses' table, whose facts the cards of the Chat Commands answers carry: called when
	 * the plugin starts, beside {@link #attach} and {@link #summaries}.
	 */
	void tables(CardTables tables)
	{
		this.tables = tables;
	}

	/** The card under the mouse as of the last frame, or null; what the menu reads. */
	HoverCard hovered()
	{
		return hovered;
	}

	/** Tells the overlay whether the card key is held: the plugin's card key listener calls it on press and release, and when the window loses focus. */
	void keyHeld(boolean held)
	{
		keyHeld = held;
	}

	/** Tells the overlay a left click landed: the plugin's mouse listener calls it, and the next frame reads where. */
	void clicked()
	{
		clickPending = true;
	}

	/**
	 * Tells the overlay the mouse wheel turned, anywhere: the plugin's wheel listener calls it, and the next frame ends the
	 * hold of a card, a wheel turn counting as a move of the mouse.
	 */
	void wheeled()
	{
		wheelTurned = true;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.showCards())
		{
			forget();
			return null;
		}
		final Widget area = client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
		final Rectangle areaBounds = area == null || area.isHidden() ? null : area.getBounds();
		// The chat font's metrics: the card is picked and the underline drawn with the same ones, so the two agree.
		final FontMetrics metrics = g.getFontMetrics(FontManager.getRunescapeFont());
		// Choice: the always-underline is drawn before the mouse is looked at, so it shows with the mouse anywhere, or
		// nowhere; the frame then goes on as it always did.
		if (areaBounds != null && config.alwaysUnderlineLevels())
		{
			underlineQuiet(g, area, areaBounds, metrics);
		}
		final net.runelite.api.Point mouse = client.getMouseCanvasPosition();
		if (mouse == null)
		{
			forget();
			return null;
		}
		final int mouseX = mouse.getX();
		final int mouseY = mouse.getY();
		// Choice: nothing outside the chat's scroll area. The lines scrolled out of the chat are still its children, with
		// rectangles over the game world, and NOWHERE makes the first frame back inside walk again.
		if (areaBounds == null || !areaBounds.contains(mouseX, mouseY))
		{
			forget();
			walkedX = NOWHERE;
			walkedY = NOWHERE;
			return null;
		}

		final boolean moved = Math.abs(mouseX - walkedX) > MOVE_THRESHOLD || Math.abs(mouseY - walkedY) > MOVE_THRESHOLD;
		if (moved || (hitLine != null && !stillHit(mouseX, mouseY, metrics))
			|| (rowLine != null && !stillRow(mouseX, mouseY)))
		{
			final HoverCard before = hitCard;
			final long beforeSince = hitSince;
			walkedX = mouseX;
			walkedY = mouseY;
			walk(area, mouseX, mouseY, metrics);
			// Choice: the delay counts from when the mouse came onto the words, so a walk that finds the same card again
			// keeps the time the first one began, and a small move on the words does not start the wait over.
			hitSince = hitCard != null && hitCard == before ? beforeSince : System.nanoTime();
		}
		// Choice: a click on the words keeps that card open and a click anywhere else (no hit) closes it; the mouse moving
		// off the words, onto another card or none, closes it too, so coming back needs a new click.
		if (clickPending)
		{
			clickPending = false;
			clickedCard = hitCard;
		}
		// Choice: the hold. When the card is lost to the chat moving under a mouse that has not moved at all since the
		// frame before (a new line arrives and the rows shift up), the card shown stays the held one while the hand rests:
		// within HOLD_JITTER px of where it rested, no wheel turn. A move off the words is the player's doing and drops the
		// card, even by a pixel, so the hold begins only on an unmoved mouse; the chat shifting is not. The walk's own
		// result (hitCard, hitSince and the row) is left as it is, so the walk keeps its bookkeeping and the hover-reveal
		// keeps following the line under the pointer; the card shown is a local.
		HoverCard shown = hitCard;
		long shownSince = hitSince;
		final boolean still = mouseX == lastX && mouseY == lastY;
		final boolean near = Math.abs(mouseX - heldX) <= HOLD_JITTER && Math.abs(mouseY - heldY) <= HOLD_JITTER;
		if (held != null && shown != held && !wheelTurned && (holding ? near : still))
		{
			shown = held;
			shownSince = heldSince;
			holding = true;
		}
		else
		{
			holding = false;
			if (shown != null)
			{
				held = shown;
				heldSince = shownSince;
				heldX = mouseX;
				heldY = mouseY;
			}
			else
			{
				held = null;
			}
		}
		wheelTurned = false;
		lastX = mouseX;
		lastY = mouseY;
		// The clicked card stays clicked while it is the card shown, held or hit.
		if (clickedCard != shown)
		{
			clickedCard = null;
		}
		hovered = shown;
		// Choice: the hover-reveal, before the gate: the mouse anywhere on a line that holds cards underlines the words of
		// every quiet card on it, whatever the show mode and the delay say about the card. A marked card's words are
		// already coloured in the chat, so they carry no underline of their own while the colouring is on.
		if (rowLine != null)
		{
			for (final HoverCard card : rowMatch.cards)
			{
				if (!card.marked() || !config.colourHoverables())
				{
					underline(g, rowLine, card, rowMatch.offset, metrics, config.hoverColour());
				}
			}
		}
		final boolean clicked = shown != null && shown == clickedCard;
		if (shown == null
			|| !CardGate.shows(config.cardTrigger(), keyHeld, clicked, shownSince, System.nanoTime(), config.cardDelayMs()))
		{
			return null;
		}

		final BufferedImage picture = pictureOf(shown);
		final int fontSize = config.cardFontSize();
		final Graphics2D measure = scratch.createGraphics();
		measure.setRenderingHints(g.getRenderingHints());
		if (config.cardPlace() == ClanHubConfig.CardPlace.CHAT)
		{
			// Choice: the chatbox's whole frame sets the wide card's width and place, the scroll area's bounds when the
			// frame is not shown.
			final Rectangle chat = chatFrame(areaBounds);
			final String description = descriptionOf(shown);
			final Color accent = config.hoverColour();
			final Dimension size = CardPainter.paintWide(measure, shown, picture, fontSize, chat.width, 0, 0, description,
				accent);
			measure.dispose();
			final Rectangle at = CardPainter.placeAboveChat(chat, size);
			CardPainter.paintWide(g, shown, picture, fontSize, chat.width, at.x, at.y, description, accent);
			return null;
		}
		final String description = descriptionOf(shown);
		final ClanHubConfig.CardWidth width = config.cardWidth();
		final Dimension size = CardPainter.paintSplit(measure, shown, picture, fontSize, 0, 0, description, width.cap,
			width.lines);
		measure.dispose();
		final Rectangle at = CardPainter.placeCentred(new Point(mouseX, mouseY), size,
			new Dimension(client.getCanvasWidth(), client.getCanvasHeight()));
		CardPainter.paintSplit(g, shown, picture, fontSize, at.x, at.y, description, width.cap, width.lines);
		return null;
	}

	/** The bounds of the chatbox's frame, or {@code fallback} when the frame is not there or not shown. */
	private Rectangle chatFrame(Rectangle fallback)
	{
		final Widget frame = client.getWidget(InterfaceID.Chatbox.UNIVERSE);
		if (frame != null && !frame.isHidden())
		{
			final Rectangle bounds = frame.getBounds();
			if (bounds != null)
			{
				return bounds;
			}
		}
		return fallback;
	}

	/**
	 * The text of the card's description, which the painter lays out in the card: the card's own notes when it has any,
	 * else the first paragraph of its wiki page, else "". One note is the text alone, a paragraph; two or more are joined
	 * with a line break, which the painter sets as a numbered list, one note to an item. "" for the paragraph when the
	 * "Wiki descriptions" setting is off, when no summaries were handed over, and when it has not come yet, in which case
	 * it is asked for again, which does nothing while the first call is still waiting.
	 */
	private String descriptionOf(HoverCard card)
	{
		final List<String> notes = card.notes();
		if (notes.size() == 1)
		{
			return notes.get(0);
		}
		if (notes.size() > 1)
		{
			return String.join("\n", notes);
		}
		final WikiSummaries asked = summaries;
		if (asked == null || !config.wikiDescriptions())
		{
			return "";
		}
		final String paragraph = asked.summaryOf(card.wikiTitle());
		if (paragraph == null)
		{
			asked.fetch(card.wikiTitle());
			return "";
		}
		return paragraph;
	}

	/**
	 * The card's picture: for a card that wants the wiki's own, while "Wiki pictures" is on, the one kept for its page, and
	 * when none is kept the page is asked for again, which does nothing while the first call is waiting or the page is
	 * known to have none; then the item's sprite, else the game's own sprite, else none.
	 */
	private BufferedImage pictureOf(HoverCard card)
	{
		final WikiPictures asked = pictures;
		if (card.wikiPicture() && asked != null && config.wikiPictures())
		{
			final BufferedImage wiki = asked.pictureOf(card.wikiTitle());
			if (wiki != null)
			{
				return wiki;
			}
			asked.fetch(card.wikiTitle());
		}
		if (card.itemId() >= 0)
		{
			return itemManager.getImage(card.itemId(), card.quantity(), card.quantity() > 1);
		}
		if (card.spriteId() >= 0)
		{
			return spriteManager.getSprite(card.spriteId(), 0);
		}
		return null;
	}

	/**
	 * Lets go of the last hit, and of a click not yet read or a card opened by one: a click that lands while the mouse is
	 * outside the chat's scroll area, or the cards are off, counts as a click elsewhere and must not open a card later.
	 * It lets go of the held card too, and of where the mouse was, so the first frame back is never a still one.
	 */
	private void forget()
	{
		clearHit();
		clickPending = false;
		clickedCard = null;
		held = null;
		holding = false;
		lastX = NOWHERE;
		lastY = NOWHERE;
	}

	/** Lets go of the last hit alone: the walk starts from here, and a click's card is kept while the mouse stays on it. */
	private void clearHit()
	{
		hitLine = null;
		hitMatch = null;
		hitCard = null;
		rowLine = null;
		rowMatch = null;
		hovered = null;
	}

	/**
	 * Whether the last hit's line is still under the mouse, still says what it said, and the mouse is still on the hit
	 * card's own words: a move of a pixel or two off them, under the walk threshold, drops the hit.
	 */
	private boolean stillHit(int mouseX, int mouseY, FontMetrics metrics)
	{
		final Rectangle bounds = hitLine.getBounds();
		if (hitLine.isHidden() || bounds == null || !bounds.contains(mouseX, mouseY))
		{
			return false;
		}
		final String plain = plain(hitLine);
		if (!holds(plain, hitCard))
		{
			return false;
		}
		final int offset = plain.indexOf(hitCard.plainLine());
		return ChatRows.of(plain, metrics::stringWidth, bounds).pick(hitMatch.cards, offset, mouseX, mouseY) == hitCard;
	}

	/**
	 * Whether the last row's line is still under the mouse and still says the stored line it said: a line that scrolled
	 * away, or was replaced by a new message, drops the row.
	 */
	private boolean stillRow(int mouseX, int mouseY)
	{
		final Rectangle bounds = rowLine.getBounds();
		if (rowLine.isHidden() || bounds == null || !bounds.contains(mouseX, mouseY))
		{
			return false;
		}
		final String plain = plain(rowLine);
		final CardStore.Match now = plain == null ? null : store.find(plain);
		return now != null && now.cards == rowMatch.cards && now.offset == rowMatch.offset;
	}

	/** Whether a widget's plain text holds the card's line. */
	private static boolean holds(String text, HoverCard card)
	{
		return text != null && text.contains(card.plainLine());
	}

	/**
	 * Walks the chatbox's line widgets, the dynamic children of the scroll area {@code render} found the mouse inside, and
	 * then the static ones, for the first that is shown, has the mouse inside its bounds and says a line the plugin has
	 * cards for (the row), and for the first of those whose card's words hold the mouse (the hit). With the mouse inside
	 * the area, a line scrolled out of it cannot hold the mouse, and a line half scrolled hits only in the part that shows.
	 */
	private void walk(Widget area, int mouseX, int mouseY, FontMetrics metrics)
	{
		clearHit();
		if (!find(area.getDynamicChildren(), mouseX, mouseY, metrics))
		{
			find(area.getStaticChildren(), mouseX, mouseY, metrics);
		}
	}

	/**
	 * Looks through one group of widgets; true when the hit is set. A widget is a hit only when the mouse is on the words
	 * of one of its cards, so the hit's line, match and card are always set together or not at all. The row is the first
	 * widget the mouse is on that says a line the plugin has cards for, set even when the mouse is not on any card's words
	 * in it; a hit makes its own widget the row. A widget the store has nothing for is read once as a line RuneLite
	 * rewrote after it arrived ({@link #readLate}), and a card found that way is stored, so it is a stored line from then on.
	 */
	private boolean find(Widget[] widgets, int mouseX, int mouseY, FontMetrics metrics)
	{
		if (widgets == null)
		{
			return false;
		}
		for (final Widget widget : widgets)
		{
			if (widget == null || widget.isHidden())
			{
				continue;
			}
			final Rectangle bounds = widget.getBounds();
			if (bounds == null || !bounds.contains(mouseX, mouseY))
			{
				continue;
			}
			final String plain = plain(widget);
			CardStore.Match match = plain == null ? null : store.find(plain);
			if (match == null && plain != null)
			{
				match = readLate(plain);
			}
			if (match == null)
			{
				continue;
			}
			if (rowLine == null)
			{
				rowLine = widget;
				rowMatch = match;
			}
			final HoverCard card = ChatRows.of(plain, metrics::stringWidth, bounds).pick(match.cards, match.offset, mouseX,
				mouseY);
			if (card != null)
			{
				rowLine = widget;
				rowMatch = match;
				hitLine = widget;
				hitMatch = match;
				hitCard = card;
				return true;
			}
		}
		return false;
	}

	/**
	 * The match for a drawn text the store did not know, read as an answer of RuneLite's Chat Commands plugin
	 * ({@link ChatCommandReader}): the card it gives is stored under the text and the store's own match is returned, at
	 * offset 0; null when the text is no such answer.
	 *
	 * <p>Choice: the text is stored whole, as drawn, so {@code stillRow} and {@code stillHit} find the line as they find
	 * any other, and a text that is no answer is read again on the next walk, which is a pattern match and no more.
	 */
	private CardStore.Match readLate(String plain)
	{
		final List<HoverCard> cards = ChatCommandReader.read(plain, tables);
		if (cards.isEmpty())
		{
			return null;
		}
		store.put(plain, cards);
		return store.find(plain);
	}

	/**
	 * A line widget's text the way the card store keys it, {@link ChatText#plain}: without its tags and with a
	 * non-breaking space written as a plain one (the game draws a player's name with the first, the stored line may have
	 * the second); null when the widget has no text.
	 */
	private static String plain(Widget widget)
	{
		final String text = widget.getText();
		return text == null ? null : ChatText.plain(text);
	}

	/**
	 * The always-underline: for each shown line of the scroll area, the dynamic children and then the static ones, that is
	 * in the visible part of the area and says a line the plugin has cards for, a 1 px underline under the words of each
	 * of its quiet cards, in the always-underline colour.
	 *
	 * <p>Choice: a line whose underline row is outside the area is a line scrolled out of the chat (its rectangle sits over
	 * the game world) and gets none.
	 */
	private void underlineQuiet(Graphics2D g, Widget area, Rectangle areaBounds, FontMetrics metrics)
	{
		final Color colour = config.alwaysUnderlineColour();
		underlineQuiet(g, area.getDynamicChildren(), areaBounds, colour, metrics);
		underlineQuiet(g, area.getStaticChildren(), areaBounds, colour, metrics);
	}

	/** One group of the scroll area's children, for the always-underline. */
	private void underlineQuiet(Graphics2D g, Widget[] widgets, Rectangle areaBounds, Color colour, FontMetrics metrics)
	{
		if (widgets == null)
		{
			return;
		}
		for (final Widget widget : widgets)
		{
			if (widget == null || widget.isHidden())
			{
				continue;
			}
			final Rectangle bounds = widget.getBounds();
			if (bounds == null || !areaBounds.intersects(bounds)
				|| bounds.y + bounds.height >= areaBounds.y + areaBounds.height)
			{
				continue;
			}
			final String plain = plain(widget);
			final CardStore.Match match = plain == null ? null : store.find(plain);
			if (match == null)
			{
				continue;
			}
			for (final HoverCard card : match.cards)
			{
				if (!card.marked())
				{
					underline(g, widget, card, match.offset, metrics, colour);
				}
			}
		}
	}

	/**
	 * A 1 px underline, 1 px under the text box of each row the card's words fall on, from where the words start to where
	 * they end on that row: the widget's left edge plus the width of the plain text before them on their row in the
	 * game's chat font, the stored line's place in the text ({@code offset}) added to the card's own. A line of one row
	 * gets one, under its box; a wrapped line ({@link ChatRows}) gets a piece on each row the words touch. It is drawn in
	 * {@code colour}.
	 *
	 * <p>Choice: when the rows come to one but the widget is taller than a row, the game broke the text where this wrap
	 * did not (an {@code <img>} rank icon's width, say), the rows cannot be told, and the line gets the card and no
	 * underline.
	 */
	private void underline(Graphics2D g, Widget line, HoverCard card, int offset, FontMetrics metrics, Color colour)
	{
		final Rectangle bounds = line.getBounds();
		if (bounds == null)
		{
			return;
		}
		final String text = plain(line);
		if (text == null || offset + card.end() > text.length())
		{
			return;
		}
		final ChatRows rows = ChatRows.of(text, metrics::stringWidth, bounds);
		if (rows.rows() == 1 && bounds.height > ONE_ROW)
		{
			return;
		}
		g.setColor(colour);
		for (final int[] piece : rows.spans(offset + card.start(), offset + card.end()))
		{
			g.fillRect(piece[0], piece[2], piece[1] - piece[0], 1);
		}
	}
}

package com.clanhub;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.gameval.ItemID;

/**
 * The reader of the two answers RuneLite's own Chat Commands plugin writes into a line after it has arrived: a kill count
 * ("Brutus kill count: 343") and a personal best ("Chambers of Xeric personal best: 21:14"). A member types {@code !kc
 * brutus} or {@code !pb chambers of xeric}, and the Chat Commands plugin of everyone who runs it replaces the typed line
 * with the answer through {@code MessageNode.setRuneLiteFormatMessage}: {@code <boss> kill count: <n,nnn>}, the boss as
 * RuneLite's {@code longBossName} spells it and the count with its thousands commas, or {@code <boss> personal best:
 * <time>}, the time as {@code secondsToTimeString} writes it ("21:14", "14:32.40", "1:02:15"), the boss and the number in
 * the highlight colour. Both commands are registered asynchronously, so the rewrite lands after every {@code ChatMessage}
 * subscriber has run and no reader of the plugin ever sees the answer as an event. It is read where it can be seen, on
 * the drawn widget, by the overlay when the mouse reaches the line. Pure: the widget's plain text in, the one card out;
 * no RuneLite state.
 *
 * <p>Choice: the whole drawn text is the key. The text has to be the answer from its first word (or its sender and a
 * colon, when the chatbox puts them in the same widget) to its last digit, so a line that goes on after the number, the
 * game's own "Your Zulrah kill count is: 343." and the typed command match nothing. The cards are the ones the
 * {@link BroadcastKindReader} gives the game's own kill count and personal best, and quiet like them: there is no event
 * for the rewrite, so the chat cannot colour the words, and the hover shows them.
 */
final class ChatCommandReader
{
	/** "Brutus kill count: 343" and "Chambers of Xeric kill count: 1,224", after the sender and a colon if any. */
	private static final Pattern KILL_COUNT = Pattern.compile(
		"(?:.*: )?(?<boss>[^:]+?) kill count: (?<count>\\d{1,3}(?:,\\d{3})*|\\d+)");
	/** "Chambers of Xeric personal best: 21:14", "14:32.40" and "1:02:15", after the sender and a colon if any. */
	private static final Pattern PERSONAL_BEST = Pattern.compile(
		"(?:.*: )?(?<boss>[^:]+?) personal best: (?<time>\\d+(?::\\d{2}){0,2}(?:\\.\\d{1,2})?)");

	private ChatCommandReader()
	{
	}

	/**
	 * The one card a widget's plain text ({@link ChatText#plain}) answers, or an empty list. The kill count is tried first,
	 * then the personal best; the card's words are the boss. Its first fact is the count or the time, then, when
	 * {@code tables} knows the boss, its combat level, hitpoints, max hit and quest ({@link BossCards#facts}); the picture
	 * is the wiki's own of the boss's page, the combat icon behind it for a kill count and the clue watch for a personal
	 * best until it comes. A null text, and a boss that is only spaces, give none.
	 *
	 * <p>Choice: a table that has not loaded, or lacks the boss, gives the card as it was before the table: the count or
	 * the time alone, the wiki's picture asked for all the same.
	 */
	static List<HoverCard> read(String plain, CardTables tables)
	{
		if (plain == null)
		{
			return Collections.emptyList();
		}
		Matcher found = KILL_COUNT.matcher(plain);
		if (found.matches() && !found.group("boss").trim().isEmpty())
		{
			final String boss = found.group("boss").trim();
			final int start = startOf(found, boss);
			final CardTables.BossInfo info = tables.boss(boss);
			return card(new InfoCard(boss + " kill count", row("Kills", found.group("count"), info),
				Collections.<String>emptyList(), BossCards.page(info, boss), plain, start, start + boss.length(),
				SkillSprites.spriteOf("Combat"), -1, false, true));
		}
		found = PERSONAL_BEST.matcher(plain);
		if (found.matches() && !found.group("boss").trim().isEmpty())
		{
			final String boss = found.group("boss").trim();
			final int start = startOf(found, boss);
			final CardTables.BossInfo info = tables.boss(boss);
			return card(new InfoCard(boss + " personal best", row("Time", found.group("time"), info),
				Collections.<String>emptyList(), BossCards.page(info, boss), plain, start, start + boss.length(), -1,
				ItemID.TRAIL_WATCH, false, true));
		}
		return Collections.emptyList();
	}

	/** The card's row: the pair of {@code label} and {@code value}, then the boss's facts. */
	private static List<HoverCard.Pair> row(String label, String value, CardTables.BossInfo info)
	{
		final List<HoverCard.Pair> row = new ArrayList<>();
		row.add(new HoverCard.Pair(label, value, ""));
		row.addAll(BossCards.facts(info));
		return row;
	}

	/** Where the trimmed boss starts in the text: the group's start, past the whitespace the trim took off its front. */
	private static int startOf(Matcher found, String trimmed)
	{
		return found.start("boss") + found.group("boss").indexOf(trimmed);
	}

	/** The one card in a list. */
	private static List<HoverCard> card(HoverCard card)
	{
		return Collections.singletonList(card);
	}
}

package com.clanhub;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.ToIntFunction;

/**
 * The rows of one chat line widget, the game's word wrap done again. The game does not split a message that is wider
 * than the chatbox into widgets: it stays ONE widget whose text has no break in it and whose height is the rows' (28 px
 * for two, 14 for each), and the game draws the words row by row, breaking at the spaces. Pure: the plain text, a width
 * function and the widget's bounds in, rows and places out; no RuneLite state. The wrap is greedy: a row takes words
 * while the width of the row's text so far, from its first character to the end of the word, is at most the bounds'
 * width; a word wider than the row stands alone on its own row, uncut; an empty text is one empty row. With the rows
 * known, the plugin can say which row a word is on and where on that row it stands, which is what the card's hit and the
 * underline need on a line that wrapped; a line of one row comes out as the plain, one-row reading of old.
 *
 * <p>Choice: the break space belongs to the row before, so an index in it is on the row it ends and the next row starts
 * at the next word's first character; the underline of words that run across a break then has a piece on each row and
 * none under the space itself.
 */
final class ChatRows
{
	/** The plain text the rows are made of. */
	private final String text;
	/** The width of a text in the chat font, in pixels. */
	private final ToIntFunction<String> width;
	/** The widget's bounds: the left edge, the top, the width the rows wrap to and the whole height. */
	private final Rectangle bounds;
	/** Where each row starts in the text. */
	private final int[] starts;
	/** The index after each row's last word, the break space left out. */
	private final int[] ends;
	/** The height of one row: the bounds' height over the rows, in whole pixels. */
	private final int rowHeight;

	private ChatRows(String text, ToIntFunction<String> width, Rectangle bounds, List<int[]> rows)
	{
		this.text = text;
		this.width = width;
		this.bounds = bounds;
		this.starts = new int[rows.size()];
		this.ends = new int[rows.size()];
		for (int row = 0; row < rows.size(); row++)
		{
			starts[row] = rows.get(row)[0];
			ends[row] = rows.get(row)[1];
		}
		this.rowHeight = Math.max(1, bounds.height / rows.size());
	}

	/**
	 * The rows the text breaks into inside {@code bounds}, {@code width} giving the width in pixels of a text in the
	 * chat font.
	 */
	static ChatRows of(String text, ToIntFunction<String> width, Rectangle bounds)
	{
		final List<int[]> rows = new ArrayList<>();
		final int length = text.length();
		int rowStart = 0;
		int rowEnd = 0;
		boolean any = false;
		int at = 0;
		while (at < length)
		{
			if (text.charAt(at) == ' ')
			{
				at++;
				continue;
			}
			final int wordStart = at;
			while (at < length && text.charAt(at) != ' ')
			{
				at++;
			}
			if (!any)
			{
				rowEnd = at;
				any = true;
			}
			else if (width.applyAsInt(text.substring(rowStart, at)) <= bounds.width)
			{
				rowEnd = at;
			}
			else
			{
				rows.add(new int[] {rowStart, rowEnd});
				rowStart = wordStart;
				rowEnd = at;
			}
		}
		rows.add(new int[] {rowStart, rowEnd});
		return new ChatRows(text, width, bounds, Collections.unmodifiableList(rows));
	}

	/** How many rows the text takes, at least one. */
	int rows()
	{
		return starts.length;
	}

	/** Where the row starts in the text: the first character of its first word. */
	int start(int row)
	{
		return starts[row];
	}

	/** The index after the row's last word; the break space that follows it is not in the row. */
	int end(int row)
	{
		return ends[row];
	}

	/**
	 * The row an index in the text is on: the row whose start to end holds it, a break space being on the row before it,
	 * and an index past the text on the last row.
	 */
	int rowOf(int index)
	{
		for (int row = rows() - 1; row > 0; row--)
		{
			if (index >= start(row))
			{
				return row;
			}
		}
		return 0;
	}

	/** The x on screen of the place before the character at {@code index}, on the row that index is on. */
	int x(int index)
	{
		final int row = rowOf(index);
		final int at = Math.max(start(row), Math.min(index, text.length()));
		return bounds.x + width.applyAsInt(text.substring(start(row), at));
	}

	/** The row the height {@code y} falls on, the first row for a y above the widget and the last for one below it. */
	int rowAt(int y)
	{
		return Math.max(0, Math.min(rows() - 1, (y - bounds.y) / rowHeight));
	}

	/** The y of the underline of a row: 1 px under the row's text box, which for a line of one row is its bottom. */
	int underlineY(int row)
	{
		return bounds.y + (row + 1) * rowHeight;
	}

	/**
	 * The pieces the words {@code [from, to)} take on the rows they touch, as {@code {left x, right x, underline y}}, the
	 * left end up to, not including, the right end, the way the underline fills them; a row where the words have nothing
	 * left out, so a break space alone has none.
	 */
	List<int[]> spans(int from, int to)
	{
		final List<int[]> pieces = new ArrayList<>();
		for (int row = 0; row < rows(); row++)
		{
			final int first = Math.max(from, start(row));
			final int last = Math.min(to, end(row));
			if (first < last)
			{
				pieces.add(new int[] {x(first), x(last), underlineY(row)});
			}
		}
		return pieces;
	}

	/**
	 * The card of the line whose words the mouse is on: for each card, its words {@code [offset + start(), offset +
	 * end())} are looked at on the row the mouse's y is on, and the first card with a part there that is not empty and
	 * whose x range holds {@code mouseX} is the one; null when the mouse is on none.
	 *
	 * <p>Choice: the card belongs to its words on their own row, so the mouse on the other row of a wrapped line, under
	 * the words or over them, is on no card.
	 */
	HoverCard pick(List<HoverCard> cards, int offset, int mouseX, int mouseY)
	{
		final int row = rowAt(mouseY);
		for (final HoverCard card : cards)
		{
			final int first = Math.max(offset + card.start(), start(row));
			final int last = Math.min(offset + card.end(), end(row));
			if (first < last && mouseX >= x(first) && mouseX < x(last))
			{
				return card;
			}
		}
		return null;
	}
}

package com.clanhub;

import java.awt.Color;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

/**
 * The chat text as the plugin reads it and as it changes it. Pure: strings in, strings out, no RuneLite state.
 * {@link #plain} is the one text every reader's offsets index and the card store keys on: the message with the game's
 * string variables filled in ({@link #expand}), without its tags, without the {@code CA_ID:<n>|} a combat achievement
 * line carries, which the client does not draw, with every non-breaking space written as a plain one, and trimmed of the whitespace around the text (before the prefix, after it
 * and at the end). {@link #colourSpans} is the only change the plugin makes to a line:
 * colour tags put around words, nothing removed or rewritten; {@link #spansOf} gives it the words to colour, those of
 * the cards that are marked.
 */
final class ChatText
{
	/**
	 * What comes before a line's first drawn character: any whitespace, an optional "CA_ID:279|" (the id a combat
	 * achievement line starts with) and any whitespace after it.
	 */
	private static final Pattern LEAD = Pattern.compile("^\\s*(?:CA_ID:\\d+\\|)?\\s*");
	/** A tag, the way {@link Text#removeTags} sees one: a "<", anything but a ">", and the ">". */
	private static final Pattern TAG = Pattern.compile("<[^>]*>");
	/**
	 * One of the game's string variables, as a whole tag: {@code <str_NAME=VALUE>} defines one (group 1 the name, group 3
	 * the value, up to the first "&gt;") and {@code <str_NAME>} refers to one (group 2 is null).
	 */
	private static final Pattern VARIABLE = Pattern.compile("<str_([A-Za-z0-9_]+)(=([^>]*))?>");
	/**
	 * The close of a span when no colour stands open before it: "<col" + {@link ChatColorType#NORMAL} + ">", the marker
	 * RuneLite's chat manager replaces with the line's own colour (the line has to be stored with {@code
	 * MessageNode.setRuneLiteFormatMessage} for that), where {@code </col>} would read as the widget's base colour.
	 */
	private static final String NORMAL = "<col" + ChatColorType.NORMAL + ">";

	private ChatText()
	{
	}

	/**
	 * The message with the game's string variables filled in ({@link #expand}), without its tags, without a leading
	 * {@code CA_ID:<digits>|} and the whitespace around it, with every non-breaking space (U+00A0) written as a plain
	 * space, and without trailing whitespace; an empty text for null.
	 *
	 * <p>Choice: the prefix is taken off only when it stands first once the tags are gone (whitespace before it
	 * allowed), which is where the game puts it. The text is trimmed because the game's task line can carry a space after
	 * the prefix (or whitespace at an end) that the drawn widget text does not, and the card store finds a line by its
	 * text: the stored line and the drawn line have to be the same characters. The game writes a player's name with a non-breaking space (U+00A0, as in a name like "self ctrl") in one place
	 * and a plain space in another, and the card store finds a line by its text, so both are made the one plain space;
	 * each is one character, so the length and every offset stay true.
	 */
	static String plain(String message)
	{
		if (message == null)
		{
			return "";
		}
		final String text = Text.removeTags(expand(message)).replace('\u00a0', ' ');
		final Matcher lead = LEAD.matcher(text);
		final int from = lead.find() ? lead.end() : 0;
		int to = text.length();
		while (to > from && Character.isWhitespace(text.charAt(to - 1)))
		{
			to--;
		}
		return text.substring(from, to);
	}

	/**
	 * The raw message with the game's string variables resolved. Some broadcasts carry a name as a variable: a definition
	 * tag {@code <str_NAME=VALUE>} at the front of the line and a reference tag {@code <str_NAME>} where the name is
	 * drawn, as in {@code <str_quest_name_0=King's Ransom>Klar has completed a quest: <str_quest_name_0>}, which the
	 * client reads as "Klar has completed a quest: King's Ransom". Here each definition is removed and remembered (a
	 * later one of the same NAME replaces the earlier) and each reference becomes the value remembered for its NAME, or
	 * nothing when it was never defined. NAME is letters, digits and underscores; VALUE is everything up to the first
	 * "&gt;", so it may hold spaces, an apostrophe or an "=". Every other tag and every other character stays as it is,
	 * and a null message gives an empty text.
	 */
	static String expand(String raw)
	{
		if (raw == null)
		{
			return "";
		}
		final Map<String, String> values = new HashMap<>();
		final StringBuilder out = new StringBuilder(raw.length());
		final Matcher tags = TAG.matcher(raw);
		int from = 0;
		while (tags.find())
		{
			out.append(raw, from, tags.start());
			from = tags.end();
			final Matcher variable = VARIABLE.matcher(tags.group());
			if (!variable.matches())
			{
				out.append(tags.group());
			}
			else if (variable.group(2) != null)
			{
				values.put(variable.group(1), variable.group(3));
			}
			else
			{
				out.append(values.getOrDefault(variable.group(1), ""));
			}
		}
		return out.append(raw, from, raw.length()).toString();
	}

	/**
	 * The {@code [start, end)} spans of the cards whose {@link HoverCard#marked} is true, in the cards' order: the words
	 * the chat colours. A quiet card has no span here; no marked card gives an empty list.
	 */
	static List<int[]> spansOf(List<HoverCard> cards)
	{
		final List<int[]> spans = new ArrayList<>();
		for (final HoverCard card : cards)
		{
			if (card.marked())
			{
				spans.add(new int[] {card.start(), card.end()});
			}
		}
		return spans;
	}

	/**
	 * The raw message with {@code <col=rrggbb>} put before each span and a close tag after it, the spans being
	 * {@code [start, end)} offsets into {@code plain(rawMessage)}. The walk skips every tag and the lead
	 * of {@link #plain} (whitespace, a {@code CA_ID:<digits>|} and the whitespace after it) without counting them, and puts
	 * the open tag just before the span's first character and the close tag just after its last, so a tag the line already
	 * has stays where it was. Spans are applied from the last to
	 * the first, so the offsets of the earlier ones stay true. With no spans, the raw message comes back as it was.
	 *
	 * <p>The offsets index the expanded text ({@link #expand}), and the tags go into the raw message as the game wrote
	 * it, its string variables unexpanded: a span over a variable's words wraps the reference tag whole, opening just
	 * before {@code <str_NAME>} and closing just after its {@code >}, so the game fills the name in between the colours.
	 *
	 * <p>Choice: a span that is empty, runs outside the text, or starts inside the span before it is left out, so the
	 * tags never cross; the spans are taken in the order of their starts, whatever order they come in. A span is closed
	 * with the colour that was open before it, not with {@code </col>}: in the game a {@code </col>} sets the text after
	 * it to the line widget's base colour, which for a line a player typed is black, and a line the game sent in its own
	 * colour would lose it after the first span. That colour is the last {@code <col=...>} tag before the span when it
	 * stands after the last {@code </col>}, else RuneLite's {@code <colNORMAL>} marker, the way the Chat Notifications
	 * plugin closes a highlighted word; the chat manager fills the marker with the line's own colour when it builds the
	 * line (see {@link #NORMAL}).
	 */
	static String colourSpans(String rawMessage, List<int[]> spans, Color colour)
	{
		if (rawMessage == null || spans == null || spans.isEmpty())
		{
			return rawMessage;
		}
		final String tagless = Text.removeTags(expand(rawMessage));
		final int[][] rawAt = rawOffsets(rawMessage, tagless.length());
		final int[] opens = rawAt[0];
		final int[] lasts = rawAt[1];
		final Matcher lead = LEAD.matcher(tagless.replace(' ', ' '));
		final int skipped = lead.find() ? lead.end() : 0;
		final int plainLength = tagless.length() - skipped;

		final List<int[]> ordered = new ArrayList<>(spans);
		Collections.sort(ordered, (a, b) -> Integer.compare(a[0], b[0]));
		final List<int[]> kept = new ArrayList<>();
		int lastEnd = 0;
		int lastRaw = 0;
		for (final int[] span : ordered)
		{
			// A span that would open inside the tag the span before it closed after (two spans over one variable) is left out too.
			if (span[0] >= lastEnd && span[1] > span[0] && span[1] <= plainLength && opens[skipped + span[0]] >= lastRaw)
			{
				kept.add(span);
				lastEnd = span[1];
				lastRaw = lasts[skipped + span[1] - 1] + 1;
			}
		}

		final String open = "<col=" + ColorUtil.colorToHexCode(colour).toLowerCase(Locale.ROOT) + ">";
		final StringBuilder out = new StringBuilder(rawMessage);
		for (int i = kept.size() - 1; i >= 0; i--)
		{
			final int[] span = kept.get(i);
			final int first = opens[skipped + span[0]];
			out.insert(lasts[skipped + span[1] - 1] + 1, colourBefore(rawMessage, first));
			out.insert(first, open);
		}
		return out.toString();
	}

	/**
	 * What closes a span that starts at raw index {@code at}: the last {@code <col=...>} tag before it, whole, when that
	 * tag stands after the last {@code </col>} (the colour still open there), else the {@link #NORMAL} marker, never
	 * {@code </col>}.
	 */
	private static String colourBefore(String raw, int at)
	{
		final String before = raw.substring(0, at);
		final int opened = before.lastIndexOf("<col=");
		if (opened > before.lastIndexOf("</col>"))
		{
			final int closed = before.indexOf('>', opened);
			if (closed >= 0)
			{
				return before.substring(opened, closed + 1);
			}
		}
		return NORMAL;
	}

	/**
	 * Where each character of the expanded, tag-free text stands in the raw message, as two arrays of
	 * {@code taglessLength} entries: entry {@code k} of the first is the raw index a span that starts at the {@code k}th
	 * character opens at, entry {@code k} of the second the raw index of the last raw character of the {@code k}th
	 * (a span that ends there closes just after it). A character that is not inside a tag stands at its own index in both.
	 * A definition tag adds no character; a reference tag adds the characters of its value ({@link #expand}), all of
	 * them opening at the tag's first character and ending at its {@code >}, so a span that starts or ends inside the
	 * value takes the tag whole. Any other tag adds nothing.
	 */
	private static int[][] rawOffsets(String raw, int taglessLength)
	{
		final int[] opens = new int[taglessLength];
		final int[] lasts = new int[taglessLength];
		final Map<String, String> values = new HashMap<>();
		final Matcher tags = TAG.matcher(raw);
		int next = 0;
		int i = 0;
		while (tags.find())
		{
			for (; i < tags.start() && next < taglessLength; i++)
			{
				opens[next] = i;
				lasts[next++] = i;
			}
			i = tags.end();
			final Matcher variable = VARIABLE.matcher(tags.group());
			if (!variable.matches())
			{
				continue;
			}
			if (variable.group(2) != null)
			{
				values.put(variable.group(1), variable.group(3));
				continue;
			}
			final int length = values.getOrDefault(variable.group(1), "").length();
			for (int k = 0; k < length && next < taglessLength; k++)
			{
				opens[next] = tags.start();
				lasts[next++] = tags.end() - 1;
			}
		}
		for (; i < raw.length() && next < taglessLength; i++)
		{
			opens[next] = i;
			lasts[next++] = i;
		}
		return new int[][] {opens, lasts};
	}
}

package com.clanhub;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

/**
 * The plugin's settings. Flat on purpose: every item is declared here and this interface extends {@link Config}
 * alone, because RuneLite stores defaults only for the methods declared on the interface it is given. The group and
 * the keys are frozen at first release; renaming one silently discards every player's setting.
 */
@ConfigGroup(ClanHubConfig.GROUP)
public interface ClanHubConfig extends Config
{
	String GROUP = "chat-hover-info";

	/** When a card opens: as soon as the mouse is on its words, only while a key is held, or when the words are clicked. */
	enum CardTrigger
	{
		HOVER("On hover"),
		HOLD_KEY("While holding a key"),
		CLICK("On click");

		private final String text;

		CardTrigger(String text)
		{
			this.text = text;
		}

		/** The words the settings show for the choice. */
		@Override
		public String toString()
		{
			return text;
		}
	}

	/** Where a card opens: centred above the cursor as the split card, or as wide as the chatbox and pinned above it. */
	enum CardPlace
	{
		CURSOR("Above the cursor"),
		CHAT("Above the chat");

		private final String text;

		CardPlace(String text)
		{
			this.text = text;
		}

		/** The words the settings show for the choice. */
		@Override
		public String toString()
		{
			return text;
		}
	}

	/**
	 * How wide the card at the cursor may grow, and how many lines its paragraph may take: {@link #cap} is its greatest
	 * width at the 16 px text size (scaled with the text size), {@link #lines} the most paragraph lines. Short cards size
	 * to their content in every choice.
	 */
	enum CardWidth
	{
		WIDE("Wide", 480, 3),
		MEDIUM("Medium", 409, 5),
		NARROW("Narrow", 391, 5);

		private final String text;
		/** The card's greatest width at the 16 px text size, in px. */
		final int cap;
		/** The most lines the paragraph takes. */
		final int lines;

		CardWidth(String text, int cap, int lines)
		{
			this.text = text;
			this.cap = cap;
			this.lines = lines;
		}

		/** The words the settings show for the choice. */
		@Override
		public String toString()
		{
			return text;
		}
	}

	/** Whether the item card shows when the mouse is on a recognised chat line. */
	@ConfigItem(
		keyName = "showCards",
		name = "Show hover cards",
		description = "Show a card at the mouse when you hover an item in a clan or friends chat line.",
		position = 1
	)
	default boolean showCards()
	{
		return true;
	}

	/** The size of the card's text, in pixels. */
	@ConfigItem(
		keyName = "cardFontSize",
		name = "Card text size",
		description = "The size of the card's text, in pixels.",
		position = 2
	)
	@Range(min = 8, max = 24)
	default int cardFontSize()
	{
		return 16;
	}

	/** Whether the words a card is about are coloured in the chat line. */
	@ConfigItem(
		keyName = "colourHoverables",
		name = "Colour hoverable words",
		description = "Colour the item, quest, achievement and pet names the cards are about in the chat.",
		position = 3
	)
	default boolean colourHoverables()
	{
		return true;
	}

	/** The colour of the words a card is about, and of the underline under the ones hovered. */
	@ConfigItem(
		keyName = "hoverColour",
		name = "Hover colour",
		description = "The colour of the words a card is about, and of the underline under the ones you hover.",
		position = 4
	)
	default Color hoverColour()
	{
		return new Color(59, 130, 246);
	}

	/** When a card opens. */
	@ConfigItem(
		keyName = "cardTrigger",
		name = "Show a card",
		description = "When a card opens: as soon as you hover, only while you hold the key below, or when you click the words.",
		position = 5
	)
	default CardTrigger cardTrigger()
	{
		return CardTrigger.HOVER;
	}

	/** The key held when the card opens only while a key is held. */
	@ConfigItem(
		keyName = "cardKey",
		name = "Card key",
		description = "The key to hold when 'Show a card' is 'While holding a key'.",
		position = 6
	)
	default Keybind cardKey()
	{
		return Keybind.ALT;
	}

	/** How long the mouse rests on the words before the card opens, in milliseconds. */
	@ConfigItem(
		keyName = "cardDelayMs",
		name = "Card delay",
		description = "How long the mouse rests on the words before the card opens.",
		position = 7
	)
	@Range(min = 0, max = 1000)
	@Units(Units.MILLISECONDS)
	default int cardDelayMs()
	{
		return 0;
	}

	/** Whether a card shows the first paragraph of its wiki page, which asks the wiki for it. */
	@ConfigItem(
		keyName = "wikiDescriptions",
		name = "Wiki descriptions",
		description = "Show the first paragraph of the wiki page on each card. Sends only the thing's name to oldschool.runescape.wiki.",
		position = 8
	)
	default boolean wikiDescriptions()
	{
		return true;
	}

	/** Whether the card of a boss, monster, raid or chest shows the wiki's own picture of it, which asks the wiki for it. */
	@ConfigItem(
		keyName = "wikiPictures",
		name = "Wiki pictures",
		description = "Show the wiki's own picture of a boss, monster, raid or chest on its card. Sends only the thing's name to oldschool.runescape.wiki, then fetches the picture the wiki names.",
		position = 9
	)
	default boolean wikiPictures()
	{
		return true;
	}

	/** Whether a drop line that says where the drop came from gives the boss, monster, raid or chest a card of its own. */
	@ConfigItem(
		keyName = "bossCards",
		name = "Boss cards",
		description = "On a drop line that says where the drop came from, give the boss, monster, raid or chest its own card, with the wiki's first paragraph.",
		position = 10
	)
	default boolean bossCards()
	{
		return true;
	}

	/** Where a card opens. */
	@ConfigItem(
		keyName = "cardPlace",
		name = "Card place",
		description = "Where a card opens: centred above the cursor, or as wide as the chatbox and pinned above it.",
		position = 11
	)
	default CardPlace cardPlace()
	{
		return CardPlace.CURSOR;
	}

	/** How wide the card at the cursor may grow. */
	@ConfigItem(
		keyName = "cardWidth",
		name = "Card width",
		description = "How wide the card at the cursor may grow: wide, or two narrower widths that give the paragraph up to five lines.",
		position = 12
	)
	default CardWidth cardWidth()
	{
		return CardWidth.MEDIUM;
	}

	/** Whether the level and XP phrases that have a card carry a line under them at all times. */
	@ConfigItem(
		keyName = "alwaysUnderlineLevels",
		name = "Underline level-ups",
		description = "Keep a line under the level and XP phrases that have a card, whether or not the mouse is on them.",
		position = 13
	)
	default boolean alwaysUnderlineLevels()
	{
		return false;
	}

	/** The colour of the line kept under the quiet phrases. */
	@ConfigItem(
		keyName = "alwaysUnderlineColour",
		name = "Underline colour",
		description = "The colour of that line.",
		position = 14
	)
	default Color alwaysUnderlineColour()
	{
		return new Color(150, 150, 150);
	}
}

