package com.clanhub;

import java.util.Optional;
import net.runelite.api.ChatMessageType;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** {@link BroadcastLine}: the four sentence shapes, the tags stripped first, and the lines and channels it leaves alone. */
public class BroadcastLineTest
{
	private static BroadcastLine.ItemMention read(ChatMessageType type, String message)
	{
		final Optional<BroadcastLine.ItemMention> found = BroadcastLine.parse(type, message);
		assertTrue("a mention in: " + message, found.isPresent());
		return found.get();
	}

	/** The name's place in the plain text, as the offsets say. */
	private static String named(BroadcastLine.ItemMention mention)
	{
		return mention.text.substring(mention.start, mention.end);
	}

	@Test
	public void aDropLineGivesTheItemAndQuantityOne()
	{
		final BroadcastLine.ItemMention mention = read(ChatMessageType.CLAN_MESSAGE,
			"Klar received a drop: Dragon claws (121,453,000 coins).");

		assertEquals("Dragon claws", mention.name);
		assertEquals(1, mention.quantity);
		assertEquals("Dragon claws", named(mention));
		assertEquals("Klar received a drop: Dragon claws (121,453,000 coins).", mention.text);
	}

	@Test
	public void aStackedDropGivesTheQuantity()
	{
		final BroadcastLine.ItemMention mention = read(ChatMessageType.FRIENDSCHATNOTIFICATION,
			"Iron Pete received a drop: 10 x Black knife (460 coins).");

		assertEquals("Black knife", mention.name);
		assertEquals(10, mention.quantity);
		assertEquals("the offsets skip the quantity", "Black knife", named(mention));
	}

	@Test
	public void clueAndCollectionLogLinesAreRead()
	{
		final BroadcastLine.ItemMention clue = read(ChatMessageType.CLAN_GUEST_MESSAGE,
			"Klar received a clue item: Ranger boots (25,296,193 coins).");
		assertEquals("Ranger boots", clue.name);
		assertEquals(1, clue.quantity);
		assertEquals("Ranger boots", named(clue));

		final BroadcastLine.ItemMention log = read(ChatMessageType.CLAN_GIM_MESSAGE,
			"Mossy Rock received a new collection log item: Abyssal whip (1/484).");
		assertEquals("Abyssal whip", log.name);
		assertEquals(1, log.quantity);
		assertEquals("Abyssal whip", named(log));
	}

	@Test
	public void tagsAndIconsAreStrippedFirst()
	{
		final BroadcastLine.ItemMention mention = read(ChatMessageType.CLAN_MESSAGE,
			"<col=0000a0><img=22>Klar received a drop: Dragon claws (1 coins).</col>");

		assertEquals("Dragon claws", mention.name);
		assertTrue("the plain text starts with the player: " + mention.text, mention.text.startsWith("Klar received"));
		assertEquals("Dragon claws", named(mention));
	}

	@Test
	public void aDropWithTheSourceTailStillGivesTheItem()
	{
		final BroadcastLine.ItemMention mention = read(ChatMessageType.CLAN_MESSAGE,
			"Blade Fiery received a drop: Hallowfell (2,320,896 coins) from Mad Angel.");

		assertEquals("Hallowfell", mention.name);
		assertEquals(1, mention.quantity);
		assertEquals("Hallowfell", named(mention));
	}

	@Test
	public void otherLinesAndChannelsGiveNothing()
	{
		assertFalse(BroadcastLine.parse(ChatMessageType.CLAN_MESSAGE, "Klar: gz!!!").isPresent());
		final String drop = "Klar received a drop: Dragon claws (121,453,000 coins).";
		assertFalse(BroadcastLine.parse(ChatMessageType.PUBLICCHAT, drop).isPresent());
		assertFalse(BroadcastLine.parse(ChatMessageType.CLAN_CHAT, drop).isPresent());
		assertFalse(BroadcastLine.parse(ChatMessageType.GAMEMESSAGE, drop).isPresent());
	}
}

package com.clanhub;

import com.clanhub.ClanHubConfig.CardTrigger;
import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** {@link CardGate}: a card shows by the show mode, whether the key is held, and how long the mouse has been on the words. */
public class CardGateTest
{
	private static final long MS = 1_000_000L;

	// Re-aimed by the lead, 2026-10-08 (lot 7): the gate also takes whether the words were clicked.
	@Test
	public void showsByTriggerKeyAndDelay()
	{
		final long since = 5_000_000_000L;

		assertTrue("on hover with no delay: at once", CardGate.shows(CardTrigger.HOVER, false, false, since, since, 0));

		assertFalse("on hover, delay 300, 100 ms after the hit",
			CardGate.shows(CardTrigger.HOVER, false, false, since, since + 100 * MS, 300));
		assertTrue("on hover, delay 300, 400 ms after the hit",
			CardGate.shows(CardTrigger.HOVER, false, false, since, since + 400 * MS, 300));

		assertFalse("holding a key, key not held, a second after",
			CardGate.shows(CardTrigger.HOLD_KEY, false, false, since, since + 1000 * MS, 0));
		assertTrue("holding a key, key held, no delay",
			CardGate.shows(CardTrigger.HOLD_KEY, true, false, since, since, 0));
	}

	@Test
	public void onClickShowsOnlyAfterAClick()
	{
		final long since = 5_000_000_000L;

		assertFalse("on click, not clicked, a second after the hit",
			CardGate.shows(CardTrigger.CLICK, false, false, since, since + 1000 * MS, 0));
		assertTrue("on click, clicked, delay 300, at the hit's instant: no wait",
			CardGate.shows(CardTrigger.CLICK, false, true, since, since, 300));
		assertTrue("holding a key, key held, clicked means nothing",
			CardGate.shows(CardTrigger.HOLD_KEY, true, false, since, since, 0));
		assertFalse("on hover, clicked means nothing: delay 300, 100 ms after the hit",
			CardGate.shows(CardTrigger.HOVER, false, true, since, since + 100 * MS, 300));
	}
}

package com.clanhub;

import com.clanhub.ClanHubConfig.CardTrigger;
import java.awt.event.KeyEvent;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JPanel;
import net.runelite.client.config.Keybind;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * {@link CardKeyListener}: the card key is taken from the game only in the key mode with the cards on and the mouse on a
 * card; every other key and every other case types as usual.
 */
public class CardKeyListenerTest
{
	private final JPanel source = new JPanel();
	private final List<Boolean> held = new ArrayList<>();
	private Keybind key = new Keybind(KeyEvent.VK_G, 0);
	private CardTrigger trigger = CardTrigger.HOLD_KEY;
	private boolean cardsOn = true;
	private HoverCard hovered;

	private CardKeyListener listener()
	{
		return new CardKeyListener(() -> key, () -> trigger, () -> cardsOn, () -> hovered, held::add);
	}

	/**
	 * A key event as the game's window sends it. The constructor leaves the extended key code at 0, and only the AWT
	 * toolkit sets it (to the key code for a key like G), which RuneLite's {@code Keybind.matches} reads; so the double
	 * answers it as the toolkit does.
	 */
	private KeyEvent event(int id, int keyCode, char keyChar, int modifiers)
	{
		return new KeyEvent(source, id, 0L, modifiers, keyCode, keyChar)
		{
			@Override
			public int getExtendedKeyCode()
			{
				return getKeyCode();
			}
		};
	}

	private KeyEvent press(int keyCode, char keyChar)
	{
		return event(KeyEvent.KEY_PRESSED, keyCode, keyChar, 0);
	}

	private KeyEvent typed(char keyChar)
	{
		return event(KeyEvent.KEY_TYPED, KeyEvent.VK_UNDEFINED, keyChar, 0);
	}

	private KeyEvent release(int keyCode, char keyChar)
	{
		return event(KeyEvent.KEY_RELEASED, keyCode, keyChar, 0);
	}

	// L8Z-1
	@Test
	public void aLetterKeyTypesWhenNoCardIsUnderTheMouse()
	{
		final CardKeyListener listener = listener();
		hovered = null;

		final KeyEvent press = press(KeyEvent.VK_G, 'g');
		listener.keyPressed(press);
		assertFalse("the press types as usual", press.isConsumed());
		assertEquals("the overlay is told the key is down", List.of(true), held);

		final KeyEvent typed = typed('g');
		listener.keyTyped(typed);
		assertFalse("the typed character reaches the chat", typed.isConsumed());

		final KeyEvent release = release(KeyEvent.VK_G, 'g');
		listener.keyReleased(release);
		assertFalse("the release is passed on", release.isConsumed());
		assertEquals("the overlay is told the key is up", List.of(true, false), held);
	}

	// L8Z-2
	@Test
	public void theKeyIsTakenOnlyOverACardInTheKeyMode()
	{
		hovered = Mockito.mock(HoverCard.class);
		final CardKeyListener listener = listener();

		final KeyEvent press = press(KeyEvent.VK_G, 'g');
		listener.keyPressed(press);
		assertTrue("the press is taken over a card in the key mode", press.isConsumed());
		assertEquals(List.of(true), held);

		final KeyEvent typed = typed('g');
		listener.keyTyped(typed);
		assertTrue("the character of a taken key never reaches the chat", typed.isConsumed());

		final KeyEvent release = release(KeyEvent.VK_G, 'g');
		listener.keyReleased(release);
		assertTrue("the release of a taken key is taken", release.isConsumed());
		assertEquals(List.of(true, false), held);

		trigger = CardTrigger.HOVER;
		final KeyEvent onHover = press(KeyEvent.VK_G, 'g');
		listener().keyPressed(onHover);
		assertFalse("on hover the key types", onHover.isConsumed());

		trigger = CardTrigger.CLICK;
		final KeyEvent onClick = press(KeyEvent.VK_G, 'g');
		listener().keyPressed(onClick);
		assertFalse("on click the key types", onClick.isConsumed());

		trigger = CardTrigger.HOLD_KEY;
		cardsOn = false;
		final KeyEvent cardsOff = press(KeyEvent.VK_G, 'g');
		listener().keyPressed(cardsOff);
		assertFalse("with the cards off the key types", cardsOff.isConsumed());
	}

	// L8Z-3
	@Test
	public void anotherKeyPassesUntouched()
	{
		hovered = Mockito.mock(HoverCard.class);
		final CardKeyListener listener = listener();

		final KeyEvent press = press(KeyEvent.VK_H, 'h');
		listener.keyPressed(press);
		final KeyEvent typed = typed('h');
		listener.keyTyped(typed);
		final KeyEvent release = release(KeyEvent.VK_H, 'h');
		listener.keyReleased(release);

		assertFalse(press.isConsumed());
		assertFalse(typed.isConsumed());
		assertFalse(release.isConsumed());
		assertTrue("the overlay is never told", held.isEmpty());
	}

	// L8Z-4
	@Test
	public void losingFocusLetsGo()
	{
		hovered = Mockito.mock(HoverCard.class);
		final CardKeyListener listener = listener();

		final KeyEvent press = press(KeyEvent.VK_G, 'g');
		listener.keyPressed(press);
		assertTrue("the press was taken", press.isConsumed());
		assertEquals(List.of(true), held);

		listener.focusLost();
		assertEquals("the overlay is told the key is up", List.of(true, false), held);

		final KeyEvent typed = typed('g');
		listener.keyTyped(typed);
		assertFalse("a character after the focus was lost types", typed.isConsumed());

		final KeyEvent release = release(KeyEvent.VK_G, 'g');
		listener.keyReleased(release);
		assertFalse("a release after the focus was lost is passed on", release.isConsumed());
		assertEquals("the overlay is not told again", List.of(true, false), held);
	}

	// L8Z-5
	@Test
	public void theDefaultAltStillHolds()
	{
		key = Keybind.ALT;
		hovered = null;
		final CardKeyListener listener = listener();

		final KeyEvent press = event(KeyEvent.KEY_PRESSED, KeyEvent.VK_ALT, KeyEvent.CHAR_UNDEFINED,
			KeyEvent.ALT_DOWN_MASK);
		listener.keyPressed(press);
		assertFalse("Alt is not taken with no card under the mouse", press.isConsumed());
		assertEquals(List.of(true), held);

		final KeyEvent release = event(KeyEvent.KEY_RELEASED, KeyEvent.VK_ALT, KeyEvent.CHAR_UNDEFINED, 0);
		listener.keyReleased(release);
		assertFalse(release.isConsumed());
		assertEquals(List.of(true, false), held);
	}
}

package com.clanhub;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.client.ui.FontManager;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * {@link CardPainter}: where the two looks open, the split and the wide card's widths, sprite, rule and growth, and the
 * description wrapped by pixel width under the header.
 */
public class CardPainterTest
{
	private static final Dimension CANVAS = new Dimension(765, 503);
	private static final Color ACCENT = new Color(59, 130, 246);
	// Re-aimed by the lead, 2026-10-08 (lot 8i): the painter wraps the description itself.
	// Re-aimed by the lead, 2026-10-08 (lot 8Q): the cap and the line count are the caller's now.
	private static final String NONE = "";
	private static final String THREE_LINES = "The dragon claws are a rare drop from the abyssal demon.";
	private static final String PARAGRAPH = words(400);

	/** {@code count} words, "word0 word1 word2 ...". */
	private static String words(int count)
	{
		final StringBuilder text = new StringBuilder();
		for (int word = 0; word < count; word++)
		{
			text.append(word == 0 ? "" : " ").append("word").append(word);
		}
		return text.toString();
	}

	/** The body font's metrics at 16 px. */
	private static FontMetrics bodyMetrics()
	{
		final BufferedImage image = new BufferedImage(1, 1, BufferedImage.TYPE_INT_RGB);
		final Graphics2D g = image.createGraphics();
		final FontMetrics metrics = g.getFontMetrics(FontManager.getRunescapeFont().deriveFont(16f));
		g.dispose();
		return metrics;
	}

	/** The quest card of the problem case: a long title, four facts, no notes, no drops. */
	private static InfoCard dragonSlayerTwo()
	{
		final List<HoverCard.Pair> row = Arrays.asList(new HoverCard.Pair("Difficulty", "Grandmaster", ""),
			new HoverCard.Pair("Length", "Very Long", ""), new HoverCard.Pair("Points", "5", ""),
			new HoverCard.Pair("Series", "Dragon Slayer", ""));
		return new InfoCard("Dragon Slayer II: The Legacy of Elvarg", row, Collections.<String>emptyList(),
			"Dragon_Slayer_II", "Klar has completed a quest: Dragon Slayer II: The Legacy of Elvarg.", 33, 70, -1);
	}

	private static ItemCard claws()
	{
		return new ItemCard(13652, "Dragon claws", 1, 121_453_000L, 123_000,
			"Klar received a drop: Dragon claws (121,453,000 coins).", 24, 36);
	}

	/** The claws card with three drop sources, which makes it three drop rows. */
	private static ItemCard clawsWithDrops()
	{
		return new ItemCard(13652, "Dragon claws", 1, 121_453_000L, 123_000,
			"Klar received a drop: Dragon claws (121,453,000 coins).", 24, 36, threeSources());
	}

	/** The whip card of {@link ItemCardTest}: three drop sources, the table's order. */
	private static ItemCard whip()
	{
		return new ItemCard(4151, "Abyssal whip", 1, 1_500_000L, 72_000,
			"Klar received a drop: Abyssal whip (1,500,000 coins).", 22, 34, threeSources());
	}

	private static List<DropRates.DropSource> threeSources()
	{
		return Arrays.asList(new DropRates.DropSource("Unsired", "1/10.7", "Unsired"),
			new DropRates.DropSource("Greater abyssal demon", "1/170.7", "Greater_abyssal_demon"),
			new DropRates.DropSource("Abyssal demon", "1/512", "Abyssal_demon"));
	}

	/** A 36 x 32 stand-in for the item sprite, solid red. */
	private static BufferedImage redSprite()
	{
		final BufferedImage sprite = new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = sprite.createGraphics();
		g.setColor(Color.RED);
		g.fillRect(0, 0, 36, 32);
		g.dispose();
		return sprite;
	}

	/** The split card at the top-left of a black image at {@code fontSize}; the image and the size it reports. */
	private static Object[] splitPainted(HoverCard card, int fontSize, String description)
	{
		final BufferedImage image = new BufferedImage(520, 300, BufferedImage.TYPE_INT_RGB);
		final Graphics2D g = image.createGraphics();
		final Dimension size = CardPainter.paintSplit(g, card, redSprite(), fontSize, 0, 0, description, 480, 3);
		g.dispose();
		return new Object[]{image, size};
	}

	/** The size of a split card at 16 px. */
	private static Dimension splitSize(HoverCard card, String description)
	{
		return (Dimension) splitPainted(card, 16, description)[1];
	}

	/** The size of a wide card {@code width} wide at 16 px. */
	private static Dimension wideSize(HoverCard card, int width, String description)
	{
		final BufferedImage image = new BufferedImage(600, 300, BufferedImage.TYPE_INT_RGB);
		final Graphics2D g = image.createGraphics();
		final Dimension size = CardPainter.paintWide(g, card, redSprite(), 16, width, 0, 0, description, ACCENT);
		g.dispose();
		return size;
	}

	@Test
	public void theSplitCardIsCentredAboveTheCursor()
	{
		final Dimension card = new Dimension(360, 150);
		assertEquals("centred on the cursor, 6 px above it", new Rectangle(120, 244, 360, 150),
			CardPainter.placeCentred(new Point(300, 400), card, CANVAS));
		assertEquals("at the left edge it starts on the canvas's edge", new Rectangle(0, 244, 360, 150),
			CardPainter.placeCentred(new Point(100, 400), card, CANVAS));
		assertEquals("at the right edge it ends on the canvas's edge", new Rectangle(405, 244, 360, 150),
			CardPainter.placeCentred(new Point(700, 400), card, CANVAS));
		assertEquals("at the top it opens below the cursor", new Rectangle(120, 118, 360, 150),
			CardPainter.placeCentred(new Point(300, 100), card, CANVAS));

		final Rectangle chat = new Rectangle(0, 340, 519, 142);
		assertEquals("the wide card's bottom edge is on the chatbox's top edge", new Rectangle(0, 227, 519, 113),
			CardPainter.placeAboveChat(chat, new Dimension(519, 113)));
		assertEquals("a card taller than the room above the chatbox is held at the top", new Rectangle(0, 0, 519, 400),
			CardPainter.placeAboveChat(chat, new Dimension(519, 400)));
	}

	@Test
	public void theHeaderCardHasItsWidthsAndGrows()
	{
		final int bodyHeight = bodyMetrics().getAscent() + bodyMetrics().getDescent() + 2;
		final Object[] sixteen = splitPainted(claws(), 16, PARAGRAPH);
		final BufferedImage image = (BufferedImage) sixteen[0];
		final Dimension size = (Dimension) sixteen[1];
		// Re-aimed by the lead, 2026-10-08 (lot 8O): the header across the top, the paragraph under.
		assertEquals("480 wide at 16 px with a paragraph", 480, size.width);
		assertEquals("600 wide at 20 px", 600, ((Dimension) splitPainted(claws(), 20, PARAGRAPH)[1]).width);
		assertEquals("240 wide at 8 px", 240, ((Dimension) splitPainted(claws(), 8, PARAGRAPH)[1]).width);
		final Dimension bare = splitSize(claws(), NONE);
		assertTrue("with no paragraph it is narrower than 480: " + bare.width, bare.width < 480);
		assertTrue("and at least 18 px wider than its hint: " + bare.width + " vs " + hintWidth(claws()),
			bare.width >= hintWidth(claws()) + 18);

		// The ground is solid, rgb(70, 61, 50), nothing of the black shows through.
		final Color ground = new Color(image.getRGB(3, 3));
		assertEquals(70, ground.getRed());
		assertEquals(61, ground.getGreen());
		assertEquals(50, ground.getBlue());

		// The sprite's box starts 9 px in: the black edge, the line inside it and the 7 px padding.
		final Color sprite = new Color(image.getRGB(9, 9));
		assertTrue("the sprite's top-left pixel is red: " + sprite, sprite.getRed() > 200 && sprite.getGreen() < 40
			&& sprite.getBlue() < 40);
		final Color before = new Color(image.getRGB(8, 8));
		assertTrue("and the pixel before it is the ground: " + before, before.getRed() < 100);

		// There are no columns: no 1 px column of the rule colour stands at x 120 through the content (the paragraph's rule
		// and the hint's cross it, a pixel each).
		int rule = 0;
		for (int y = 5; y < size.height - 6; y++)
		{
			if (image.getRGB(120, y) == (CardPainter.LINE.getRGB() | 0xFF000000))
			{
				rule++;
			}
		}
		assertTrue("no column rule at x 120 (" + rule + " px) in a card " + size.height + " tall", rule < 10);

		// Growth: a paragraph takes up to three lines and its rule; the drops take one line however many sources there are.
		assertEquals("three paragraph lines and the rule", 3 * bodyHeight + 5,
			splitSize(claws(), PARAGRAPH).height - bare.height);
		assertEquals("one paragraph line and the rule", bodyHeight + 5, splitSize(claws(), "a b c").height - bare.height);
		assertEquals("the drops are one line", bodyHeight, splitSize(whip(), NONE).height - bare.height);
		assertTrue("six sources are never shorter than three: " + splitSize(whipWith(6), NONE).height + " vs "
			+ splitSize(whip(), NONE).height, splitSize(whipWith(6), NONE).height >= splitSize(whip(), NONE).height);
	}

