		when(config.cardPlace()).thenReturn(ClanHubConfig.CardPlace.CURSOR);

		final String line = "Klar received a drop: Dragon claws (121,453,000 coins) from Duke Sucellus.";
		final int start = line.indexOf("Duke Sucellus");
		final int end = start + "Duke Sucellus".length();
		final InfoCard duke = new InfoCard("Duke Sucellus", Collections.<HoverCard.Pair>emptyList(),
			Collections.<String>emptyList(), "Duke_Sucellus", line, start, end, SkillSprites.spriteOf("Combat"), -1, false,
			true);
		final String other = "Klar received a drop: Dragon claws (121,453,000 coins) from Zulrah.";
		final InfoCard zulrah = new InfoCard("Zulrah", Collections.<HoverCard.Pair>emptyList(),
			Collections.<String>emptyList(), "Zulrah", other, other.indexOf("Zulrah"), other.length() - 1,
			SkillSprites.spriteOf("Combat"), -1, false, true);
		final CardStore store = new CardStore();
		store.put(line, Collections.<HoverCard>singletonList(duke));
		store.put(other, Collections.<HoverCard>singletonList(zulrah));
		overlay.attach(store);
		final Widget dukeLine = lineSaying(line, new Rectangle(0, 400, 500, 14));
		final Widget zulrahLine = lineSaying(other, new Rectangle(0, 420, 500, 14));
		when(area.getDynamicChildren()).thenReturn(new Widget[] {dukeLine, zulrahLine});
		final int words = wordsX(line, start, end, 0);

		assertSame("the words are hit", duke, frameAt(words, 407));
		assertNotNull("the box is painted", paintedBox(414));
		assertNull("no picture yet, the sprite manager has no sprite either: nothing red", redBox());
		verify(factory, times(1)).newCall(any(Request.class));

		final ArgumentCaptor<Callback> page = ArgumentCaptor.forClass(Callback.class);
		verify(call, times(1)).enqueue(page.capture());
		page.getValue().onResponse(call, answer("application/json", DUKE_PAGE.getBytes(StandardCharsets.UTF_8)));
		verify(factory, times(2)).newCall(any(Request.class));
		final ArgumentCaptor<Callback> thumb = ArgumentCaptor.forClass(Callback.class);
		verify(call, times(2)).enqueue(thumb.capture());
		thumb.getValue().onResponse(call, answer("image/png", fixtureBytes()));

		assertSame("the same card is still hit", duke, frameAt(words, 407));
		final Rectangle card = paintedBox(414);
		assertNotNull(card);
		final Rectangle red = redBox();
		assertNotNull("the picture's red shows in the box", red);
		assertTrue("at least 40 wide and 10 tall: " + red, red.width >= 40 && red.height >= 10);
		final int expected = card.x + CardPainter.INSET + 4;
		assertTrue("its left is the box's left + 9 + 4, within 2 px: " + red.x + " vs " + expected,
			Math.abs(red.x - expected) <= 2);
		assertTrue("it lies inside the 64 px box, which is 9 px in from the card's top: " + red,
			red.y >= card.y + CardPainter.INSET
				&& red.y + red.height <= card.y + CardPainter.INSET + CardPainter.PICTURE_BOX);
		verify(factory, times(2)).newCall(any(Request.class));

		when(config.wikiPictures()).thenReturn(false);
		assertSame("still hit with the setting off", duke, frameAt(words, 407));
		assertNotNull(paintedBox(414));
		assertNull("with the setting off no picture is drawn", redBox());

		assertSame("a fresh card is hit", zulrah,
			frameAt(wordsX(other, other.indexOf("Zulrah"), other.length() - 1, 0), 427));
		assertNotNull(paintedBox(434));
		verify(factory, times(2)).newCall(any(Request.class));
	}

	/**
	 * The chat moves a row: the claws line {@code visible} rises to y 386 and a new line, which has no card, sits where the
	 * mouse was (y 400 to 414); the area answers both, the new one last.
	 */
	private void theChatMovesUp(Widget visible)
	{
		when(visible.getBounds()).thenReturn(new Rectangle(0, 386, 500, 14));
		final Widget fresh = lineSaying("Someone: hello there", new Rectangle(0, 400, 500, 14));
		when(area.getDynamicChildren()).thenReturn(new Widget[] {visible, fresh});
	}

	@Test
	public void theCardHoldsWhileTheMouseIsStillWhenTheChatMoves()
	{
		final Widget visible = line(new Rectangle(0, 400, 500, 14));
		when(area.getDynamicChildren()).thenReturn(new Widget[] {visible});
		final int words = wordsX(LINE, 22, 34, 0);

		assertSame("on the words", claws, frameAt(words, 407));
		assertTrue("the card painted", painted());

		theChatMovesUp(visible);
		assertSame("the chat moved, the mouse did not: the card stays", claws, frameAt(words, 407));
		assertTrue("the held card painted", painted());
		assertSame("and on the next frame", claws, frameAt(words, 407));
		assertTrue("still painted", painted());
		assertSame("two pixels off, within the jitter", claws, frameAt(words + 2, 407));
		assertTrue("still painted within the jitter", painted());
		assertNull("three pixels from where it rested ends the hold", frameAt(words + 3, 407));
		assertFalse("nothing painted", painted());
		assertNull("back at the rested spot the hold is over, and the new line has no card", frameAt(words, 407));
		assertFalse("nothing painted back at the rested spot", painted());
	}

	@Test
	public void aWheelTurnEndsTheHold()
	{
		final Widget visible = line(new Rectangle(0, 400, 500, 14));
		when(area.getDynamicChildren()).thenReturn(new Widget[] {visible});
		final int words = wordsX(LINE, 22, 34, 0);

		assertSame("on the words", claws, frameAt(words, 407));
		theChatMovesUp(visible);
		assertSame("the card is held", claws, frameAt(words, 407));
		assertTrue("the held card painted", painted());

		overlay.wheeled();
		assertNull("the wheel turned: the hold ends", frameAt(words, 407));
		assertFalse("nothing painted", painted());
		assertNull("and the wheel does not need turning again", frameAt(words, 407));
		assertFalse("still nothing painted", painted());
	}

	@Test
	public void leavingTheChatEndsTheHold()
	{
		final Widget visible = line(new Rectangle(0, 400, 500, 14));
		when(area.getDynamicChildren()).thenReturn(new Widget[] {visible});
		final int words = wordsX(LINE, 22, 34, 0);

		assertSame("on the words", claws, frameAt(words, 407));
		theChatMovesUp(visible);
		assertSame("the card is held", claws, frameAt(words, 407));

		assertNull("outside the area", frameAt(100, 207));
		assertFalse("nothing painted outside the area", painted());
		assertNull("back at the rested point the hold is over", frameAt(words, 407));
		assertFalse("nothing painted", painted());
	}

	@Test
	public void aClickedCardHoldsThroughTheShiftToo()
	{
		when(config.cardTrigger()).thenReturn(ClanHubConfig.CardTrigger.CLICK);
		final Widget visible = line(new Rectangle(0, 400, 500, 14));
		when(area.getDynamicChildren()).thenReturn(new Widget[] {visible});
		final int words = wordsX(LINE, 22, 34, 0);

		overlay.clicked();
		frameAt(words, 407);
		assertTrue("the click opens the card", painted());

		theChatMovesUp(visible);
		frameAt(words, 407);
		assertTrue("the clicked card holds through the shift", painted());
		frameAt(words, 407);
		assertTrue("and on the next frame", painted());

		overlay.wheeled();
		frameAt(words, 407);
		assertFalse("the wheel turned: the card is gone", painted());
		frameAt(words, 407);
		assertFalse("and it needs a new click to come back", painted());
	}

	@Test
	public void theHoldDoesNotStartOnAMove()
	{
		final Widget visible = line(new Rectangle(0, 400, 500, 14));
		when(area.getDynamicChildren()).thenReturn(new Widget[] {visible});
		final int words = wordsX(LINE, 22, 34, 0);

		assertSame("on the words", claws, frameAt(words, 407));
		assertTrue("the card painted", painted());

		theChatMovesUp(visible);
		assertNull("the shift came with a move of a pixel: no hold", frameAt(words + 1, 407));
		assertFalse("nothing painted", painted());
	}
}

package com.clanhub;

import com.google.gson.Gson;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * {@link ChatCommandReader}: the answers of RuneLite's Chat Commands plugin, a kill count and a personal best, are read
 * from the text as drawn, and nothing else is.
 */
public class ChatCommandReaderTest
{
	/** The one card a text gives. */
	private static HoverCard theCard(String text)
	{
		// Re-aimed by the lead, 2026-10-08 (lot 8T): the reader takes the tables.
		final List<HoverCard> cards = ChatCommandReader.read(text, new CardTables());
		assertEquals("one card from: " + text, 1, cards.size());
		return cards.get(0);
	}

	/** The card's one row as its label and value, the two set apart by a space. */
	private static String rowOf(HoverCard card)
	{
		assertEquals("one row", 1, card.rows().size());
		assertEquals("one pair", 1, card.rows().get(0).size());
		final HoverCard.Pair pair = card.rows().get(0).get(0);
		return pair.label + " " + pair.value;
	}

	@Test
	public void readsAKillCountAnswerAsDrawn()
	{
		final HoverCard brutus = theCard("Brutus kill count: 343");
		assertEquals("Brutus kill count", brutus.title());
		assertEquals("Kills 343", rowOf(brutus));
		assertEquals("Brutus", brutus.plainLine().substring(brutus.start(), brutus.end()));
		assertFalse("the chat does not colour it: there is no event for the rewrite", brutus.marked());
		assertEquals("Brutus", brutus.wikiTitle());
		assertEquals(SkillSprites.spriteOf("Combat"), brutus.spriteId());
		assertEquals(-1, brutus.itemId());
		// Re-aimed by the lead, 2026-10-08 (lot 8U): the wiki's picture is asked for, the combat icon stands behind it.
		assertTrue("the kill count answer asks for the wiki's picture", brutus.wikiPicture());
		assertEquals("Brutus kill count: 343", brutus.plainLine());

		final HoverCard raid = theCard("Chambers of Xeric Challenge Mode kill count: 1,303");
		assertEquals("Chambers of Xeric Challenge Mode kill count", raid.title());
		assertEquals("Kills 1,303", rowOf(raid));
		assertEquals("Chambers of Xeric Challenge Mode", raid.plainLine().substring(raid.start(), raid.end()));
		assertEquals("Chambers of Xeric Challenge Mode", raid.wikiTitle());

		// "From zambzy: " is 13 characters, so the words stand at 13..19.
		final HoverCard sent = theCard("From zambzy: Brutus kill count: 343");
		assertEquals("Brutus kill count", sent.title());
		assertEquals(13, sent.start());
		assertEquals(19, sent.end());
		assertEquals("Brutus", sent.plainLine().substring(sent.start(), sent.end()));
		assertEquals("Kills 343", rowOf(sent));
	}

	@Test
	public void readsAPersonalBestAnswerAsDrawn()
	{
		final HoverCard raid = theCard("Chambers of Xeric personal best: 21:14");
		assertEquals("Chambers of Xeric personal best", raid.title());
		assertEquals("Time 21:14", rowOf(raid));
		assertEquals("Chambers of Xeric", raid.plainLine().substring(raid.start(), raid.end()));
		assertFalse("quiet", raid.marked());
		assertEquals(ItemID.TRAIL_WATCH, raid.itemId());
		assertEquals(-1, raid.spriteId());
		assertEquals("Chambers of Xeric", raid.wikiTitle());
		// Re-aimed by the lead, 2026-10-08 (lot 8U): the wiki's picture is asked for, the clue watch stands behind it.
		assertTrue("the personal best answer asks for the wiki's picture", raid.wikiPicture());

		assertEquals("Time 14:32.40", rowOf(theCard("Theatre of Blood personal best: 14:32.40")));
		assertEquals("Time 1:02:15", rowOf(theCard("Inferno personal best: 1:02:15")));
		assertTrue("a sender in front of the answer", theCard("Klar: Inferno personal best: 1:02:15").start() > 0);
	}

	@Test
	public void readsNothingElse()
	{
		final String[] none = {
			"Your Zulrah kill count is: 343.",
			"!kc brutus",
			"Iron Pete has a funny feeling like he's being followed: Pet snakeling at 2,678 killcount.",
			"Klar: gz",
			"",
			"zambzy: Brutus kill count: 343 lol",
			"kill count: 343",
		};
		for (final String text : none)
		{
			// Re-aimed by the lead, 2026-10-08 (lot 8T): the reader takes the tables.
			assertTrue("nothing from: " + text, ChatCommandReader.read(text, new CardTables()).isEmpty());
		}
		assertTrue("nothing from null", ChatCommandReader.read(null, new CardTables()).isEmpty());
	}

	/** The card's one row as each pair's label and value, in order. */
	private static List<String> pairsOf(HoverCard card)
	{
		assertEquals("one row", 1, card.rows().size());
		final List<String> pairs = new ArrayList<>();
		for (final HoverCard.Pair pair : card.rows().get(0))
		{
			pairs.add(pair.label + " " + pair.value);
		}
		return pairs;
	}

	// Re-aimed by the lead, 2026-10-08 (lot 8U): the wiki's picture replaces the pet.
	@Test
	public void theAnswersCarryTheBoss() throws Exception
	{
		final CardTables tables;
		try (Reader cards = new InputStreamReader(ChatCommandReaderTest.class.getResourceAsStream(
			"/com/clanhub/cards-fixture.json"), StandardCharsets.UTF_8);
			Reader bosses = new InputStreamReader(ChatCommandReaderTest.class.getResourceAsStream(
				"/com/clanhub/bosses-fixture.json"), StandardCharsets.UTF_8))
		{
			tables = CardTables.parse(cards, new Gson()).readBosses(bosses, new Gson());
		}

		final HoverCard brutus = ChatCommandReader.read("Brutus kill count: 343", tables).get(0);
		assertEquals("Brutus kill count", brutus.title());
		assertEquals(Arrays.asList("Kills 343", "Combat 70", "Hitpoints 100", "Max hit 10", "Quest The Ides of Milk"),
			pairsOf(brutus));
		assertEquals("a kill count has no item behind the picture", -1, brutus.itemId());
		assertTrue("it asks for the wiki's picture", brutus.wikiPicture());
		assertEquals("and the combat sprite stands behind it", SkillSprites.spriteOf("Combat"), brutus.spriteId());
		assertFalse("still quiet", brutus.marked());
		assertEquals("Brutus", brutus.plainLine().substring(brutus.start(), brutus.end()));

		final HoverCard zulrah = ChatCommandReader.read("zambzy: Zulrah kill count: 1,224", tables).get(0);
		assertEquals(Arrays.asList("Kills 1,224", "Combat 725", "Hitpoints 500", "Max hit 41"), pairsOf(zulrah));
		assertEquals("no pet: the wiki's picture replaces it", -1, zulrah.itemId());
		assertTrue(zulrah.wikiPicture());

		final HoverCard raid = ChatCommandReader.read("Chambers of Xeric personal best: 21:14", tables).get(0);
		assertEquals("a raid with no stats has the time alone", Arrays.asList("Time 21:14"), pairsOf(raid));
		assertEquals("the clue watch behind its picture", ItemID.TRAIL_WATCH, raid.itemId());
		assertTrue(raid.wikiPicture());
		assertEquals(-1, raid.spriteId());

		final HoverCard best = ChatCommandReader.read("Vorkath personal best: 2:28", tables).get(0);
		assertEquals(Arrays.asList("Time 2:28", "Combat 732", "Hitpoints 750", "Max hit 32", "Quest Dragon Slayer II"),
			pairsOf(best));

		final HoverCard bare = ChatCommandReader.read("Brutus kill count: 343", new CardTables()).get(0);
		assertEquals("a table that has not loaded gives the card as today", Arrays.asList("Kills 343"), pairsOf(bare));
		assertEquals(-1, bare.itemId());
		assertTrue("a table that has not loaded still asks for the wiki's picture", bare.wikiPicture());
		assertEquals(Arrays.asList("Kills 343"), pairsOf(ChatCommandReader.read("Nobody kill count: 343", tables).get(0)));
		final HoverCard inferno = ChatCommandReader.read("Inferno personal best: 1:02:15", tables).get(0);
		assertEquals("a personal best the table lacks keeps the clue watch", ItemID.TRAIL_WATCH, inferno.itemId());
		assertTrue(inferno.wikiPicture());
	}
}

package com.clanhub;

import java.awt.Rectangle;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.function.ToIntFunction;
import org.junit.Test;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/** {@link ChatRows}: where the game breaks a wrapped line, the row a word is on, and a card's words row by row. */
public class ChatRowsTest
{
	/** Ten pixels a character. */
	private static final ToIntFunction<String> TEN = s -> s.length() * 10;

	/** A card whose words stand at {@code start} to {@code end} of its line. */
	private static ItemCard spanning(int start, int end)
	{
		return new ItemCard(1, "Item", 1, 1L, 1, "a line", start, end);
	}

	@Test
	public void breaksAtSpacesLikeTheGame()
	{
		final ChatRows two = ChatRows.of("aaaa bbbb cccc dddd", TEN, new Rectangle(0, 400, 100, 28));
		assertEquals(2, two.rows());
		assertEquals(0, two.start(0));
		assertEquals(9, two.end(0));
		assertEquals(10, two.start(1));
		assertEquals(19, two.end(1));
		assertEquals(0, two.rowOf(0));
		assertEquals("the break space is on the row before", 0, two.rowOf(9));
		assertEquals(1, two.rowOf(10));
		assertEquals(1, two.rowOf(18));
		assertEquals("an index past the text is on the last row", 1, two.rowOf(19));
		assertEquals(50, two.x(5));
		assertEquals(0, two.x(10));
		assertEquals(50, two.x(15));
		assertEquals(0, two.rowAt(405));
		assertEquals(1, two.rowAt(420));
		assertEquals("above the widget is the first row", 0, two.rowAt(399));
		assertEquals("below it is the last", 1, two.rowAt(500));
		assertEquals(414, two.underlineY(0));
		assertEquals(428, two.underlineY(1));

		final ChatRows one = ChatRows.of("aaaa", TEN, new Rectangle(0, 400, 100, 14));
		assertEquals(1, one.rows());
		assertEquals(414, one.underlineY(0));
		assertEquals(0, one.rowAt(407));
		assertEquals(40, one.x(4));

		final ChatRows empty = ChatRows.of("", TEN, new Rectangle(0, 400, 100, 14));
		assertEquals(1, empty.rows());
		assertEquals(0, empty.start(0));
		assertEquals(0, empty.end(0));

		final ChatRows wide = ChatRows.of("aaaaaaaaaaaa bb", TEN, new Rectangle(0, 400, 100, 28));
		assertEquals("a word wider than the row stands alone, uncut", 2, wide.rows());
		assertEquals(12, wide.end(0));
		assertEquals(13, wide.start(1));
		assertEquals(15, wide.end(1));
	}

	@Test
	public void picksTheCardOnTheMousesRowAndSpansEachRow()
	{
		final ChatRows two = ChatRows.of("aaaa bbbb cccc dddd", TEN, new Rectangle(0, 400, 100, 28));
		final HoverCard a = spanning(5, 9);
		final HoverCard b = spanning(15, 19);
		final List<HoverCard> both = Arrays.asList(a, b);
		assertSame(a, two.pick(both, 0, 60, 405));
		assertSame(b, two.pick(both, 0, 60, 420));
		assertNull("right of the words on the first row", two.pick(both, 0, 95, 405));
		assertNull("left of the words on the second row", two.pick(both, 0, 20, 420));
		assertNull("left of the words on the first row", two.pick(both, 0, 0, 405));

		final List<HoverCard> across = Collections.<HoverCard>singletonList(spanning(5, 14));
		final HoverCard c = across.get(0);
		assertSame("the first row's piece", c, two.pick(across, 0, 60, 405));
		assertSame("the second row's piece", c, two.pick(across, 0, 20, 420));
		assertNull("under the first row's piece, on the second row", two.pick(across, 0, 60, 420));

		assertEquals(1, two.spans(5, 9).size());
		assertArrayEquals(new int[] {50, 90, 414}, two.spans(5, 9).get(0));
		final List<int[]> broken = two.spans(5, 14);
		assertEquals(2, broken.size());
		assertArrayEquals(new int[] {50, 90, 414}, broken.get(0));
		assertArrayEquals(new int[] {0, 40, 428}, broken.get(1));
		assertTrue("a break space alone has no piece", two.spans(9, 10).isEmpty());

		final ChatRows three = ChatRows.of("xx aaaa bbbb cccc dddd", TEN, new Rectangle(0, 400, 100, 42));
		assertEquals(3, three.rows());
		assertSame(a, three.pick(both, 3, 20, 420));
		assertSame(b, three.pick(both, 3, 20, 435));
		assertNull(three.pick(both, 3, 20, 405));
		final List<int[]> third = three.spans(8, 12);
		assertEquals(1, third.size());
		assertArrayEquals(new int[] {0, 40, 428}, third.get(0));
	}
}

package com.clanhub;

import java.awt.Color;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** {@link ChatText}: the plain text a card's offsets index, and the colour tags put around its words. */
public class ChatTextTest
{
	private static final Color BLUE = new Color(59, 130, 246);

	/** The spans as text, so a list of them can be compared: "[22, 34]". */
	private static List<String> shown(List<int[]> spans)
	{
		final List<String> shown = new ArrayList<>();
		for (final int[] span : spans)
		{
			shown.add(Arrays.toString(span));
		}
		return shown;
	}

	/** A quest broadcast as the game now sends it: the quest's name is a string variable, defined first, drawn by a reference. */
	private static final String RAW =
		"<img=2> <str_quest_name_0=King's Ransom>Small Za has completed a quest: <str_quest_name_0>";
	private static final String PLAIN = "Small Za has completed a quest: King's Ransom";

	@Test
	public void plainExpandsTheGamesStringVariables()
	{
		assertEquals("<img=2> Small Za has completed a quest: King's Ransom", ChatText.expand(RAW));
		assertEquals(PLAIN, ChatText.plain(RAW));

		assertEquals("x Two=2 One", ChatText.plain("<str_a=One> <str_b=Two=2> x <str_b> <str_a>"));
		assertEquals("a later definition replaces the earlier", "Two Two",
			ChatText.plain("<str_a=One><str_a=Two><str_a> <str_a>"));
		assertEquals("a reference never defined is nothing", "a  b", ChatText.plain("a <str_nothing> b"));
		assertEquals("a tag that is no variable is an ordinary tag", "Klar: gz",
			ChatText.plain("<col=ff0000>Klar</col>: <str a>gz"));

		final String untouched = "<col=0000a0>Klar received a drop: Dragon claws (1 coins).</col>";
		assertEquals("no variables, no change", untouched, ChatText.expand(untouched));
		assertEquals("", ChatText.expand(null));
	}

	@Test
	public void coloursASpanOverAStringVariable()
	{
		final int start = PLAIN.indexOf("King's");
		assertEquals("<img=2> <str_quest_name_0=King's Ransom>Small Za has completed a quest: "
			+ "<col=3b82f6><str_quest_name_0><colNORMAL>",
			ChatText.colourSpans(RAW, Collections.singletonList(new int[] {start, PLAIN.length()}), BLUE));

		assertEquals("a span over the literal words leaves both variable tags where they are",
			"<img=2> <str_quest_name_0=King's Ransom><col=3b82f6>Small Za<colNORMAL> has completed a quest: "
			+ "<str_quest_name_0>",
			ChatText.colourSpans(RAW, Collections.singletonList(new int[] {0, 8}), BLUE));

		assertEquals("a span that starts and ends inside the value takes the reference whole",
			"<img=2> <str_quest_name_0=King's Ransom>Small Za has completed a quest: "
			+ "<col=3b82f6><str_quest_name_0><colNORMAL>",
			ChatText.colourSpans(RAW, Collections.singletonList(new int[] {start + 7, start + 10}), BLUE));

		assertEquals("two spans over one variable colour it once",
			"<img=2> <str_quest_name_0=King's Ransom>Small Za has completed a quest: "
			+ "<col=3b82f6><str_quest_name_0><colNORMAL>",
			ChatText.colourSpans(RAW, Arrays.asList(new int[] {start, start + 4}, new int[] {start + 6, PLAIN.length()}),
				BLUE));
	}

	@Test
	public void plainStripsTagsAndTheAchievementPrefix()
	{
		assertEquals("Mossy Rock has completed a Master combat task: Perfect Zulrah (5 points).",
			ChatText.plain("<col=0000a0>CA_ID:279|Mossy Rock has completed a Master combat task: Perfect Zulrah "
