import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.when;

/** {@link DemoLines}: the item samples are broadcasts the reader reads, and they lead the list of every sample. */
public class DemoLinesTest
{
	@Test
	public void everyItemSampleIsABroadcastTheReaderReads()
	{
		// Re-aimed by the lead, 2026-10-08 (lot 8R): a fifth item line, the drop that says where it came from.
		final List<String> expected = Arrays.asList("Dragon claws", "Black knife", "Ranger boots", "Abyssal whip",
			"Runite ore");
		assertEquals(expected.size(), DemoLines.ITEMS.size());
		for (int i = 0; i < DemoLines.ITEMS.size(); i++)
		{
			final DemoLines.Line line = DemoLines.ITEMS.get(i);
			final Optional<BroadcastLine.ItemMention> found = BroadcastLine.parse(line.type, line.text);
			assertTrue("a mention in: " + line.text, found.isPresent());
			assertEquals(expected.get(i), found.get().name);
			assertEquals("a broadcast has no speaker", "", line.name);
		}

		final List<DemoLines.Line> all = DemoLines.lines();
		assertTrue("lines() holds at least the five", all.size() >= DemoLines.ITEMS.size());
		assertEquals("lines() starts with the five", DemoLines.ITEMS, all.subList(0, DemoLines.ITEMS.size()));
		assertTrue("the fifth names its boss", DemoLines.ITEMS.get(4).text.endsWith("from Duke Sucellus."));
	}

	@Test
	public void theOwnSamplesFollowTheItems()
	{
		// Re-aimed by the lead, 2026-10-08 (lot 8e): player chat is never read, so the demo has no typed line.
		final List<DemoLines.Line> all = DemoLines.lines();
		final int items = DemoLines.ITEMS.size();
		assertEquals(2, DemoLines.OWN.size());
		assertEquals("the own lines follow the items", DemoLines.OWN, all.subList(items, items + 2));
		// Re-aimed by the lead, 2026-10-08 (lot 8R): the fifth item line makes 16 in all.
		// Re-aimed by the lead, 2026-10-08 (lot 8V): combat level and total level lines give no card, so 14 in all.
		// Re-aimed by the lead, 2026-10-09 (lot 9E): a second quest line, in the game's string-variable form.
		assertEquals("15 lines in all", 15, all.size());

		final ItemCards itemCards = Mockito.mock(ItemCards.class);
		when(itemCards.forName(anyString(), anyInt(), anyString(), anyInt(), anyInt())).thenAnswer(call ->
			new ItemCard(0, call.getArgument(0), call.getArgument(1), 0L, 0, call.getArgument(2),
				call.getArgument(3), call.getArgument(4)));
		// Re-aimed by the lead, 2026-10-08 (lot 8T): the reader takes the tables.
		final OwnLineReader reader = new OwnLineReader(itemCards, () -> true, new CardTables());
		for (final DemoLines.Line line : DemoLines.OWN)
		{
			assertEquals(ChatMessageType.GAMEMESSAGE, line.type);
			assertEquals("an own game line has no speaker", "", line.name);
			assertEquals("one card from: " + line.text, 1, reader.read(line.type, line.text).size());
		}
	}

	@Test
	public void theKindSamplesEndTheList() throws Exception
	{
		// Re-aimed by the lead, 2026-10-08 (lot 8V): combat level and total level lines give no card, so seven kinds.
		// Re-aimed by the lead, 2026-10-09 (lot 9E): a second quest line, in the game's string-variable form.
		assertEquals(8, DemoLines.KINDS.size());
		for (final DemoLines.Line line : DemoLines.KINDS)
		{
			assertEquals(ChatMessageType.CLAN_MESSAGE, line.type);
			assertEquals("a broadcast has no speaker", "", line.name);
		}
		final List<DemoLines.Line> all = DemoLines.lines();
		assertEquals("lines() ends with the kinds", DemoLines.KINDS, all.subList(all.size() - 8, all.size()));

		final CardTables tables;
		try (Reader in = new InputStreamReader(DemoLinesTest.class.getResourceAsStream("/com/clanhub/cards-fixture.json"),
			StandardCharsets.UTF_8))
		{
			tables = CardTables.parse(in, new Gson());
		}
		final BroadcastKindReader reader = new BroadcastKindReader(tables, Mockito.mock(ItemCards.class));
		for (final DemoLines.Line line : DemoLines.KINDS)
		{
			assertTrue("a card from: " + line.text, reader.read(line.type, line.text).size() >= 1);
		}
	}
}

package com.clanhub;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.InputStreamReader;
import java.io.Reader;
import java.io.StringReader;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.Map;
import org.junit.Assume;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** {@link DropRates}: the table's shape read from a small fixture, an empty table, and the real bundled table. */
public class DropRatesTest
{
	private static final String FIXTURE = "/com/clanhub/drops-fixture.json";
	private static final String BUNDLED = "/com/clanhub/drops.json";

	/** A classpath resource opened as the plugin opens its table: read as UTF-8. */
	private static Reader open(String resource)
	{
		return new InputStreamReader(DropRatesTest.class.getResourceAsStream(resource), StandardCharsets.UTF_8);
	}

	@Test
	public void parsesTheFixtureAndAnswersByName() throws Exception
	{
		final DropRates rates;
		try (Reader in = open(FIXTURE))
		{
			rates = DropRates.parse(in, new Gson());
		}

		final List<DropRates.DropSource> whip = rates.lookup("Abyssal whip");
		assertEquals(2, whip.size());
		assertEquals("Abyssal demon", whip.get(0).from);
		assertEquals("1/512", whip.get(0).rate);
		assertEquals("Abyssal_demon", whip.get(0).wiki);
		assertEquals("Greater abyssal demon", whip.get(1).from);

		final List<DropRates.DropSource> lower = rates.lookup("abyssal whip");
		assertEquals(2, lower.size());
		assertEquals("Abyssal demon", lower.get(0).from);
		assertEquals("1/512", lower.get(0).rate);
		assertEquals("Abyssal_demon", lower.get(0).wiki);

		assertTrue(rates.lookup("Nonsense").isEmpty());
		assertTrue(rates.loaded());
	}

	@Test
	public void anEmptyTableAnswersNothingWithoutFailing()
	{
		final DropRates none = new DropRates();
		assertFalse(none.loaded());
		assertTrue(none.lookup("Dragon claws").isEmpty());

		final DropRates empty = DropRates.parse(new StringReader("{\"items\": {}}"), new Gson());
		assertTrue(empty.loaded());
		assertTrue(empty.lookup("Dragon claws").isEmpty());
	}

	/**
	 * Choice: the items are counted from the file's own list of names (read with a Gson of the test's own), each name
	 * asked of the parsed table, so the count is of items the table answers for and no member exists for the test alone.
	 */
	@Test
	public void theBundledTableParsesWhenItIsThere() throws Exception
	{
		Assume.assumeNotNull(DropRates.class.getResource(BUNDLED));
		final Gson gson = new Gson();
		final DropRates rates;
		try (Reader in = open(BUNDLED))
		{
			rates = DropRates.parse(in, gson);
		}
		final JsonObject root;
		try (Reader in = open(BUNDLED))
		{
			root = gson.fromJson(in, JsonObject.class);
		}

		int items = 0;
		for (final Map.Entry<String, JsonElement> item : root.getAsJsonObject("items").entrySet())
		{
			final List<DropRates.DropSource> sources = rates.lookup(item.getKey());
			if (!sources.isEmpty())
			{
				items++;
			}
			for (final DropRates.DropSource source : sources)
			{
				assertFalse("a source without a name for " + item.getKey(), source.from.isEmpty());
				assertFalse("a source without a rate for " + item.getKey(), source.rate.isEmpty());
			}
		}
		assertTrue("at least 1,000 items, found " + items, items >= 1000);
		assertFalse("the whip has a source", rates.lookup("Abyssal whip").isEmpty());
	}
}

package com.clanhub;

import java.awt.Color;
import java.awt.image.BufferedImage;
import javax.swing.ImageIcon;
import net.runelite.client.ui.ColorScheme;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

/** {@link GearGlyph}, in memory: its size, its transparent corners and hole, and the colour of its ring. */
public class GearGlyphTest
{
	private static final Color ORANGE = new Color(220, 138, 0);

	private static BufferedImage image(ImageIcon icon)
	{
		return (BufferedImage) icon.getImage();
	}

	@Test
	public void theIconIsAsBigAsAskedAndNoSmallerThanTheMinimum()
	{
		final ImageIcon twelve = GearGlyph.icon(12, ORANGE);
		assertEquals(12, twelve.getIconWidth());
		assertEquals(12, twelve.getIconHeight());
		assertEquals(GearGlyph.MIN_SIZE, GearGlyph.icon(3, ORANGE).getIconWidth());
	}

	@Test
	public void theFourCornersAndTheHoleAreTransparent()
	{
		final BufferedImage img = image(GearGlyph.icon(12, ORANGE));
		assertEquals(0, img.getRGB(0, 0) >>> 24);
		assertEquals(0, img.getRGB(11, 0) >>> 24);
		assertEquals(0, img.getRGB(0, 11) >>> 24);
		assertEquals(0, img.getRGB(11, 11) >>> 24);
		assertEquals(0, img.getRGB(5, 5) >>> 24);
		assertEquals(0, img.getRGB(6, 6) >>> 24);
	}

	@Test
	public void theRingIsSolidInTheGivenColour()
	{
		// (8, 7) sits on the ring between two teeth: well inside the metal, so fully opaque.
		assertEquals(0xFF000000 | ORANGE.getRGB(), image(GearGlyph.icon(12, ORANGE)).getRGB(8, 7));
	}

	@Test
	public void noColourMeansTheSidebarsGrey()
	{
		assertEquals(0xFF000000 | ColorScheme.LIGHT_GRAY_COLOR.getRGB(), image(GearGlyph.icon(12, null)).getRGB(8, 7));
		assertEquals(new Color(165, 165, 165), ColorScheme.LIGHT_GRAY_COLOR);
	}
}

package com.clanhub;

import java.util.Collections;
