	@Test
	public void theRateOfANameIsItsFirstSources() throws Exception
	{
		final DropRates rates;
		try (Reader in = new InputStreamReader(ItemCardsTest.class.getResourceAsStream("/com/clanhub/drops-fixture.json"),
			StandardCharsets.UTF_8))
		{
			rates = DropRates.parse(in, new Gson());
		}
		final ItemCards cards = new ItemCards(Mockito.mock(ItemManager.class), rates);

		assertEquals("1/512", cards.rateOf("Abyssal whip"));
		assertEquals("the case rule is the lookup's", "1/512", cards.rateOf("abyssal WHIP"));
		assertEquals("1/4000", cards.rateOf("Pet Snakeling"));
		assertEquals("", cards.rateOf("Nothing at all"));
		assertEquals("no table", "", new ItemCards(Mockito.mock(ItemManager.class), null).rateOf("Abyssal whip"));
		assertEquals("a table that has not loaded", "",
			new ItemCards(Mockito.mock(ItemManager.class), new DropRates()).rateOf("Abyssal whip"));
	}

	/**
	 * A source whose name holds one of these is a container, which the table lists after every monster. A copy of
	 * CONTAINER_WORDS in docs/data/fetch_drops.py, which makes the order: keep the two the same.
	 */
	private static final String[] CONTAINER_WORDS = {"chest", "cache", "lockbox", "casket", "sack", "coffin", "impling",
		"reward", "crate", "supply", "jar", "pouch", "barrel", "urn", "nest", "unsired"};

	private static final String BUNDLED = "/com/clanhub/drops.json";

	private static boolean isContainer(String source)
	{
		final String name = source.toLowerCase(Locale.ROOT);
		for (final String word : CONTAINER_WORDS)
		{
			if (name.contains(word))
			{
				return true;
			}
		}
		return false;
	}

	private static Reader bundled()
	{
		return new InputStreamReader(ItemCardsTest.class.getResourceAsStream(BUNDLED), StandardCharsets.UTF_8);
	}

	@Test
	public void theBundledTableIsMonstersFirstAndSixAtMost() throws Exception
	{
		Assume.assumeNotNull(ItemCardsTest.class.getResource(BUNDLED));
		final JsonObject items;
		try (Reader in = bundled())
		{
			items = new Gson().fromJson(in, JsonObject.class).getAsJsonObject("items");
		}
		assertTrue("the table holds items", items.size() > 1000);
		for (final Map.Entry<String, JsonElement> item : items.entrySet())
		{
			final JsonArray sources = item.getValue().getAsJsonArray();
			assertTrue(item.getKey() + " has " + sources.size() + " sources, more than six", sources.size() <= 6);
			boolean containerSeen = false;
			for (final JsonElement source : sources)
			{
				final String from = source.getAsJsonObject().get("from").getAsString();
				if (isContainer(from))
				{
					containerSeen = true;
				}
				else
				{
					assertFalse(item.getKey() + " lists the monster " + from + " after a container", containerSeen);
				}
			}
		}

		final DropRates rates;
		try (Reader in = bundled())
		{
			rates = DropRates.parse(in, new Gson());
		}
		final List<DropRates.DropSource> whip = rates.lookup("Abyssal whip");
		assertEquals(3, whip.size());
		assertEquals("Greater abyssal demon", whip.get(0).from);
		assertEquals("Abyssal demon", whip.get(1).from);
		assertEquals("Unsired", whip.get(2).from);

		final List<DropRates.DropSource> platelegs = rates.lookup("Dragon platelegs");
		assertTrue("Dragon platelegs has at least five sources: " + platelegs.size(), platelegs.size() >= 5);
		assertFalse("and its first is a monster: " + platelegs.get(0).from, isContainer(platelegs.get(0).from));
	}
}

package com.clanhub;

import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.when;

/** {@link ItemNameIndex}: built in slices, it keeps every real item's name, tradeable or not, and skips notes, placeholders and junk. */
public class ItemNameIndexTest
{
	/** An item the way the cache gives one: not a note, not a placeholder, the given name and worth. */
	private static ItemComposition item(String name, boolean tradeable, int alch, int note)
	{
		final ItemComposition composition = Mockito.mock(ItemComposition.class);
		when(composition.getName()).thenReturn(name);
		when(composition.isTradeable()).thenReturn(tradeable);
		when(composition.getHaPrice()).thenReturn(alch);
		when(composition.getNote()).thenReturn(note);
		when(composition.getPlaceholderTemplateId()).thenReturn(-1);
		return composition;
	}

	@Test
	public void buildsInChunksSkippingNotesPlaceholdersAndJunk()
	{
		final Client client = Mockito.mock(Client.class);
		when(client.getItemCount()).thenReturn(6);
		final ItemManager items = Mockito.mock(ItemManager.class);
		final ItemComposition[] compositions = {
			item("Dragon claws", true, 0, -1),
			item("Dragon claws", true, 0, 0),
			item("null", false, 0, -1),
			item("Man", false, 0, -1),
			item("Abyssal whip", true, 0, -1),
			item("Bones", false, 1, -1)};
		for (int id = 0; id < compositions.length; id++)
		{
			when(items.getItemComposition(id)).thenReturn(compositions[id]);
		}
		final ItemNameIndex index = new ItemNameIndex();
		assertFalse("not complete before it reads anything", index.complete());

		index.buildSome(client, items, 4);
		assertFalse(index.complete());
		assertEquals(4, index.next);
		assertEquals(Integer.valueOf(0), index.idOf("dragon claws"));
		assertNull(index.idOf("abyssal whip"));

		index.buildSome(client, items, 4);
		assertTrue(index.complete());
		assertEquals(Integer.valueOf(4), index.idOf("abyssal whip"));
		assertEquals(Integer.valueOf(5), index.idOf("bones"));
		assertNull(index.idOf("man"));
		assertNull(index.idOf("null"));
		assertEquals(3, index.size());
	}

	@Test
	public void keepsUntradeableNamesOfFiveCharactersOrMore()
	{
		final Client client = Mockito.mock(Client.class);
		when(client.getItemCount()).thenReturn(3);
		final ItemManager items = Mockito.mock(ItemManager.class);
		final ItemComposition[] compositions = {
			item("Pet snakeling", false, 0, -1),
			item("Man", false, 0, -1),
			item("null", false, 0, -1)};
		for (int id = 0; id < compositions.length; id++)
		{
			when(items.getItemComposition(id)).thenReturn(compositions[id]);
		}
		final ItemNameIndex index = new ItemNameIndex();

		index.buildSome(client, items, 10);

		assertTrue(index.complete());
		assertEquals(Integer.valueOf(0), index.idOf("pet snakeling"));
		assertNull(index.idOf("man"));
		assertNull(index.idOf("null"));
		assertEquals(1, index.size());
	}
}

package com.clanhub;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** {@link NavIcon}, in memory: the size, the coin exactly as {@link CoinGlyph} draws it, the picture clear of it. */
public class NavIconTest
{
	/** The coin's centre and the farthest its jittered rim reaches from it, with a pixel of margin. */
	private static final double COIN_CENTRE = 4.5;
	private static final double CLEAR_DISTANCE = 6.0;

	private static BufferedImage coinAlone()
	{
		final BufferedImage img = new BufferedImage(NavIcon.SIZE, NavIcon.SIZE, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		try
		{
			CoinGlyph.paint(g);
		}
		finally
		{
			g.dispose();
		}
		return img;
	}

	@Test
	public void theIconIsSixteenBySixteenArgb()
	{
		final BufferedImage icon = NavIcon.create();
		assertEquals(16, icon.getWidth());
		assertEquals(16, icon.getHeight());
		assertEquals(BufferedImage.TYPE_INT_ARGB, icon.getType());
	}

	@Test
	public void theCoinIsDrawnPixelForPixelAsTheCoinGlyphDrawsIt()
	{
		final BufferedImage icon = NavIcon.create();
		final BufferedImage coin = coinAlone();
		int coinPixels = 0;
		for (int y = 0; y < NavIcon.SIZE; y++)
		{
			for (int x = 0; x < NavIcon.SIZE; x++)
			{
				if ((coin.getRGB(x, y) >>> 24) != 0)
				{
					coinPixels++;
					assertEquals("coin pixel " + x + "," + y, coin.getRGB(x, y), icon.getRGB(x, y));
				}
			}
		}
		assertTrue("the coin drew something", coinPixels > 0);
	}

	@Test
	public void thePictureLiesClearOfTheCoinsCircle()
	{
		final BufferedImage icon = NavIcon.create();
		final BufferedImage coin = coinAlone();
		int pictureOnly = 0;
		for (int y = 0; y < NavIcon.SIZE; y++)
		{
			for (int x = 0; x < NavIcon.SIZE; x++)
			{
				if (icon.getRGB(x, y) != coin.getRGB(x, y))
				{
					pictureOnly++;
					final double dx = x + 0.5 - COIN_CENTRE;
					final double dy = y + 0.5 - COIN_CENTRE;
					assertTrue("picture pixel " + x + "," + y + " is too near the coin",
						Math.sqrt(dx * dx + dy * dy) >= CLEAR_DISTANCE);
				}
			}
		}
		assertTrue("the picture drew something", pictureOnly > 0);
	}

	private static final int PARCHMENT = 0xFFCDBE9E;
	private static final int CLAN = 0xFF0000B0;
	private static final int HOVER = 0xFF3B82F6;
	private static final int WHITE = 0xFFF0F0F0;
	private static final int INK = 0xFF16161A;

	private static void assertPixel(String what, int expected, BufferedImage icon, int x, int y)
	{
		assertEquals(what + " at " + x + "," + y, expected, icon.getRGB(x, y));
	}

	@Test
	public void thePictureIsTheHoveredChatLineAndTheCardAbove()
	{
		final BufferedImage icon = NavIcon.create();
		final BufferedImage coin = coinAlone();
		int differing = 0;
		for (int y = 0; y < NavIcon.SIZE; y++)
		{
			for (int x = 0; x < NavIcon.SIZE; x++)
			{
				if (icon.getRGB(x, y) != coin.getRGB(x, y))
				{
					differing++;
				}
			}
		}
		assertEquals("the picture's pixels", 107, differing);

		for (int x = 0; x < NavIcon.SIZE; x++)
		{
			// Rows 0 and 9 hold only the coin's own rim (left of x 10): the picture adds nothing, the row of air.
			assertEquals("row 0 is the coin alone at " + x, coin.getRGB(x, 0), icon.getRGB(x, 0));
			assertEquals("row 9 is the coin alone at " + x, coin.getRGB(x, 9), icon.getRGB(x, 9));
			if (x >= 10)
			{
				assertEquals("row 0 transparent at " + x, 0, icon.getRGB(x, 0) >>> 24);
				assertEquals("row 9 transparent at " + x, 0, icon.getRGB(x, 9) >>> 24);
			}
			for (int y = 10; y <= 12; y++)
			{
				assertEquals("row " + y + " opaque at " + x, 255, icon.getRGB(x, y) >>> 24);
			}
		}

		// The strip's parchment at its two top corners, the clan's blue along the line, the lit word.
		assertPixel("parchment", PARCHMENT, icon, 0, 10);
		assertPixel("parchment", PARCHMENT, icon, 15, 10);
		assertPixel("clan blue", CLAN, icon, 1, 11);
		assertPixel("clan blue", CLAN, icon, 8, 11);
		assertPixel("hover blue", HOVER, icon, 9, 11);
		assertPixel("hover blue", HOVER, icon, 10, 11);
		// The title bar and its two cut corners, the window's cut bottom corner.
		assertPixel("hover blue", HOVER, icon, 12, 1);
		assertPixel("hover blue", HOVER, icon, 10, 2);
		assertEquals("title bar corner cut at 10,1", 0, icon.getRGB(10, 1) >>> 24);
		assertEquals("title bar corner cut at 15,1", 0, icon.getRGB(15, 1) >>> 24);
		assertEquals("window corner cut at 10,8", 0, icon.getRGB(10, 8) >>> 24);
		// The window's white and the ink of its two lines.
		assertPixel("white", WHITE, icon, 12, 3);
		assertPixel("white", WHITE, icon, 10, 5);
		assertPixel("ink", INK, icon, 11, 4);
		assertPixel("ink", INK, icon, 14, 4);
		assertPixel("ink", INK, icon, 13, 6);
		assertPixel("white", WHITE, icon, 14, 6);
		// The arrow's tip on the word, and the foot of the arrow.
		assertPixel("ink", INK, icon, 11, 11);
		assertPixel("white", WHITE, icon, 12, 11);
		assertPixel("white", WHITE, icon, 12, 15);
		assertPixel("ink", INK, icon, 13, 15);
		assertPixel("ink", INK, icon, 15, 15);
	}
}

package com.clanhub;

import com.google.gson.Gson;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.ChatMessageType;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.when;

/** {@link OwnLineReader}: the player's valuable drop, untradeable drop and collection log lines each give their item's card. */
public class OwnLineReaderTest
{
	/** An {@link ItemCards} that answers every name with a card titled by it, at the offsets it was given. */
	private static ItemCards echoing()
	{
		final ItemCards itemCards = Mockito.mock(ItemCards.class);
		when(itemCards.forName(anyString(), anyInt(), anyString(), anyInt(), anyInt())).thenAnswer(call ->
			new ItemCard(0, call.getArgument(0), call.getArgument(1), 0L, 0, call.getArgument(2),
				call.getArgument(3), call.getArgument(4)));
		return itemCards;
	}

	@Test
	public void readsValuableUntradeableAndCollectionLogLines()
	{
		// Re-aimed by the lead, 2026-10-08 (lot 8T): the reader takes the tables.
		final OwnLineReader reader = new OwnLineReader(echoing(), () -> true, new CardTables());

		final List<HoverCard> valuable = reader.read(ChatMessageType.GAMEMESSAGE,
			"Valuable drop: Dragon claws (121,453,000 coins)");
		assertEquals(1, valuable.size());
		assertEquals("Dragon claws", valuable.get(0).title());
		assertEquals(1, valuable.get(0).quantity());
		assertEquals(15, valuable.get(0).start());
		assertEquals(27, valuable.get(0).end());

		final List<HoverCard> stack = reader.read(ChatMessageType.GAMEMESSAGE,
			"Valuable drop: 10 x Black knife (4,600 coins)");
		assertEquals(1, stack.size());
		assertEquals(10, stack.get(0).quantity());
		assertEquals("Black knife x10", stack.get(0).title());

		final List<HoverCard> pet = reader.read(ChatMessageType.GAMEMESSAGE, "Untradeable drop: Pet snakeling");
		assertEquals(1, pet.size());
		assertEquals("Pet snakeling", pet.get(0).title());
		final List<HoverCard> valued = reader.read(ChatMessageType.GAMEMESSAGE,
			"Untradeable drop: Pet snakeling (1 coin)");
		assertEquals("Pet snakeling", valued.get(0).title());

		final List<HoverCard> log = reader.read(ChatMessageType.GAMEMESSAGE,
			"New item added to your collection log: Abyssal whip");
		assertEquals(1, log.size());
		assertEquals("Abyssal whip", log.get(0).title());
		assertEquals(39, log.get(0).start());
		assertEquals(51, log.get(0).end());

		assertTrue(reader.read(ChatMessageType.GAMEMESSAGE, "You have been poisoned.").isEmpty());
		assertTrue("only own game lines are read",
			reader.read(ChatMessageType.CLAN_MESSAGE, "Valuable drop: Dragon claws (121,453,000 coins)").isEmpty());
	}

	@Test
	public void aValuableDropWithASourceGivesTheBossCard()
	{
		final String line = "Valuable drop: 45 x Runite ore (456,345 coins) from Duke Sucellus";

		// Re-aimed by the lead, 2026-10-08 (lot 8T): the reader takes the tables.
		final List<HoverCard> both = new OwnLineReader(echoing(), () -> true, new CardTables())
			.read(ChatMessageType.GAMEMESSAGE, line);
		assertEquals("the item's card and the boss's", 2, both.size());
		assertEquals(45, both.get(0).quantity());
		final HoverCard boss = both.get(1);
		assertEquals("Duke Sucellus", boss.title());
		assertEquals("Duke Sucellus", boss.plainLine().substring(boss.start(), boss.end()));
		assertFalse("quiet", boss.marked());

		assertEquals("with the switch off, the item's card alone", 1,
			new OwnLineReader(echoing(), () -> false, new CardTables()).read(ChatMessageType.GAMEMESSAGE, line).size());
		assertEquals("a valuable drop with no source gives one card", 1,
			new OwnLineReader(echoing(), () -> true, new CardTables()).read(ChatMessageType.GAMEMESSAGE,
				"Valuable drop: Dragon claws (121,453,000 coins)").size());
	}

	// Re-aimed by the lead, 2026-10-08 (lot 8U): the wiki's picture replaces the pet.
	@Test
	public void theOwnDropBossCardCarriesTheBoss() throws Exception
	{
		final String line = "Valuable drop: 45 x Runite ore (456,345 coins) from Duke Sucellus";
		final CardTables tables;
		try (Reader cards = new InputStreamReader(OwnLineReaderTest.class.getResourceAsStream(
			"/com/clanhub/cards-fixture.json"), StandardCharsets.UTF_8);
			Reader bosses = new InputStreamReader(OwnLineReaderTest.class.getResourceAsStream(
				"/com/clanhub/bosses-fixture.json"), StandardCharsets.UTF_8))
		{
			tables = CardTables.parse(cards, new Gson()).readBosses(bosses, new Gson());
		}

		final HoverCard boss = new OwnLineReader(echoing(), () -> true, tables)
			.read(ChatMessageType.GAMEMESSAGE, line).get(1);
		assertEquals("one row of facts", 1, boss.rows().size());
		final List<String> facts = new ArrayList<>();
		for (final HoverCard.Pair pair : boss.rows().get(0))
		{
			facts.add(pair.label + " " + pair.value);
		}
		assertEquals(Arrays.asList("Combat 450", "Hitpoints 440", "Max hit 24",
			"Quest Desert Treasure II - The Fallen Empire"), facts);
		assertEquals("no pet: the wiki's picture replaces it", -1, boss.itemId());
		assertTrue("the card asks for the wiki's picture", boss.wikiPicture());
		assertEquals("the combat sprite stands behind it", SkillSprites.spriteOf("Combat"), boss.spriteId());
		assertEquals("Duke Sucellus", boss.title());
		assertEquals("Duke Sucellus", boss.plainLine().substring(boss.start(), boss.end()));
		assertEquals("https://oldschool.runescape.wiki/w/Duke_Sucellus", boss.wikiUrl());
		assertFalse("still quiet", boss.marked());

		final HoverCard bare = new OwnLineReader(echoing(), () -> true, new CardTables())
			.read(ChatMessageType.GAMEMESSAGE, line).get(1);
		assertTrue("a table that has not loaded gives no facts", bare.rows().get(0).isEmpty());
		assertEquals("and no pet", -1, bare.itemId());
		assertTrue("the wiki's picture is asked for all the same", bare.wikiPicture());
		assertEquals("the combat sprite is the picture, as in lot 8R", SkillSprites.spriteOf("Combat"), bare.spriteId());
	}
}

